// The Portuguese of What's new, what each version changed (lib/whats-new.ts, app/whats-new.tsx) (i18n/pt/index.ts).
export const whatsNew: Record<string, string> = {
  "**The day stands out in every chat**: over the first message of each day, groups and Chat with myself too, the day shows in bold between two lines: **Today**, **Yesterday**, the weekday within the last week, and before that the weekday and date. See [Chat through a relay](#relay).":
    "**O dia aparece bem em cada conversa**: acima da primeira mensagem de cada dia, também nos grupos e na Conversa comigo, o dia aparece em negrito entre duas linhas: **Hoje**, **Ontem**, o dia da semana na última semana e, antes disso, o dia da semana com a data. Veja [Conversar por um relay](#relay).",
  "**The microphone writes, if you like**: tap the microphone beside the message field and choose **Speak to write**, and from then on holding it writes what you say into the field, until you choose **Voice message** again. The choice stays for every chat. See [Chat through a relay](#relay).": "**O microfone escreve, se você quiser**: toque no microfone ao lado do campo da mensagem e escolha **Fale para escrever**, e a partir daí, segurando-o, ele escreve no campo o que você diz, até você escolher de novo **Mensagem de voz**. A escolha vale para cada conversa. Veja [Conversar por um relay](#relay).",
  "**Ways on home**: once a relay is set, the line under the top bar of home is **Ways**, with a dot for each way your messages go out by and how many of them wait; a tap opens **Ways**. See [How Erevos picks the path](#paths).": "**Caminhos na tela inicial**: depois que um relay é definido, a linha abaixo da barra de cima da tela inicial é **Caminhos**, com um ponto para cada caminho por onde suas mensagens saem e quantas delas esperam; um toque abre **Caminhos**. Veja [Como o Erevos escolhe o caminho](#paths).",
  "**LoRa makes up for lost pieces, and long texts go shorter**: a text sent by LoRa in several pieces now goes with spare pieces, one for each four, so it comes whole even when a piece or two are lost on the air; older Erevos reads it as before. And long texts are packed, with nothing lost, before they are encrypted, when that makes them go in fewer bytes, to contacts whose Erevos unpacks them. See [Over a LoRa radio](#lora).": "**O LoRa repõe as partes perdidas, e os textos longos vão mais curtos**: um texto enviado por LoRa em várias partes vai agora com partes de reserva, uma por cada quatro, e chega inteiro mesmo que uma ou duas partes se percam no ar; um Erevos mais antigo lê-o como antes. E os textos longos são comprimidos, sem perder nada, antes de serem cifrados, quando assim ocupam menos bytes, para contactos cujo Erevos os descomprime. Vê [Por um rádio LoRa](#lora).",
  "**Ways at a glance**: **Settings** → **Relay and networks** → **Ways** shows each way your messages go out by, the relay, Nostr, the phones nearby, LoRa, SMS and Tor, with how each is now and a line under it: full when it works, faint when it reaches no one now, dashed when it is off. Above them, how many of your messages wait to go, an orange dot for each. Only the space that is open shows, never hidden chats. See [How Erevos picks the path](#paths).": "**Os caminhos de relance**: **Configurações** → **Relay e redes** → **Caminhos** mostra cada caminho por onde suas mensagens saem, o relay, o Nostr, os celulares por perto, o LoRa, o SMS e o Tor, com como cada um está agora e uma linha embaixo: cheia quando funciona, fraca quando agora não alcança ninguém, tracejada quando está desligado. Em cima, quantas mensagens suas estão esperando para sair, um ponto laranja para cada uma. Aparece só o espaço aberto, nunca as conversas ocultas. Veja [Como o Erevos escolhe o caminho](#paths).",
  "**Answer a hidden contact's call with no PIN**: where hidden chats receive while closed, **Answer** on the ringing screen takes their contact's call at once, on a call screen with no name and no face, and the hidden chats stay closed; the small sign and the PIN still open them. See [Hidden chats](#hidden).": "**Atender sem PIN a chamada de um contato oculto**: onde as conversas ocultas recebem quando fechadas, **Atender** na tela da chamada atende na hora, numa tela sem nome nem rosto, e as conversas ocultas continuam fechadas; o pequeno sinal e o PIN ainda as abrem. Veja [Conversas ocultas](#hidden).",
  "**See yourself in a video call**: once their picture comes, yours stays in a small window in the top corner, on both phones; before, it vanished, and each side saw only the other. See [Chat through a relay](#relay).": "**Veja-se numa videochamada**: assim que chega a imagem do outro, a sua fica numa janela pequena no canto de cima, nos dois celulares; antes sumia, e cada lado via só o outro. Veja [Conversar por um relay](#relay).",
  "**Phones nearby are off until you turn them on**: Erevos no longer looks for phones nearby by itself, with Bluetooth, Wi-Fi Aware or on the same Wi-Fi, as on the same Wi-Fi it held a call back for up to a minute before it rang. Turn on **Look for phones nearby** under **Nearby, with no internet**, on **New chat**, to chat and call with no internet. See [Chat with a nearby phone](#nearby).": "**Os celulares por perto ficam desligados até você ligar**: o Erevos não procura mais sozinho celulares por perto, por Bluetooth, Wi-Fi Aware ou na mesma Wi-Fi, porque na mesma Wi-Fi ele segurava uma chamada por até um minuto antes de tocar. Ligue **Procurar celulares por perto** em **Perto, sem internet**, em **Nova conversa**, para conversar e ligar sem internet. Veja [Conversar com um celular por perto](#nearby).",
  "**Open a file with another app**: a file in a chat, a PDF say, has **Open** too, not only **Save**: the phone's app for it reads it from Erevos's memory, with no copy left on the phone. Erevos asks first, and never opens web pages, drawings or app packages that way. See [Chat through a relay](#relay).": "**Abrir um arquivo com outro app**: um arquivo numa conversa, um PDF por exemplo, tem também **Abrir**, não só **Salvar**: o app do celular lê da memória do Erevos, sem que fique uma cópia no celular. O Erevos pergunta antes e nunca abre assim páginas web, desenhos nem pacotes de apps. Veja [Conversar por um relay](#relay).",
  "**Shared chats say how far they are, on both phones**: chats a contact shared from a relay your Erevos does not take from by itself show **Coming, 40%** once you tap them, and their phone says it is taking them; if they did not come, both phones say so and yours buzzes twice. See [Chat through a relay](#relay).": "**Conversas compartilhadas dizem até onde foram, nos dois celulares**: conversas que um contato compartilhou de um relay do qual o seu Erevos não pega sozinho mostram **Chegando, 40%** quando você toca nelas, e o celular dele diz que você está pegando; se não chegaram, os dois celulares dizem e o seu vibra duas vezes. Veja [Conversar por um relay](#relay).",
  "**Calls connect again**: a call that rang no longer stays at **Connecting** on both phones; each phone now waits for its own addresses before it calls or answers. See [Chat through a relay](#relay).": "**As chamadas conectam de novo**: uma chamada que tocou não fica mais em **Conectando** nos dois celulares; cada celular agora espera os próprios endereços antes de ligar ou atender. Veja [Conversar por um relay](#relay).",
  "**A phone beside you brings your messages**: with no internet, an Erevos phone beside yours that has it, and carries for others, takes what waits for you on your relay and hands it over nearby, once you say yes to that phone. It learns your queue there, never what your messages say, and your phone moves to a new queue once it has internet again. Yours does the same for others while **Carry messages for others** is on, as it now is from the start. Never through Tor, and from another relay only once you say yes, warned it sees your address. See [Chat with a nearby phone](#nearby).": "**Um celular ao seu lado traz suas mensagens**: sem internet, um celular com Erevos ao lado do seu que tem, e leva para os outros, pega o que espera por você no seu relay e entrega por perto, depois do seu sim para aquele celular. Ele fica sabendo da sua fila ali, nunca do que dizem suas mensagens, e o seu celular passa para uma fila nova assim que tiver internet de novo. O seu faz o mesmo pelos outros enquanto **Levar mensagens de outras pessoas** está ligado, como agora já vem desde o início. Nunca pelo Tor, e de outro relay só depois do seu sim, avisado de que ele vê o seu endereço. Veja [Conversar com um celular por perto](#nearby).",
  "**A Matrix chat read elsewhere is read here too**: an encrypted Matrix chat you read, or answered, in Element or on another device of yours no longer keeps its count of new messages here. See [Matrix](#matrix).": "**Uma conversa do Matrix lida em outro lugar fica lida aqui também**: uma conversa criptografada do Matrix que você leu ou respondeu no Element ou em outro dispositivo seu não mantém mais aqui o número de mensagens novas. Veja [Matrix](#matrix).",
  "**Matrix rooms with very long messages open**: a message with a very long run of names, dots or dashes, as some public Matrix rooms have, no longer closes Erevos+ as its chat shows it.":
    "**As salas do Matrix com mensagens muito longas abrem**: uma mensagem com uma sequência muito longa de nomes, pontos ou hífenes, como têm algumas salas públicas do Matrix, não fecha mais o Erevos+ quando a conversa a mostra.",
  "**Messenger chats you read stay read**: a Messenger chat you marked read, or wrote in, no longer comes back as unread when Messenger sends it again, after Erevos+ reconnects or starts.":
    "**As conversas do Messenger que você leu continuam lidas**: uma conversa do Messenger que você marcou como lida, ou em que escreveu, não volta mais como não lida quando o Messenger a envia de novo, depois que o Erevos+ se reconecta ou inicia.",
  "**Chats stay where you read**: in Telegram, Matrix, XMPP and Nostr chats, the chat no longer moves by itself to other messages as older ones load above it; it stays at the last message, or where you were reading.":
    "**As conversas ficam onde você lê**: nas conversas do Telegram, Matrix, XMPP e Nostr, a conversa não se move mais sozinha para outras mensagens enquanto as mais antigas carregam acima; ela fica na última mensagem ou onde você estava lendo.",
  "**Erevos+ says its own name, with an icon of its own**: the app and its guide now say Erevos+ everywhere, and its icon is Erevos's mark on a purple tile. Where it speaks of the plain Erevos, it still says Erevos.":
    "**O Erevos+ diz o próprio nome, com um ícone próprio**: o app e o guia agora dizem Erevos+ em todo lugar, e o ícone é a marca do Erevos sobre um quadrado roxo. Onde fala do Erevos simples, continua dizendo Erevos.",
  "**Signal: one chat for each person, with their name**: in Erevos+, a Signal chat shows the person's name, what you send from the phone Erevos+ is linked to shows in the chat of the one you sent it to, and someone who first wrote to your phone number keeps one chat with you on their phone too.":
    "**Signal: uma conversa para cada pessoa, com o nome dela**: no Erevos+, uma conversa do Signal mostra o nome da pessoa, o que você envia do celular ao qual o Erevos+ está vinculado aparece na conversa de quem recebeu, e quem escreveu primeiro para o seu número também mantém uma só conversa com você no celular dela.",
  "**A message's menu always opens**: holding a message, in a chat or a group, opens its menu every time; before, after you had been in another app, it could stop opening until Erevos was closed and opened again.": "**O menu de uma mensagem sempre abre**: ao segurar uma mensagem, em uma conversa ou em um grupo, o menu dela abre toda vez; antes, depois de você passar por outro app, ele podia parar de abrir até você fechar e abrir o Erevos de novo.",
  "**New chat, made anew**: your QR code is on New chat as soon as it opens, with **Scan theirs** and **Share** under it; the field at the top finds a contact by name, or adds someone whose link you paste; and **No Erevos yet?** makes an invite, showing again one no one took yet instead of making another. On a new phone with no relay, New chat starts with **Start with an invite**. The small QR code is new each time and good once: the first to scan it is a contact at once, and anyone after, or with the link you share, writes a message request first. See [Chat through a relay](#relay).": "**Nova conversa, feita de novo**: seu código QR fica em Nova conversa assim que ela abre, com **Ler o da outra pessoa** e **Compartilhar** embaixo; o campo no alto encontra um contato pelo nome, ou adiciona alguém cujo link você cola; e **Ainda não tem o Erevos?** faz um convite, mostrando de novo um que ninguém pegou ainda em vez de fazer outro. Em um celular novo sem relay, Nova conversa começa com **Comece com um convite**. O código QR pequeno é novo a cada vez e vale uma vez: quem o ler primeiro vira contato na hora, e quem vier depois, ou com o link que você compartilha, escreve primeiro um pedido de mensagem. Veja [Conversar por um relay](#relay).",
  "What's new": 'Novidades',
  'What each version changed': 'O que mudou em cada versão',
  'What each version of Erevos changed, the newest first.': 'O que mudou em cada versão do Erevos, da mais nova para a mais antiga.',
  'Not out yet': 'Ainda não lançada',
  'This version': 'Esta versão',
  'For you': 'Para você',
  'Under the hood': 'Nos bastidores',
  "**Chats you have read stay read, on every network**: in Erevos+, Messenger, Signal, Session, Telegram, Matrix, XMPP and Nostr chats you have read no longer notify you again of messages already read, after a restart, a reconnect or when a chat opens. Signal's reads go both ways with the phone it is linked to, and a Nostr chat you answer from another app is read here too.": "**As conversas que leste ficam lidas, em todas as redes**: no Erevos+, as conversas no Messenger, Signal, Session, Telegram, Matrix, XMPP e Nostr que leste já não te avisam outra vez de mensagens já lidas, depois de reiniciar, de voltar a ligar ou ao abrir uma conversa. O que lês no Signal passa nos dois sentidos com o telemóvel a que está ligado, e uma conversa Nostr a que respondes noutra app fica lida aqui também.",
  "**The guide tells of Messenger, Signal and Session**: in Erevos+, the user guide has a section for each, on signing in, chats, groups, calls, notifications, Tor and signing out. See [Messenger](#messenger), [Signal](#signal) and [Session](#session).": "**O guia explica o Messenger, o Signal e o Session**: no Erevos+, o guia tem uma secção para cada um, sobre entrar, conversas, grupos, chamadas, notificações, Tor e sair. Veja [Messenger](#messenger), [Signal](#signal) e [Session](#session).",
  // Not out yet.
  "**New chat asks whether they have Erevos**: over your QR code on **New chat**, choose **Has Erevos already** or **New to Erevos**. The first is your QR code as before, and says that it works only when both phones have a relay; the second shows an invite, which brings in someone new, or someone whose phone has no relay. New chat remembers your choice. See [Chat through a relay](#relay).":
    "**Nova conversa pergunta se a pessoa tem Erevos**: acima do seu código QR em **Nova conversa**, escolha **Já tem Erevos** ou **Novo no Erevos**. O primeiro é o seu código QR como antes, e diz que só funciona se os dois celulares tiverem um relay; o segundo mostra um convite, que traz alguém novo, ou alguém cujo celular não tem relay. Nova conversa lembra a sua escolha. Veja [Conversar por um relay](#relay).",
  "**The keypad lists the contacts it finds, and shows its letters**: on the Phone's **Keypad**, the contacts what you type finds are listed in the room over the number, all of them, not one at a time; and each key shows its letters in the app's language, ΑΒΓ in Greek, ABC in the others. See [Phone](#phone).":
    "**O teclado lista os contatos que encontra, e mostra suas letras**: no **Teclado** do Telefone, os contatos que o que você digita encontra aparecem numa lista no espaço acima do número, todos de uma vez e não um por um; e cada tecla mostra suas letras no idioma do app, ΑΒΓ em grego, ABC nos outros. Veja [Telefone](#phone).",
  "**A phone beside you no longer slows Erevos**: with another Erevos phone near you on the same Wi-Fi, Erevos no longer links to it over Wi-Fi Aware too, which took your phone's Wi-Fi away for moments and slowed your messages and the relay, as if the other phone were far away; and a link to a phone nearby that stopped carrying anything is let go at once, not used on. See [Chat with a nearby phone](#nearby).":
    "**Um celular ao seu lado não deixa mais o Erevos lento**: com outro celular com Erevos perto de você na mesma Wi-Fi, o Erevos não se liga mais a ele também por Wi-Fi Aware, o que tirava por instantes a Wi-Fi do seu celular e atrasava suas mensagens e o relay, como se o outro celular estivesse longe; e uma ligação com um celular por perto que deixou de levar qualquer coisa é largada na hora, em vez de continuar em uso. Veja [Conversar com um celular por perto](#nearby).",
  "**Calls start sooner and sound steadier**: a call through the call relay no longer waits up to 5 seconds on each phone for every way to the relay, only for the first that works; while it goes on, Erevos looks for phones nearby less often, which took the phone's Wi-Fi away for moments and made gaps in the sound; and in a video call, their picture is no longer put aside when their sound came apart from it. See [Chat through a relay](#relay).":
    "**As chamadas começam mais rápido e soam mais estáveis**: uma chamada pelo relay de chamadas não espera mais até 5 segundos em cada celular por cada caminho até o relay, só pelo primeiro que funciona; durante a chamada, o Erevos procura celulares por perto com menos frequência, o que tirava o Wi-Fi do celular por instantes e cortava o som; e numa chamada de vídeo, a imagem da outra pessoa não é mais deixada de lado quando o som dela chegou separado. Veja [Conversar por um relay](#relay).",
  "**Contacts as you dial**: on the Phone's **Keypad**, a contact whose number holds the digits you type, or whose name starts with them on the keys' letters (2 for ABC and ΑΒΓ), shows over the keys: tap it to call. See [Phone](#phone).":
    "**Contatos ao discar**: no **Teclado** do Telefone, um contato cujo número contém os dígitos digitados, ou cujo nome começa com eles nas letras das teclas (2 para ABC e ΑΒΓ), aparece acima das teclas: toque nele para ligar. Veja [Telefone](#phone).",
  "**Chats open at once**: a chat no longer waits, showing your contact as encrypted, for Erevos to finish what it was doing with the relay in the background; it is ready to use as it opens, and holding a message opens its menu, at most a moment later while Erevos says it is still reading what came. See [Chat through a relay](#relay).":
    "**As conversas abrem na hora**: uma conversa não espera mais, mostrando seu contato como criptografado, que o Erevos termine o que fazia com o relay em segundo plano; ela está pronta ao abrir, e segurar uma mensagem abre o menu dela, no máximo um instante depois, enquanto o Erevos diz que ainda está lendo o que chegou. Veja [Conversar por um relay](#relay).",
  "**Pair with a code with no relay yet**: on a phone with no relay yet, **New chat** now has **Pair with a code** too, under your QR code, and opens straight on **Start with an invite** without first showing the screen of a phone with a relay. See [Chat through a relay](#relay).":
    "**Emparelhar com um código sem relay ainda**: num celular ainda sem relay, **Nova conversa** agora também tem **Emparelhar com um código**, abaixo do seu código QR, e abre direto em **Comece com um convite** sem mostrar antes a tela de um celular com relay. Veja [Conversar por um relay](#relay).",
  "**The Public tab says why it shows no Nostr post**: whether the list of people you follow was not found, or they were found but no relay sent their posts, or their posts came but could not be shown, and how each relay answered. Before, it said only that no public posts were found. See [Chats with other Nostr apps](#nostr-chats).":
    "**A aba Público diz por que não mostra nenhuma publicação do Nostr**: se a lista das pessoas que você segue não foi encontrada, se foram encontradas mas nenhum relay enviou as publicações delas, ou se as publicações vieram mas não puderam ser mostradas, e como cada relay respondeu. Antes, dizia só que nenhuma publicação pública foi encontrada. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**A new computer links to the end**: a computer with no relay before linking now takes the phone's answer at once, so linking with the small code finishes by itself, and with the full code **They match** shows. Before, the phone waited for **They match** while the computer showed nothing more until Erevos started again. See [Linked devices](#devices).":
    "**Um computador novo se conecta até o fim**: um computador sem relay antes da conexão agora recebe na hora a resposta do celular, então a conexão com o pequeno código termina sozinha, e com o código completo aparece **São iguais**. Antes, o celular esperava por **São iguais** enquanto o computador não mostrava mais nada até o Erevos ser aberto de novo. Veja [Dispositivos conectados](#devices).",
  "**Sharing into Erevos reaches every service**: **Send to** now lists the chats of your Matrix, XMPP and Nostr accounts too, beside Erevos chats, groups and SMS conversations. A photo or file shared from another app no longer goes missing when Erevos locks as it opens: after the password, **Send to** shows it again, where before it said that nothing came to send. See [Chat through a relay](#relay).":
    "**Compartilhar no Erevos alcança todos os serviços**: **Enviar para** agora lista também as conversas das suas contas de Matrix, XMPP e Nostr, ao lado das conversas do Erevos, dos grupos e das conversas de SMS. Uma foto ou um arquivo compartilhado de outro app não se perde mais quando o Erevos bloqueia ao abrir: depois da senha, **Enviar para** mostra de novo, onde antes dizia que nada chegou para enviar. Veja [Conversar por um relay](#relay).",
  "**Search, media, days and export in Matrix, XMPP, Nostr and SMS**: these chats now have **Search in this chat**, **Media, links and files**, **Go to a day** and **Export chat**, as Erevos chats do, over what your phone keeps of them; an SMS conversation has them under **⋮**. Nothing you search for leaves your phone. See [Getting started](#start).":
    "**Busca, mídia, dias e exportação no Matrix, XMPP, Nostr e SMS**: essas conversas agora têm **Buscar nesta conversa**, **Mídia, links e arquivos**, **Ir para um dia** e **Exportar conversa**, como as conversas do Erevos, sobre o que o seu celular guarda delas; uma conversa de SMS os tem em **⋮**. Nada do que você busca sai do seu celular. Veja [Primeiros passos](#start).",
  "**Styles, cards and video in Matrix, XMPP and Nostr**: these chats now show bold, italic and the other marks for how words look, with tappable links, and send a contact card, a video without where it was filmed, or a photo from the camera at the quality you choose. In groups, @ offers the members; Nostr chats send your location, and a message you forward is marked as forwarded on your phone. See [Matrix](#matrix).":
    "**Estilos, cartões e vídeo no Matrix, XMPP e Nostr**: essas conversas agora mostram negrito, itálico e as outras marcas de como as palavras aparecem, com links para tocar, e enviam um cartão de contato, um vídeo sem o lugar onde foi filmado ou uma foto da câmera na qualidade que você escolher. Nos grupos, @ oferece os membros; as conversas do Nostr enviam sua localização, e uma mensagem que você encaminha fica marcada como encaminhada no seu celular. Veja [Matrix](#matrix).",
  "**Starred messages in every chat**: star a message in Matrix, XMPP, Nostr and SMS too, and find it again under **Starred messages**; save a photo, video, voice message or file that came there to the Collection, and keep a sticker or photo that came as one of your stickers. See [Chat through a relay](#relay).":
    "**Mensagens favoritas em todas as conversas**: favorite uma mensagem também no Matrix, XMPP, Nostr e SMS, e encontre-a de novo em **Mensagens favoritas**; salve na Coleção uma foto, um vídeo, uma mensagem de voz ou um arquivo que chegou lá, e guarde uma figurinha ou foto que chegou como uma das suas figurinhas. Veja [Conversar por um relay](#relay).",
  "**Pin and archive any chat**: hold any chat down on the home screen (an Erevos contact or group, Matrix, XMPP or Nostr) to **Pin to the top**, **Archive** or, on Android, mute it, as SMS conversations already could. Archived chats wait under **Archived** until a new message comes from them. Matrix favourites show pinned, and low-priority rooms come last. A Matrix row shows ✓✓✓ once everyone has read yours. Matrix rooms, XMPP contacts and group MMS can take a name of your own. See [Getting started](#start).":
    "**Fixe e arquive qualquer conversa**: segure qualquer conversa na tela inicial (um contato ou grupo do Erevos, Matrix, XMPP ou Nostr) para **Fixar no topo**, **Arquivar** ou, no Android, silenciá-la, como as conversas por SMS já podiam. As conversas arquivadas esperam em **Arquivadas** até chegar uma mensagem nova delas. Os favoritos do Matrix aparecem fixados, e as salas de prioridade baixa vêm por último. Uma linha do Matrix mostra ✓✓✓ assim que todos leram a sua. Salas do Matrix, contatos do XMPP e MMS em grupo podem ter um nome seu. Veja [Primeiros passos](#start).",
  "**Drafts, Send later and Remind me on Matrix, XMPP and Nostr**: what you type in a chat and do not send stays as its draft, also after Erevos closes, and shows on the chat's row. Hold **Send** down to send a message later from this phone. A Matrix or XMPP message that did not go has **Send again** in its menu, and **Remind me** on a message of any of these chats, SMS too, puts it in Chat with myself with a reminder. See [Matrix](#matrix).":
    "**Rascunhos, Enviar mais tarde e Lembrar-me no Matrix, XMPP e Nostr**: o que você digita numa conversa e não envia fica como rascunho dela, também depois que o Erevos fecha, e aparece na linha da conversa. Segure **Enviar** para enviar uma mensagem mais tarde deste celular. Uma mensagem do Matrix ou XMPP que não saiu tem **Enviar de novo** no menu, e **Lembrar-me** numa mensagem dessas conversas, e do SMS, a coloca em Conversa comigo com um lembrete. Veja [Matrix](#matrix).",
  "**A PIN and screenshots for Matrix, XMPP, Nostr and SMS chats**: lock a chat on Matrix, XMPP or Nostr, or an SMS conversation, with a PIN of its own and block its screenshots, as an Erevos chat; an SMS conversation can also have its own look, be muted, or have a sound of its own. See [Hidden chats](#hidden).":
    "**Um PIN e capturas para conversas do Matrix, XMPP, Nostr e SMS**: bloqueie uma conversa do Matrix, XMPP ou Nostr, ou uma conversa por SMS, com um PIN próprio e bloqueie as capturas de tela dela, como uma conversa do Erevos; uma conversa por SMS também pode ter aparência própria, ser silenciada ou ter um som próprio. Veja [Conversas ocultas](#hidden).",
  "**Chat rules on Matrix, XMPP, Nostr and SMS**: disappearing messages, a timer for the chat or **Disappear** for one message, each chat saying what the other side keeps; **Block** on Matrix and Nostr, with a list of whom you blocked on each service's screen; **Delete** asks **This phone** or **Everyone**; on XMPP, **Appear offline** to one contact; and **Check in person** by QR code on XMPP and Nostr. See [Matrix](#matrix).":
    "**Regras da conversa no Matrix, XMPP, Nostr e SMS**: mensagens temporárias, com um tempo para a conversa ou **Temporária** para uma mensagem, e cada conversa diz o que o outro lado guarda; **Bloquear** no Matrix e Nostr, com uma lista de quem você bloqueou na tela de cada serviço; **Apagar** pergunta **Este celular** ou **Para todos**; no XMPP, **Aparecer offline** para um contato; e **Conferir pessoalmente** por código QR no XMPP e Nostr. Veja [Matrix](#matrix).",
  "**Choose where a call's sound goes**: with a Bluetooth or wired headset connected, **Speaker** in a call becomes **Audio output**, to choose the phone, the speaker or the headset, a Bluetooth one by its own name. A headset connected as a call starts, or during it, takes the sound, as in a phone call. On Android. See [Chat through a relay](#relay).":
    "**Escolha para onde vai o som de uma chamada**: com fones Bluetooth ou com fio conectados, **Alto-falante** numa chamada passa a ser **Saída de áudio**, para escolher o telefone, o alto-falante ou os fones, os Bluetooth pelo próprio nome. Fones conectados ao começar uma chamada, ou durante ela, ficam com o som, como numa chamada telefônica. No Android. Veja [Conversar por um relay](#relay).",
  "**Nothing goes through Tor unless you turn it on**: on Android, **Automatically from your relay** under **Home relay** is now off in a new space, so a space no longer takes its relay's paired relay as a home relay through Tor by itself; turn it on there if you want it. Turning it off now also lets go of the home relay it took, so Tor does not run for it. See [Home relay](#home-relay).":
    "**Nada passa pelo Tor a menos que você o ligue**: no Android, **Automaticamente pelo seu relay** em **Relay de casa** agora vem desligado num espaço novo, então um espaço não pega mais sozinho o relay pareado com o seu relay como relay de casa pelo Tor; ligue-o lá se quiser. Desligá-lo agora também larga o relay de casa que ele pegou, para o Tor não rodar por ele. Veja [Relay de casa](#home-relay).",
  "**Your relays first, Nostr only after them**: a text to a contact who reads on Nostr now goes through your relay, then their home relays, then your home relay, and through the public Nostr relays only when none of them took it. Before, it went to the Nostr relays first and through your relay only when they were slow or did not take it. See [Through Nostr](#nostr).":
    "**Primeiro os seus relays, o Nostr só depois**: um texto para um contato que lê no Nostr agora passa pelo seu relay, depois pelos relays de casa do contato, depois pelo seu relay de casa, e pelos relays Nostr públicos só quando nenhum deles o aceitou. Antes, ele ia primeiro aos relays Nostr e pelo seu relay só quando eles eram lentos ou não o aceitavam. Veja [Pelo Nostr](#nostr).",
  "**One chat only through Tor**: on Android, **Through Tor** in an Erevos chat's **Details** sends that chat's messages and files only through Tor, on circuits of its own, whatever the space's Tor setting. It is off unless you turn it on, and calls do not go through Tor. See [Through Tor](#tor).":
    "**Uma só conversa pelo Tor**: no Android, **Pelo Tor** nos **Detalhes** de uma conversa do Erevos envia as mensagens e os arquivos dessa conversa só pelo Tor, em circuitos próprios, seja qual for a configuração de Tor do espaço. Fica desativado a menos que você ative, e as chamadas não passam pelo Tor. Veja [Pelo Tor](#tor).",
  "**One chat only through Tor reaches Nostr too**: a chat with **Through Tor** on in its **Details** now sends and reads its Nostr texts only through Tor, and its photos and files on Nostr file servers too, even when the space's Tor is **Nothing**; Tor is started for it, and what goes waits for it. Until your contact first writes to the chat's own queue, their first messages come to the space's own queue, which is read the space's way. Before, with the space's Tor off, such a chat's texts could reach the public Nostr relays straight, and they saw the phone's internet address. See [Through Tor](#tor).":
    "**Uma só conversa pelo Tor chega também ao Nostr**: uma conversa com **Pelo Tor** ativado nos seus **Detalhes** agora envia e lê os textos Nostr dela só pelo Tor, e as fotos e os arquivos dela em servidores de arquivos Nostr também, mesmo quando o Tor do espaço é **Nada**; o Tor é iniciado para ela, e o que sai espera por ele. Até o seu contato escrever pela primeira vez na fila própria da conversa, as primeiras mensagens dele chegam à fila do espaço, que é lida do jeito que o espaço diz. Antes, com o Tor do espaço desativado, os textos de uma conversa assim podiam chegar direto aos relays Nostr públicos, que viam o endereço de internet do celular. Veja [Pelo Tor](#tor).",
  "**Through Tor on your linked devices too**: a chat's **Through Tor** switch, set in its **Details**, now reaches your linked devices (your computer, the web app and Jolla) and back: switched on or off on any of them, it is switched everywhere. On a linked device that chat's messages, files and send-later messages then go only through Tor too, on the chat's own circuits, never straight; so do the copies that go to your contact's other devices. The web app has no Tor: there a chat with the switch on sends nothing while it is on, and the switch is shown so it can be turned off. A device on an older version never turns it off anywhere; it learns a change made elsewhere at that contact's next change. Before, it was only on the phone where you set it. See [Through Tor](#tor).":
    "**Pelo Tor também nos seus dispositivos conectados**: o interruptor **Pelo Tor** de uma conversa, definido nos seus **Detalhes**, agora chega aos seus dispositivos conectados (o seu computador, o app web e o Jolla) e volta: ativado ou desativado em um deles, fica assim em todos. Num dispositivo conectado, as mensagens, os arquivos e as mensagens para enviar mais tarde dessa conversa passam então também só pelo Tor, pelos circuitos próprios da conversa, nunca direto; o mesmo vale para as cópias que vão para os outros dispositivos do seu contato. O app web não tem Tor: lá uma conversa com o interruptor ativado não envia nada enquanto estiver ativado, e o interruptor aparece para poder ser desativado. Um dispositivo com uma versão mais antiga nunca o desativa em lugar nenhum; ele fica sabendo de uma mudança feita em outro lugar na próxima mudança desse contato. Antes, valia só no celular onde você o definia. Veja [Pelo Tor](#tor).",
  "**Nostr has its own Tor switch**: the **Nostr** screen now has **Nostr through Tor**, **On** or **Off**, off unless you turn it on. **On**, Erevos reaches the Nostr relays and the Nostr file servers only through Tor, and starts Tor for it even when the space's Tor is **Nothing**; a text that goes there waits while Tor starts. It only adds Tor: with the space's Tor on, or for a chat set to **Through Tor**, Nostr goes through Tor whatever it says. Before, Nostr only followed the space's Tor setting, and the screen only said whether it was on. See [Through Nostr](#nostr).":
    "**O Nostr tem um botão de Tor próprio**: a tela **Nostr** agora tem **Nostr pelo Tor**, **Ativado** ou **Desativado**, desativado a menos que você ative. **Ativado**, o Erevos acessa os relays Nostr e os servidores de arquivos Nostr só pelo Tor e inicia o Tor para isso, mesmo quando o Tor do espaço é **Nada**; um texto que vai para lá espera enquanto o Tor inicia. Isso só acrescenta o Tor: com o Tor do espaço ativado, ou para uma conversa com **Pelo Tor**, o Nostr passa pelo Tor seja o que for que ele diga. Antes, o Nostr só seguia a configuração de Tor do espaço, e a tela só dizia se estava ativado. Veja [Pelo Nostr](#nostr).",
  "**Erevos warns before your internet address can be seen**: once before the first message, voice message or file in an Erevos chat that can go without Tor, with **Through Tor for this chat** to fix it or **Go on**; before the first message in an Erevos group that can go without Tor; before a call, as calls never go through Tor, unless the contact is nearby on the same network; before fetching a file from a server your contact chose; and in every **Open this link?** question, where the site sees the address. Each has a **Guide** button. Before, Erevos did not say it. See [Who sees your internet address](#ip).":
    "**O Erevos avisa antes que o seu endereço de internet possa ser visto**: uma vez antes da primeira mensagem, mensagem de voz ou arquivo numa conversa do Erevos que pode ir sem Tor, com **Pelo Tor para esta conversa** para resolver ou **Prosseguir**; antes da primeira mensagem num grupo do Erevos que pode ir sem Tor; antes de uma chamada, pois as chamadas nunca passam pelo Tor, a menos que o contato esteja perto na mesma rede; antes de baixar um arquivo de um servidor que seu contato escolheu; e em toda pergunta **Abrir este link?**, em que o site vê o endereço. Cada aviso tem um botão **Guia**. Antes, o Erevos não dizia isso. Veja [Quem vê o seu endereço de internet](#ip).",
  "**A Tor switch of their own**: backups to a server, the Collection's server copy, radio and TV lists, link previews and updates each have a **Through Tor** switch in their own screen, off unless you turn it on. On, that goes only through Tor, whatever the space's Tor setting, and waits while Tor starts; nothing goes straight. Off, it goes as before. It only adds Tor. For updates, the switch makes the daily new-version notice and **Check for updates** ask the web app's server instead of GitHub; a new version is told, but it does not download through Tor: to install it, turn the switch off for a moment. Playing a radio station or a TV channel always goes straight. Before, backups, the Collection and radio and TV followed only the space's Tor setting, and link previews and updates never went through Tor. See [Who sees your internet address](#ip).":
    "**Uma chave de Tor para cada um**: os backups para um servidor, a cópia da Coleção em um servidor, as listas de rádio e TV, as prévias de links e as atualizações têm cada um uma chave **Pelo Tor** na sua própria tela, desligada a menos que você a ligue. Ligada, isso vai só pelo Tor, seja qual for a definição de Tor do espaço, e espera enquanto o Tor inicia; nada vai direto. Desligada, vai como antes. Ela só acrescenta o Tor. Nas atualizações, a chave faz o aviso diário de versão nova e **Procurar atualizações** perguntarem ao servidor do app web em vez do GitHub; uma versão nova é avisada, mas não baixa pelo Tor: para instalar, desligue a chave por um momento. Tocar uma estação de rádio ou um canal de TV vai sempre direto. Antes, os backups, a Coleção e o rádio e a TV só seguiam a definição de Tor do espaço, e as prévias de links e as atualizações nunca passavam pelo Tor. Veja [Quem vê o seu endereço de internet](#ip).",
  "**Bare web addresses open too**: t.me/name, example.org/page and the like are now tappable in every chat, as in Telegram and Signal, and show whole before they open; e-mail addresses and file names are not. See [Chat through a relay](#relay).":
    "**Endereços web simples também abrem**: t.me/name, example.org/page e parecidos agora podem ser tocados em todas as conversas, como no Telegram e no Signal, e aparecem inteiros antes de abrir; endereços de e-mail e nomes de arquivo não. Veja [Conversar por um relay](#relay).",
  "**Read marks no longer go missing**: when you read a message and put the phone away at once, the other person still learns that you read it, at Erevos's next look, also after Erevos was closed. Before, it could stay at ✓✓ for them for good.": "**As marcas de leitura não se perdem mais**: quando você lê uma mensagem e guarda o telefone logo em seguida, a outra pessoa ainda fica sabendo que você leu, na próxima olhada do Erevos, também depois que o Erevos foi fechado. Antes, podia ficar em ✓✓ para ela para sempre.",
  "**Backups are checked**: after each automatic backup Erevos reads it back from the folder, opens it with its password, makes sure every part it names is there, of its size, and reads two of them through. On a server it looks at the listing only. **Check now** under Backups also downloads the server’s newest backup and ten of its parts; a part missing or damaged shows in red. **Full check of the folder** compares every part there with its SHA-256, on the phone. See [Backups](#backup).":
    "**As cópias são verificadas**: depois de cada cópia automática, o Erevos volta a lê-la da pasta, abre-a com a sua palavra-passe, confirma que cada parte que nomeia está lá, com o seu tamanho, e lê duas delas por inteiro. Num servidor só olha para a lista. **Verificar agora**, em Cópias de segurança, descarrega também a cópia mais recente do servidor e dez das suas partes; uma parte em falta ou danificada aparece a vermelho. **Verificação completa da pasta** compara cada parte lá com o seu SHA-256, no telefone. Ver [Cópias de segurança](#backup).",
  "**A new first start**: the first screen now says what you do not give, no phone number, email, user name or account, and asks for a name for your contacts, if you want one. After the modules comes a short screen for each, with how to begin with it and what Android should allow for it, **Allow all, one by one** among it; then the password lock and backups, then what is ready and what is missing. **I already have Erevos on another phone** goes straight to restoring a backup. See [Modules](#modules).":
    "**Um novo primeiro início**: a primeira tela agora diz o que você não entrega, nem número de telefone, nem e-mail, nem nome de usuário, nem conta, e pede um nome para seus contatos, se você quiser um. Depois dos módulos vem uma tela curta para cada um, com como começar com ele e o que o Android deve permitir para ele, com **Permitir tudo, um por um** entre isso; depois o bloqueio com senha e os backups, e depois o que está pronto e o que falta. **Eu já tenho o Erevos em outro celular** vai direto para a restauração de um backup. Veja [Módulos](#modules).",
  "**Leftovers**: photos and files that nothing names any more, as those of an import that stopped in its middle, can now be found and deleted, under Backups → **Leftovers**. Type the PIN of each of your hidden chats and the password of any other space, tap **Find leftovers**, and Erevos shows how much none of them names; **Delete them** deletes it once you say so. See [Backups](#backup).":
    "**Restos**: fotos e ficheiros que já nada nomeia, como os de uma importação que parou a meio, podem agora ser encontrados e apagados, em Cópias de segurança → **Restos**. Escreve o PIN de cada uma das tuas conversas ocultas e a palavra-passe de qualquer outro espaço, toca em **Procurar restos**, e o Erevos mostra quanto nenhum deles nomeia; **Apagá-los** apaga-o assim que confirmares. Ver [Cópias de segurança](#backup).",
  "**An import that stops leaves nothing behind**: when Erevos stops while it brings in the photos and files of a Telegram, WhatsApp or Viber export, as when Android closes it or the battery runs out, what it had written of them is deleted the next time it starts. Before, it stayed on the phone, and in every backup, for good. See [Imported chats](#import).":
    "**Uma importação interrompida não deixa nada para trás**: quando o Erevos para enquanto traz as fotos e ficheiros de uma exportação do Telegram, WhatsApp ou Viber, como quando o Android o fecha ou a bateria acaba, o que já tinha escrito é apagado no arranque seguinte. Antes ficava no telefone, e em cada cópia de segurança, para sempre. Ver [Conversas importadas](#import).",
  // 7.0.0-rc.7
  "**What takes room**: Backups now have **What takes room**, which shows on Android how much room Erevos takes on the phone, by kind: the Collection with the chats' photos and files, voice messages, chat history, Tor, and what writes that did not end left over. Each automatic backup holds it all, so it tells why one is large. See [Backups](#backup).":
    "**O que ocupa espaço**: as cópias de segurança têm agora **O que ocupa espaço**, que mostra no Android quanto espaço o Erevos ocupa no telefone, por tipo: a Coleção com as fotos e ficheiros das conversas, as mensagens de voz, o histórico, o Tor e os restos de escritas que não terminaram. Cada cópia automática contém tudo isto, assim vê-se porque é grande. Ver [Cópias de segurança](#backup).",
  "**Backups to a server get there again**: a backup to your own server, such as a Nextcloud, no longer stops when the server misses one of its pieces for a moment, as when it closes for a few minutes at night. That piece goes again a little later and the backup carries on; before, it started over the next time, and a large backup could fail day after day. See [Backups](#backup).":
    '**Os backups para um servidor voltam a chegar**: um backup para o seu próprio servidor, como um Nextcloud, não para mais quando o servidor deixa de aceitar por um momento uma das partes, como quando fecha por alguns minutos à noite. Essa parte vai de novo um pouco depois e o backup continua; antes, ele recomeçava na vez seguinte, e um backup grande podia falhar dia após dia. Veja [Backups](#backup).',
  // 7.0.0-rc.6
  "**Photos and files from the Collection, straight from a chat**: **+** in a chat now has **Collection**, which opens the Collection of that chat's place, its photos and its other files. Tap what to send, then **Send**, and it goes in the chat. Before, **Photo** opened only the phone's own gallery. See [Collection](#collection).":
    "**Fotos e arquivos da Coleção, direto de uma conversa**: **+** numa conversa agora tem **Coleção**, que abre a Coleção do lugar dessa conversa, com as fotos e os outros arquivos dela. Toque no que quer enviar e depois em **Enviar**, e vai para a conversa. Antes, **Foto** abria só a galeria do celular. Veja [Coleção](#collection).",
  "**A chat opens at its last message again**: opened from the home screen or a notification, a chat could stop above its newest messages, often above the unread ones. Now it goes to its end at once, and once more as its messages come into view.":
    "**Uma conversa volta a abrir na última mensagem**: aberta da tela inicial ou de uma notificação, uma conversa podia parar acima das mensagens mais novas, muitas vezes acima das não lidas. Agora ela vai na hora até o fim, e mais uma vez assim que as mensagens aparecem.",
  "**A new sign-in to a relay is no longer undone**: after you signed in to your relay again, a chat screen open from before could later write back the token from before, which the relay no longer lets in, and the relay then refused this phone. Now the new token is kept at once, and every chat screen open takes it. See [Chat through a relay](#relay).":
    "**Entrar de novo no relay não é mais desfeito**: depois que você entrava de novo no seu relay, uma tela de conversa aberta de antes podia mais tarde gravar de volta o token anterior, que o relay não deixa mais entrar, e o relay então recusava este celular. Agora o novo token é guardado na hora, e toda tela de conversa aberta passa a usá-lo. Veja [Conversar por um relay](#relay).",
  // 7.0.0-rc.5
  "**A message sent offline is no longer lost when you leave the chat**: what you sent while your chats were still opening, as they do for a while with no connection, was lost if you left the chat before it went. Now it waits, marked **Waiting**, and goes by itself once the relay or their phone nearby can take it, a voice message too. See [Chat through a relay](#relay).":
    "**Uma mensagem enviada sem conexão não se perde mais quando você sai da conversa**: o que você enviava enquanto suas conversas ainda abriam, como fazem por um tempo sem conexão, se perdia se você saísse da conversa antes de ela ir. Agora ela fica marcada **Aguardando** e vai sozinha assim que o relay ou o celular da pessoa por perto puder pegá-la, uma mensagem de voz também. Veja [Conversar por um relay](#relay).",
  // 7.0.0-rc.4
  "**No more freezing after a space opens**: while an automatic backup was made, the screen could stop answering for minutes. Now the backup's files are written, listed and deleted in their folder away from the screen, and its parts are checked natively, many times faster.":
    '**Chega de travamentos quando um espaço abre**: enquanto um backup automático era feito, a tela podia parar de responder por minutos. Agora os arquivos do backup são escritos, listados e apagados na pasta deles, longe da tela, e suas partes são verificadas de forma nativa, muitas vezes mais rápido.',
  // 7.0.0-rc.3
  "**Your SMS on your computer**: the phone's SMS can now show on this space's linked devices too, a computer, a browser or a tablet, end-to-end encrypted: read them there and answer, and the phone sends the answer. The latest 50 conversations go, each with its latest 50 messages; photos stay on the phone. Off until you turn it on, on the phone, under Settings → Phone and SMS → SMS → **On my linked devices too**. See [SMS](#sms).":
    "**Os seus SMS no computador**: os SMS do celular agora podem aparecer também nos dispositivos conectados deste espaço, um computador, um navegador ou um tablet, com criptografia de ponta a ponta: lá você os lê e responde, e o celular envia a resposta. Vão as últimas 50 conversas, cada uma com as suas últimas 50 mensagens; as fotos ficam no celular. Desativado até você ativar, no celular, em Configurações → Telefone e SMS → SMS → **Também nos meus dispositivos conectados**. Veja [SMS](#sms).",
  "**TV in the Collection**: the Collection's new **TV** tab plays TV channels from IPTV lists (.m3u), by their link or from a file, or from iptv-org's public list of free channels, by country or whole, in their groups, with a search, on Android, on a computer and in a browser. There is no programme guide, logos show only if you turn them on, and a channel's name and link, or a radio station's, can be sent to a chat. See [Collection](#collection).":
    "**TV na Coleção**: a nova aba **TV** da Coleção toca canais de TV de listas IPTV (.m3u), pelo link ou de um arquivo, ou da lista pública de canais gratuitos do iptv-org, por país ou inteira, nos seus grupos, com busca, no Android, no computador e em um navegador. Não há guia de programação, os logotipos só aparecem se você ligá-los, e o nome e o link de um canal, ou de uma estação de rádio, podem ser enviados para uma conversa. Veja [Coleção](#collection).",
  "**Radio that keeps playing**: when a station's server, or a proxy on the way, drops the stream, or the network goes for a moment, Erevos asks the station again by itself, a few seconds later, instead of stopping.":
    "**Rádio que continua tocando**: quando o servidor de uma estação, ou um proxy no caminho, corta o fluxo, ou a rede cai por um instante, o Erevos reconecta sozinho alguns segundos depois, em vez de parar.",
  "**Radio playlists with many stations**: in the Collection's Radio, **Add a station** takes a playlist link (.m3u, .pls) that names many stations and adds each of them, and **Import a playlist file** adds the stations of a .m3u or .pls file from your device. Only stations with an https link are added, and Erevos says how many were left out.":
    "**Playlists de rádio com muitas estações**: no Rádio da Coleção, **Adicionar uma estação** aceita um link de playlist (.m3u, .pls) com muitas estações e adiciona todas, e **Importar um arquivo de playlist** adiciona as estações de um arquivo .m3u ou .pls do seu aparelho. Só estações com link https são adicionadas, e o Erevos diz quantas ficaram de fora.",
  "**Block screenshots in a chat**: in a chat's details, **Block screenshots** keeps screenshots and screen recordings of it out on both phones, on Android, and either of you can turn it off again. Erevos on an iPhone, on a computer, in a browser or on Sailfish cannot block them, and says so. See [Chat through a relay](#relay).":
    "**Bloquear capturas de tela em uma conversa**: nos detalhes de uma conversa, **Bloquear capturas de tela** impede capturas e gravações de tela dela nos dois celulares, no Android, e qualquer um de vocês pode desativar de novo. O Erevos em um iPhone, em um computador, em um navegador ou no Sailfish não consegue bloqueá-las, e avisa. Veja [Conversar por um relay](#relay).",
  "**Every chat in its own look**: groups, Chat with myself and chats on Matrix, XMPP and Nostr now have **Chat look** too, as a contact's chat had, for that chat only. See [Chat through a relay](#relay).":
    "**Cada conversa com a sua aparência**: os grupos, a Conversa comigo e as conversas no Matrix, XMPP e Nostr agora também têm **Aparência da conversa**, como tinha a conversa de um contato, só para essa conversa. Veja [Conversar por um relay](#relay).",
  "**Letters and text size**: Settings → Appearance has **Letters** (the style's own, the phone's, serif or monospace) and the messages' **Text size**, for the whole app or, from **Chat look**, for one chat. See [Appearance](#appearance).":
    "**Tipo de letra e tamanho do texto**: Configurações → Aparência tem **Tipo de letra** (a do estilo, a do telefone, com serifa ou monoespaçada) e o **Tamanho do texto** das mensagens, para todo o app ou, em **Aparência da conversa**, para uma conversa. Veja [Aparência](#appearance).",
  "**Muting hidden Matrix, XMPP and Nostr chats**: a hidden place's own Matrix, XMPP and Nostr chats can now be muted, as hidden chats are, and then say nothing at all. See [Hidden chats](#hidden).":
    "**Silenciar conversas ocultas do Matrix, XMPP e Nostr**: as conversas das contas próprias de Matrix, XMPP e Nostr de um lugar oculto agora podem ser silenciadas, como as conversas ocultas, e então não dizem nada. Veja [Conversas ocultas](#hidden).",
  "**Say when I open Erevos**: with **Last seen** on, opening Erevos now tells your contacts at once, without waiting for a message: only those you talked with in the last 30 days who show their own time too, each after a random wait of up to a minute, at most every 15 minutes. The relay can then tell when you open Erevos: turn it off under Settings → Privacy and security → Last seen, or in a chat's details. See [Chat through a relay](#relay).":
    "**Avisar quando eu abrir o Erevos**: com **Visto por último** ligado, abrir o Erevos agora avisa seus contatos na hora, sem esperar uma mensagem: só aqueles com quem você conversou nos últimos 30 dias que também mostram o próprio horário, cada um depois de uma espera aleatória de até um minuto, no máximo a cada 15 minutos. O relay pode então saber quando você abre o Erevos: desligue em Configurações → Privacidade e segurança → Visto por último, ou nos detalhes de uma conversa. Veja [Conversar por um relay](#relay).",
  "**Moving to a new phone**: a new chapter of the guide takes you step by step from the old phone to the new one with one backup: what to get ready, what comes over, what to set again, and wiping the old one at the end. See [Moving to a new phone](#new-phone).":
    "**Mudar para um celular novo**: um novo capítulo do guia leva você passo a passo do celular antigo para o novo com um só backup: o que preparar, o que vai junto, o que configurar de novo, e apagar o antigo no fim. Veja [Mudar para um celular novo](#new-phone).",
  '**A lost phone**: if the phone a backup came from was lost or stolen and may still be on, **The old phone was lost** under Settings → Data and devices → Backups moves every space and its hidden chats to new relay queues, so that phone reads nothing more of yours there, and tells your contacts quietly. The contact links and QR codes you gave before work for 14 more days. See [Backups](#backup).':
    '**Um celular perdido**: se o celular de onde veio um backup foi perdido ou roubado e ainda pode estar ligado, **O celular antigo foi perdido**, em Configurações → Dados e dispositivos → Backups, passa cada espaço e suas conversas ocultas para filas novas do relay, para esse celular não ler mais nada seu lá, e avisa os seus contatos em silêncio. Os links de contato e os QR codes que você deu antes valem por mais 14 dias. Veja [Backups](#backup).',
  '**Restored chats go on by themselves**: after a backup is restored, a chat that went on after the backup was made starts a new conversation with the contact by itself, so you no longer give each other your links again, but with a contact on an older Erevos. See [Backups](#backup).':
    '**As conversas restauradas seguem sozinhas**: depois de restaurar um backup, uma conversa que continuou depois do backup começa sozinha uma conversa nova com o contato, então vocês não precisam mais trocar de novo os seus links, exceto com um contato de um Erevos mais antigo. Veja [Backups](#backup).',
  '**Backups every 6 hours, and lighter**: automatic backups can now come every 6 hours too, made while Erevos is open and as it goes to the background. Each one writes and sends only the photos, files and voice messages that are new, and names again those of the backups before it: keep the whole backup folder together. See [Backups](#backup).':
    '**Backups a cada 6 horas, e mais leves**: os backups automáticos agora também podem ser feitos a cada 6 horas, enquanto o Erevos está aberto e ao ir para o segundo plano. Cada um escreve e envia só as fotos, os arquivos e as mensagens de voz que são novos, e nomeia de novo os dos backups anteriores: mantenha junta a pasta toda dos backups. Veja [Backups](#backup).',
  '**Linked devices after a restore**: the phone a backup was restored on can ask the computers and browsers the old phone had linked to link again: tap **Ask to link again** under Settings → Data and devices → Linked devices, then **Link again** on the device. It keeps its chats, with no code to scan. See [Backups](#backup).':
    '**Dispositivos conectados depois de uma restauração**: o celular em que um backup foi restaurado pode pedir aos computadores e navegadores que o celular antigo tinha conectado que se conectem de novo: toque em **Pedir para conectar de novo** em Configurações → Dados e dispositivos → Dispositivos conectados, depois em **Conectar de novo** no dispositivo. Ele mantém as conversas dele, sem código para ler. Veja [Backups](#backup).',
  "**The phone's calls in backups**: on Android, **Put the calls in backups** under Backups adds the call history and Android's blocked numbers to your backups, and restoring adds back those the phone lacks. Off until you turn it on. See [Backups](#backup).":
    '**As chamadas do celular nos backups**: no Android, **Incluir as chamadas nos backups**, em Backups, acrescenta aos seus backups o histórico de chamadas e os números bloqueados do Android, e restaurar devolve os que faltam ao celular. Desligado até você ligar. Veja [Backups](#backup).',
  "**Groups after a restore**: a member restored from a backup asks the group's admin to put it in again, which works while the group moved on only a little.":
    '**Grupos depois de uma restauração**: um membro restaurado de um backup pede ao administrador do grupo que o ponha de novo, o que funciona enquanto o grupo avançou só um pouco.',
  "**The time of a message that waited**: a message that waited on the relay, as for a computer or for hidden chats that were closed, now shows when it was sent, not when it came. From an Erevos before this version it still shows when it came.":
    "**A hora de uma mensagem que esperou**: uma mensagem que esperou no relay, como para um computador ou para conversas ocultas fechadas, mostra agora quando foi enviada, não quando chegou. De um Erevos anterior a esta versão continua a mostrar quando chegou.",
  // 7.0.0-rc.2
  "**Find radio stations by name**: Add a station in the Collection's Radio tab searches Radio Browser, a free directory, sent only the words you type when you press Search. See [Collection](#collection).":
    "**Encontre estações pelo nome**: Adicionar uma estação na aba Rádio da Coleção busca no Radio Browser, um diretório livre, que recebe só as palavras que você digita quando aperta Buscar. Veja [Coleção](#collection).",
  "**Internet radio in the Collection**: a Radio tab with stations you add by their https link, kept encrypted with the Collection, played like the music, with the notice on the phone. The station sees your device's IP address. See [Collection](#collection).":
    "**Rádio pela internet na Coleção**: uma aba Rádio com estações que você adiciona pelo link https delas, criptografadas com a Coleção, tocadas como a música, com a notificação no telefone. A estação vê o endereço IP do seu aparelho. Veja [Coleção](#collection).",
  "**Music and videos of any size in the desktop app's Collection**: they play and seek at once, read a piece at a time from their encrypted pieces, never held whole in memory. See [Collection](#collection).":
    "**Músicas e vídeos de qualquer tamanho na Coleção do app de computador**: tocam e avançam na hora, lidos um pedaço por vez dos seus pedaços criptografados, nunca inteiros na memória. Veja [Coleção](#collection).",
  "**Playlists in the Collection's Music**: songs in the order you choose, kept encrypted with the Collection, played in order or shuffled. Make one at the top of Music, and add songs from their menu or by holding them down. See [Collection](#collection).":
    "**Playlists na Música da Coleção**: músicas na ordem que você escolhe, criptografadas com a Coleção, tocadas em ordem ou em ordem aleatória. Crie uma no alto de Música, e adicione músicas pelo menu delas ou segurando-as. Veja [Coleção](#collection).",
  "**Subtitles for the Collection's videos**: an .srt or .vtt file in the same folder with the video's name (film.srt, or film.en.srt) shows as its subtitles, and a tap at the top turns them off or on. See [Collection](#collection).":
    "**Legendas para os vídeos da Coleção**: um arquivo .srt ou .vtt na mesma pasta com o nome do vídeo (film.srt, ou film.en.srt) aparece como suas legendas, e um toque no alto as desliga ou liga. Veja [Coleção](#collection).",
  "**A player's screen for the Collection**: tap the bar of the music playing, or **Now playing**, for its cover, title, artist and album, a bar to move in it, previous and next, **Shuffle**, **Repeat** (all or one), the speed from 0.5× to 2×, and the list, to tap another. A video, or music of 10 minutes or more, starts where you left it. The notification shows the title and cover only with **Show the title in the notification** on. See [Collection](#collection).":
    "**Uma tela de reprodução para a Coleção**: toque na barra da música que está tocando, ou em **Tocando agora**, para ver a capa, o título, o artista e o álbum, uma barra para se mover nela, anterior e próxima, **Aleatório**, **Repetir** (tudo ou uma), a velocidade de 0.5× a 2× e a lista, para tocar outra. Um vídeo, ou uma música de 10 minutos ou mais, começa onde você parou. A notificação mostra o título e a capa só com **Mostrar o título na notificação** ligado. Veja [Coleção](#collection).",
  "**Photos, Videos, Music and Files**: the Collection has a tab for each, each with the folders that hold any of its files above it. See [Collection](#collection).":
    "**Fotos, Vídeos, Música e Arquivos**: a Coleção tem uma aba para cada um, com em cima as pastas que têm algo dela. Veja [Coleção](#collection).",
  "**Music of the Collection goes on with the screen off**: on Android, music could stop a while after the screen went off. Now the player is kept in the foreground for as long as the list plays. See [Collection](#collection).":
    "**A música da Coleção continua com a tela desligada**: no Android, a música podia parar um tempo depois de a tela apagar. Agora o player fica em primeiro plano enquanto a lista toca. Veja [Coleção](#collection).",
  "**More music and video formats in the Collection**: on Android MP3, AAC, M4A, FLAC, Ogg, Opus, WAV, AMR, MP4, MKV, WebM and 3GP play, also a file that came with no type, known by its name's ending, and seeking works in an MP3 with no table of its seconds. See [Collection](#collection).":
    "**Mais formatos de música e vídeo na Coleção**: no Android tocam MP3, AAC, M4A, FLAC, Ogg, Opus, WAV, AMR, MP4, MKV, WebM e 3GP, também um arquivo que chegou sem tipo, reconhecido pelo final do nome, e pular para um ponto funciona também num MP3 sem tabela dos seus segundos. Veja [Coleção](#collection).",
  "**New modules on after an update**: where the modules were chosen before the Collection came, as on a phone or computer updated from 6, the Collection stayed off. Now it is on there, as is any module that comes later, until you turn it off in Settings → General → Modules. See [Modules](#modules).":
    "**Módulos novos ativados após uma atualização**: onde os módulos foram escolhidos antes de a Coleção chegar, como num celular ou computador atualizado da 6, a Coleção ficava desativada. Agora ela fica ativada lá, como qualquer módulo que chegar depois, até você desativá-la em Configurações → Geral → Módulos. Veja [Módulos](#modules).",
  "**A home relay by itself**: on Android, when your relay names a relay paired with it, a space with no home relay takes that one, only through Tor, with its token from a coupon: nothing to type. **Automatically from your relay**, under Settings → Relay and networks → Home relay, turns it off. See [Home relay](#home-relay).":
    "**Um relay de casa sozinho**: no Android, quando o seu relay nomeia um relay pareado com ele, um espaço sem relay de casa pega esse, só por Tor, com o token dele de um cupom: nada para digitar. **Automaticamente pelo seu relay**, em Configurações → Relay e redes → Relay de casa, desliga isso. Veja [Relay de casa](#home-relay).",
  "**A chip for every part that is on**: above the chats, **SMS**, **Erevos**, **Matrix**, **XMPP** and **Nostr** each have their chip whenever they are on in Modules, also with no chat yet. Before, in a space with only SMS so far, choosing **All messages** after Erevos's icon opened its chats hid the chips, with no way back.":
    "**Um chip para cada parte ligada**: acima das conversas, **SMS**, **Erevos**, **Matrix**, **XMPP** e **Nostr** têm cada um o seu chip sempre que estão ligados em Módulos, também sem nenhuma conversa ainda. Antes, em um espaço só com SMS até agora, escolher **Todos** depois que o ícone do Erevos abria suas conversas escondia os chips, sem como voltar.",
  "**Invite at one tap**: on the home screen, **Invite** beside the relay's line shows an invite's QR code at once, with nothing to type: who it is for and your name for them can be typed below it, or never. See [Chat through a relay](#relay).":
    "**Convidar com um toque**: na tela inicial, **Convidar** ao lado da linha do relay mostra na hora o código QR de um convite, sem digitar nada: para quem é e seu nome para essa pessoa podem ser digitados abaixo, ou nunca. Veja [Conversar por um relay](#relay).",
  "**Sign in with LPHL without typing a code**: on Android, once you sign in on the page the browser opened, tap **Open Erevos** there, and Erevos finishes signing in by itself. The code to type is still on the page, in case nothing opens. It needs the relay updated. See [Chat through a relay](#relay).":
    "**Entrar com LPHL sem digitar um código**: no Android, depois de entrar na página que o navegador abriu, toque em **Abrir o Erevos** lá, e o Erevos termina de entrar sozinho. O código para digitar continua na página, caso nada abra. Precisa do relay atualizado. Veja [Conversar por um relay](#relay).",
  "**Invites and contact links by touch**: on an Android phone with NFC, while **Invite someone** or **My QR code** shows the small QR code, hold the back of their phone to the back of yours: their phone opens it by itself, in Erevos where it is installed. See [Chat through a relay](#relay).":
    "**Convites e links de contato por toque**: num telefone Android com NFC, enquanto **Convidar alguém** ou **Meu código QR** mostra o código QR pequeno, encoste a parte de trás do telefone da pessoa na do seu: o telefone dela o abre sozinho, no Erevos se estiver instalado. Veja [Conversar por um relay](#relay).",
  "**Smaller invite QR codes**: the QR code of **Invite someone** now holds about eight times less, so simpler and older cameras read it too, and its link is short enough for an SMS. It opens Erevos's page for invites, which offers Erevos and then opens the invite in it. Where your relay lets this phone make no invite, the long one is still made. See [Chat through a relay](#relay).":
    "**Códigos QR de convite menores**: o código QR de **Convidar alguém** agora contém cerca de oito vezes menos, então câmeras mais simples e antigas também o leem, e seu link é curto o bastante para um SMS. Ele abre a página de convites do Erevos, que oferece o Erevos e depois abre o convite nele. Onde seu relay não deixa este telefone fazer convites, o longo continua sendo feito. Veja [Conversar por um relay](#relay).",
  "**A small contact QR code**: **Show my QR code** now shows your contact link in short, so any camera reads it, and **Share my contact link** sends a link any app lets you tap. Whoever scans it while it shows is your contact at once; later, they write a message request first. **Large QR code, for no internet** shows the whole one, for near with no internet. See [Chat through a relay](#relay).":
    "**Um código QR de contato pequeno**: **Mostrar meu código QR** agora mostra seu link de contato em curto, então qualquer câmera o lê, e **Compartilhar meu link de contato** envia um link que qualquer app deixa tocar. Quem o lê enquanto ele aparece vira seu contato na hora; mais tarde, escreve primeiro um pedido de mensagem. **Código QR grande, sem internet** mostra o inteiro, para perto e sem internet. Veja [Conversar por um relay](#relay).",
  "**Links open Erevos**: on Android, an invite or contact link tapped in any app opens Erevos, which asks before it takes it, once the web server and a new Erevos are both out. See [Chat through a relay](#relay).":
    "**Links abrem o Erevos**: no Android, um link de convite ou de contato tocado em qualquer app abre o Erevos, que pergunta antes de aceitá-lo, quando o servidor web e um Erevos novo tiverem saído. Veja [Conversar por um relay](#relay).",
  "**Home relay**: the screen no longer says that whoever runs a home relay sees this phone's address when it is set to **Only through Tor**.":
    "**Relay de casa**: a tela não diz mais que quem cuida de um relay de casa vê o endereço deste celular quando ele está em **Só por Tor**.",
  "**An invite that opened Erevos for the first time** opens once the first start's setup is done, however long it took; before, after five minutes on the setup screens it was lost.":
    "**Um convite que abriu o Erevos pela primeira vez** abre quando a configuração da primeira inicialização termina, não importa quanto demore; antes, depois de cinco minutos nas telas de configuração, ele se perdia.",
  // 7.0.0-rc.1
  "**Linked devices on the same Wi-Fi**: the phone and a computer on the same Wi-Fi or hotspot give each other what changes straight there, with no internet too. See [Linked devices](#devices).":
    "**Dispositivos conectados no mesmo Wi-Fi**: o celular e um computador no mesmo Wi-Fi ou hotspot passam um ao outro o que muda direto ali, também sem internet. Veja [Dispositivos conectados](#devices).",
  "**Your Matrix, XMPP and Nostr accounts on every linked device**: each device linked gets them by itself, with no choice to make, and they follow as they change on the phone: one you sign out of there, or replace with another, goes from the devices too. See [Linked devices](#devices).":
    "**Suas contas Matrix, XMPP e Nostr em cada dispositivo conectado**: cada dispositivo conectado as recebe sozinho, sem nada para escolher, e elas seguem as mudanças no celular: a conta da qual você sai lá, ou troca por outra, sai também dos dispositivos. Veja [Dispositivos conectados](#devices).",
  "**Same settings on your linked devices**: the language, the look and Last seen changed on the phone or a computer change on the others too. A photo behind the screens, passwords, PINs and what is about one device alone stay on each. A device can keep its own: **Same settings on every device** in Linked devices. See [Linked devices](#devices).":
    "**As mesmas configurações nos seus dispositivos conectados**: o idioma, a aparência e Visto por último mudados no celular ou em um computador mudam também nos outros. Uma foto atrás das telas, as senhas, os PINs e o que diz respeito a um só dispositivo ficam em cada um. Um dispositivo pode manter as suas: **As mesmas configurações em todos os dispositivos** em Dispositivos conectados. Veja [Dispositivos conectados](#devices).",
  "**Last seen**: when a contact is not online, their chat says when they last had Erevos open, to the minute. It goes end-to-end encrypted, never to the relay. It is on, and both ways: turn it off in Settings → Privacy and security → Last seen, and no one sees yours, nor you theirs. Hidden chats have their own time and their own switch, in a chat's details there. See [Chat through a relay](#relay).":
    "**Visto por último**: quando um contato não está online, a conversa dele diz quando ele abriu o Erevos pela última vez, até o minuto. Vai criptografado de ponta a ponta, nunca para o relay. Fica ativado, e nos dois sentidos: desative em Configurações → Privacidade e segurança → Visto por último, e ninguém vê o seu, nem você o deles. As conversas ocultas têm a sua própria hora e o seu próprio interruptor, nos detalhes de uma conversa de lá. Veja [Conversar por um relay](#relay).",
  "**One Public feed**: the new **Public** chip on the home screen shows the public posts of the Nostr people you follow and the public Matrix rooms you are in as one feed, as in Amethyst, with photos inside the posts and a card for a link. Answer, share again, like, share and write new posts with photos; for Matrix, answer, react and share. **Photos** chooses whether photos come at once, only through Tor or on a tap. The **Nostr** chip shows only the Nostr chats again. See [Chats with other Nostr apps](#nostr-chats).":
    "**Um só feed público**: o novo botão **Público** da tela inicial mostra num só feed, como no Amethyst, as publicações públicas das pessoas do Nostr que você segue e as salas Matrix públicas em que você está, com as fotos dentro das publicações e um cartão para um link. Responda, compartilhe de novo, curta, compartilhe e escreva novas publicações com fotos; no Matrix, responda, reaja e compartilhe. **Fotos** escolhe se as fotos vêm na hora, só pelo Tor ou com um toque. O botão **Nostr** volta a mostrar só as conversas Nostr. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Collection**: an encrypted place in every space and hidden place for photos, files and folders, with its icon next to the lock. Turn it on in Modules. See [Collection](#collection).":
    "**Coleção**: um lugar criptografado em cada espaço e em cada lugar oculto para fotos, arquivos e pastas, com o ícone dela ao lado do cadeado. Ative-a em Módulos. Veja [Coleção](#collection).",
  "**Music, videos and PDFs in the Collection**: music and videos play from their encrypted pieces, music on with the screen off and with play, pause, next and previous on the lock screen, and PDFs read page by page inside Erevos. **Open with another app** leaves no plain copy, and a photo or video picked from the gallery can be deleted there after importing. See [Collection](#collection).":
    "**Músicas, vídeos e PDFs na Coleção**: músicas e vídeos tocam dos seus pedaços criptografados, a música também com a tela apagada, com reproduzir, pausar, próximo e anterior na tela de bloqueio, e os PDFs são lidos página por página dentro do Erevos. **Abrir com outro app** não deixa cópia sem criptografia, e uma foto ou um vídeo da galeria pode ser apagado de lá depois de importar. Veja [Coleção](#collection).",
  "**The Collection on a computer**: in the desktop app for Linux, macOS and Windows the Collection keeps your photos and files encrypted too. Photos, PDFs, music and videos open in memory only, never as a plain copy on the disk, and close when the space locks. **Save to the computer** asks first. See [Collection](#collection).":
    "**A Coleção no computador**: no app para computador para Linux, macOS e Windows a Coleção também guarda suas fotos e arquivos criptografados. Fotos, PDFs, músicas e vídeos abrem só na memória, nunca como cópia sem criptografia no disco, e fecham quando o espaço bloqueia. **Salvar no computador** pergunta antes. Veja [Coleção](#collection).",
  "**Files up to 4 GB in the Collection**: on Android a file picked from the phone's files is encrypted as it is read, with no plain copy first, so it comes in faster and needs no room twice. In the desktop app music and videos up to 1 GB play. See [Collection](#collection).":
    "**Arquivos de até 4 GB na Coleção**: no Android, um arquivo escolhido nos arquivos do telefone é criptografado enquanto é lido, sem cópia sem criptografia antes, então entra mais rápido e não precisa do dobro de espaço. No app para computador, músicas e vídeos de até 1 GB tocam. Veja [Coleção](#collection).",
  "**The Collection on a WebDAV server**: each space and hidden place can copy its Collection, still encrypted, to a folder on a server you choose, Nextcloud, ownCloud or any that speaks WebDAV, so big files are not only on the phone. Only what is new goes, and a phone that lacks a file fetches it from there. See [Collection](#collection).":
    "**A Coleção num servidor WebDAV**: cada espaço e cada lugar oculto pode copiar a sua Coleção, ainda cifrada, para uma pasta num servidor que escolhes, Nextcloud, ownCloud ou qualquer um que fale WebDAV, para que os ficheiros grandes não estejam só no telemóvel. Só vai o que é novo, e um telemóvel a que falte um ficheiro vai buscá-lo lá. Vê [Coleção](#collection).",
  "**The Collection on your linked devices**: turn on **On my linked devices too** in a Collection's settings and that Collection goes to the space's or hidden place's linked devices, changes and deletions with it. Small pictures come at once, a file itself on the same Wi-Fi or when you open it, a piece at a time, going on where it stopped after the network drops. See [Collection](#collection).":
    "**A Coleção nos seus dispositivos conectados**: ative **Também nos meus dispositivos conectados** nas configurações de uma Coleção e essa Coleção vai para os dispositivos conectados do espaço ou lugar oculto, com mudanças e exclusões. As miniaturas chegam na hora, o arquivo em si na mesma Wi-Fi ou quando você o abre, pedaço por pedaço, continuando de onde parou se a rede cair. Veja [Coleção](#collection).",
  "**Groups stay on the device you choose**: on the phone, under Linked devices → Groups stay on, move the groups to a linked computer. Their keys go there, never copied, so the groups work there with the phone off and new ones can be made there; members see nothing new. See [Linked devices](#devices).":
    "**Os grupos ficam no dispositivo que você escolher**: no celular, em Dispositivos conectados → Os grupos ficam em, mova os grupos para um computador conectado. As chaves deles vão para lá, nunca copiadas, então os grupos funcionam lá com o celular desligado e dá para criar novos lá; os membros não veem nada novo. Veja [Dispositivos conectados](#devices).",
  "**Add someone new on a linked device without the phone**: a computer adds someone whose contact link is from this version by itself, with the phone off, and writes to them at once; they see your account as a request, with the same safety number, and the phone adds them too once it is on. See [Linked devices](#devices).":
    "**Adicione alguém novo num dispositivo conectado sem o celular**: um computador adiciona sozinho alguém cujo link de contato é desta versão, com o celular desligado, e escreve para a pessoa na hora; ela vê sua conta como uma solicitação, com o mesmo número de segurança, e o celular a adiciona também assim que liga. Veja [Dispositivos conectados](#devices).",
  "**Calls and Send later on your linked devices without the phone**: with a contact on this version, a computer calls and is called by itself and sends a message for later itself, with the phone off, and a copy goes to each of their devices too, held till its time. Every device of yours shows what is scheduled, and deleting it on any of them takes it back everywhere. See [Linked devices](#devices).":
    "**Chamadas e Enviar mais tarde nos seus dispositivos conectados sem o celular**: com um contato nesta versão, um computador liga e recebe chamadas sozinho e envia ele mesmo uma mensagem para mais tarde, com o celular desligado, e uma cópia vai também para cada dispositivo dele, guardada até a hora. Cada dispositivo seu mostra o que está agendado, e apagá-lo em qualquer um o cancela em todos. Veja [Dispositivos conectados](#devices).",
  '**Support Erevos**: every way has its QR code now, Liberapay and PayPal too, and PayPal opens in the browser.':
    '**Apoiar o Erevos**: cada forma tem agora o seu código QR, também o Liberapay e o PayPal, e o PayPal abre no navegador.',
  '**Chats open at their end**: a long chat, or one with imported messages, could open at a message read long ago, often a photo, as it drew earlier messages on its way to the end. Now it opens at the newest message, and the arrow to where you left off is there when new ones came.':
    '**As conversas abrem no fim**: uma conversa longa, ou uma com mensagens importadas, podia abrir numa mensagem lida há muito tempo, muitas vezes uma foto, porque carregava mensagens anteriores a caminho do fim. Agora ela abre na mensagem mais recente, e a seta para onde você parou está lá quando chegaram novas.',
  "**Tor off unless you turn it on**: a new space sends nothing through Tor, so messages go fastest, and turning Tor on asks first, as it makes them slower. A space you already have keeps its choice, under Settings → Relay and networks → Tor. Texts through Nostr now go without Tor too: then the Nostr relays see your phone's internet address, never who wrote to whom. See [Through Tor](#tor).":
    "**Tor desativado até você ativar**: um espaço novo não envia nada pelo Tor, então as mensagens vão mais rápido, e ativar o Tor pergunta antes, pois as deixa mais lentas. Um espaço que você já tem mantém a escolha dele, em Configurações → Relay e redes → Tor. Os textos pelo Nostr agora também vão sem o Tor: então os relays Nostr veem o endereço de internet do seu celular, nunca quem escreveu para quem. Veja [Pelo Tor](#tor).",
  "**Moving a chat to a space with no relay**: **Move to another space** stopped there, as that space had no relay of its own. Now it offers this space's relay, which that space then keeps, and it makes that space's relay queue when it has a relay but no queue yet. See [Second password](#second).":
    "**Mover uma conversa para um espaço sem relay**: **Mover para outro espaço** parava aí, porque esse espaço não tinha relay próprio. Agora oferece o relay deste espaço, que esse espaço depois mantém, e cria a fila desse espaço no relay quando tem relay mas ainda não tem fila. Veja [Segunda senha](#second).",
  "**Fixes from a review of all the code**: a message you were typing stays with its chat when you open another, and never shows in a PIN-locked chat's place; a locked chat under a locked group stays out of screenshots when the group closes; the Collection's catalogue goes into backups, so a restored phone opens its files; calls in a public group reach their members; a Matrix or XMPP account no longer stops for good at one bad message or an unreachable server; a message sent for later stays listed while its details are still coming; the computer app's Wi-Fi link refuses an impossible port; and the panic button lets the apps it tells start before it closes.":
    "**Correções de uma revisão de todo o código**: uma mensagem que estava a escrever fica com a sua conversa quando abre outra, e nunca aparece no lugar de uma conversa com PIN; uma conversa bloqueada por baixo de um grupo bloqueado fica fora das capturas de ecrã quando o grupo fecha; o catálogo da Coleção entra nas cópias de segurança, para que um telemóvel restaurado abra os seus ficheiros; as chamadas num grupo público chegam aos seus membros; uma conta Matrix ou XMPP já não pára para sempre numa mensagem danificada ou num servidor inalcançável; uma mensagem para mais tarde continua na lista enquanto os seus dados ainda chegam; a ligação Wi-Fi da aplicação de computador recusa uma porta impossível; e o botão de pânico deixa as aplicações que avisa arrancarem antes de fechar.",
  "**Safer in twelve more ways, from the review before 7**: a message the relay hands you is deleted there only once your phone has kept it, so a connection cut at that moment loses nothing (an older relay works as before); a relay keeps a bound on what it holds in all and for each phone; in a public group no one can have another member taken out by claiming to be them; with SMS invites off, no one becomes a contact from your number alone; searches that find nothing are forgotten after a quarter of an hour; a Matrix message is shown as its sender's only when the key came from their device, else as **Not verified**, and an XMPP or Matrix device that changes its key gets nothing until you accept it, while a new device is said in the chat; a photo or file from a server its sender chose is fetched by itself only through Tor, else on a tap; an old first packet replayed to you never takes over a chat; and your linked devices' log takes each device's changes only from that device, and forgets devices that are gone.":
    "**Mais seguro de doze maneiras a mais, da revisão antes da 7**: uma mensagem que o relay lhe entrega só é apagada lá depois de o seu telemóvel a ter guardado, por isso uma ligação cortada nesse momento não perde nada (um relay mais antigo funciona como antes); um relay mantém um limite ao que guarda no total e por cada telemóvel; num grupo público ninguém consegue mandar expulsar outro membro fazendo-se passar por ele; com os convites por SMS desligados, ninguém vira contacto só pelo seu número; as pesquisas que nada encontram são esquecidas ao fim de um quarto de hora; uma mensagem Matrix é mostrada como do seu remetente só quando a chave veio do dispositivo dele, senão como **Não verificado**, e um dispositivo XMPP ou Matrix que muda de chave não recebe nada até o aceitar, enquanto um dispositivo novo é anunciado na conversa; uma foto ou um ficheiro de um servidor escolhido pelo remetente só vem sozinho por Tor, senão com um toque; um primeiro pacote antigo reenviado nunca toma uma conversa; e o registo dos seus dispositivos ligados só aceita as alterações de cada dispositivo vindas desse dispositivo, e esquece os que se foram.",
  "**A home relay only through Tor**: switch a home relay to **Only through Tor** and it never sees your phone's address, whatever Tor is set to for the rest. With no token typed, it gives one for a coupon that your relay signs blind, so neither relay can tell whose it is, and two spaces can use each other's relays as home relays with nothing tying them together. The token comes within the hour, lasts 90 days, and Erevos renews it by itself. Needs Tor, on Android. See [Home relay](#home-relay).":
    '**Um relay de casa só pelo Tor**: coloque um relay de casa em **Só pelo Tor** e ele nunca vê o endereço do seu celular, seja qual for a configuração do Tor para o resto. Sem token digitado, ele dá um por um cupom que o seu relay assina às cegas, então nenhum dos dois relays consegue saber de quem é, e dois espaços podem usar os relays um do outro como relays de casa sem nada que os ligue. O token vem dentro de uma hora, dura 90 dias e o Erevos o renova sozinho. Precisa do Tor, no Android. Veja [Relay de casa](#home-relay).',
  // 6.0.0-rc.2
  "**Home's buttons stay at the bottom**: after the password, home's **Remind me** and **New chat** could float halfway up the screen, over the chats, with the list ending above them, until Erevos went away and came back. Now the screen asks Android at once whether a keyboard is open. See [Password lock](#lock).":
    "**Os botões da tela inicial ficam embaixo**: depois da senha, **Lembrar-me** e **Nova conversa** podiam flutuar no meio da tela, sobre as conversas, com a lista terminando acima deles, até sair do Erevos e voltar. Agora a tela pergunta na hora ao Android se há um teclado aberto. Veja [Bloqueio com senha](#lock).",
  "**The Nostr tab's posts come**: **Posts** could stay on **Looking…** for good through Tor. Each wait through Tor took one of the threads the whole app shares, and once all were taken, every look-up of the posts waited behind the others; a relay that answered and then could not be reached kept them waiting with no end. Now Tor's waits have threads of their own, a relay that cannot be reached is let be after 20 seconds, and the posts come within about two minutes at most, with what was found by then. See [Chats with other Nostr apps](#nostr-chats).":
    "**As publicações da aba Nostr chegam**: **Publicações** podia ficar para sempre em **Procurando…** pelo Tor. Cada espera pelo Tor ocupava uma das threads que o app inteiro compartilha, e quando todas estavam ocupadas, cada busca das publicações esperava atrás das outras; um relay que respondeu e depois não pôde mais ser alcançado as deixava esperando sem fim. Agora as esperas do Tor têm threads próprias, um relay que não pode ser alcançado é deixado de lado depois de 20 segundos, e as publicações chegam em cerca de dois minutos no máximo, com o que foi encontrado até então. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Linux, Windows and macOS again**: 6.0.0-rc.1 came out without them: the check that each build for computers opens did not know the setup of Erevos's very first start. Now it does.":
    "**De novo Linux, Windows e macOS**: a 6.0.0-rc.1 saiu sem eles: a verificação de que cada versão para computador abre não conhecia a configuração do primeiríssimo início do Erevos. Agora conhece.",
  // 6.0.0-rc.1
  "**Links open on Sailfish OS**: **Sign in with LPHL**, a donation page or a link in a chat opened nothing there. Now Sailfish OS opens them: a web page in the browser, a number in the phone or the messages, an address in the mail.":
    "**Os links abrem no Sailfish OS**: **Entrar com LPHL**, uma página de doação ou um link numa conversa não abriam nada. Agora o Sailfish OS abre-os: uma página web no navegador, um número no telefone ou nas mensagens, um endereço no email.",
  "**Matrix, and photos and files in XMPP and Nostr chats, on Sailfish OS**: Erevos there could not reach their servers over HTTPS, so Matrix could not sign in, photos and files neither came nor went, and links showed no preview. Now they work as on a computer.":
    "**Matrix, e fotos e arquivos nas conversas XMPP e Nostr, no Sailfish OS**: lá o Erevos não alcançava os servidores deles por HTTPS, então o Matrix não conseguia entrar, fotos e arquivos não chegavam nem saíam e os links não mostravam prévia. Agora funcionam como num computador.",
  "**A phone call shows its screen**: with Erevos as the phone app, a call that came could ring with the phone's screen black, so it could not be answered, when Android's full-screen notifications for Erevos, Erevos's notices or its notices of incoming calls were off. Now the call screen comes up by itself, over the lock screen too, and turns the screen on. A call that Do Not Disturb holds back still comes quietly, with the screen off. See [Phone](#phone).":
    "**Uma chamada telefônica mostra a sua tela**: com o Erevos como app de telefone, uma chamada recebida podia tocar com a tela preta, sem poder ser atendida, quando estavam desativadas as notificações em tela cheia do Android para o Erevos, as notificações do Erevos ou as notificações dele de chamadas recebidas. Agora a tela de chamada aparece sozinha, também sobre a tela de bloqueio, e acende a tela. Uma chamada que o \"Não perturbe\" segura continua chegando em silêncio, com a tela apagada. Veja [Telefone](#phone).",
  "**The calculator shows a long result from its start**: upright, a result with many decimals hid its first digits, which showed only with the phone turned sideways. Now a long number gets smaller to fit, its first digits always in sight.":
    "**A calculadora mostra um resultado longo desde o início**: na vertical, um resultado com muitas casas decimais escondia os primeiros dígitos, que só apareciam com o telefone na horizontal. Agora um número longo fica menor até caber, com os primeiros dígitos sempre à vista.",
  "**Pick the recipient of a new SMS from your contacts**: **New SMS** has a **Contacts** button that opens your contacts with a search, and typing a name or number suggests the contacts that match. A contact with several numbers shows a line for each, and for a group MMS each one you pick is added. With only the SMS open, only the phone's contacts show. See [SMS](#sms).":
    "**Escolha o destinatário de um novo SMS entre os contatos**: **Novo SMS** tem um botão **Contatos** que abre seus contatos com busca, e ao digitar um nome ou número aparecem os contatos que combinam. Um contato com vários números mostra uma linha para cada um, e em um MMS em grupo cada contato escolhido é acrescentado. Com só os SMS abertos, aparecem só os contatos do telefone. Veja [SMS](#sms).",
  "**More for a number in the Phone**: on the keypad, **⋯** beside a typed number offers **Add to contacts**, **Add to an existing contact**, **Send an SMS** and **Copy the number**. **Recents** and **Favourites** offer **Copy the number** and **Open the contact**; **Favourites** also **Send an SMS**, and **Recents** adds an unknown number to an existing contact. With Erevos locked, the Phone still only calls. See [Phone](#phone).":
    "**Mais para um número no Telefone**: no teclado, **⋯** ao lado de um número digitado oferece **Adicionar aos contatos**, **Adicionar a um contato existente**, **Enviar um SMS** e **Copiar o número**. **Recentes** e **Favoritos** oferecem **Copiar o número** e **Abrir o contato**; **Favoritos** também **Enviar um SMS**, e **Recentes** junta um número desconhecido a um contato existente. Com o Erevos bloqueado, o Telefone continua só a ligar. Veja [Telefone](#phone).",
  "**A short buzz on touch**: the keys of the keypad, **Call**, **End**, Send, the keyboard's Enter, switches and menus that open give a short buzz. **Settings** → **Appearance** → **Vibrate on touch** turns it off. See [Appearance](#appearance).":
    "**Uma vibração curta ao tocar**: as teclas do teclado, **Ligar**, **Encerrar**, Enviar, o Enter do teclado, os interruptores e os menus que se abrem dão uma vibração curta. Em **Configurações** → **Aparência** → **Vibrar ao tocar** você a desliga. Veja [Aparência](#appearance).",
  "**A number on each icon, on Huawei and Honor**: their launchers now show a number on each of Erevos's icons apart, with **Number on the icon** on: on Erevos's own the messages, on SMS's the SMS not read, on Phone's the missed calls, on Contacts's a birthday today. Most other launchers, such as those of Pixel and GrapheneOS, Samsung's and Kvaesitso, give a notice's dot or number to all of an app's icons alike, and Erevos cannot change that there. See [Appearance](#appearance).":
    "**Um número em cada ícone, em Huawei e Honor**: os launchers deles agora mostram um número em cada ícone do Erevos à parte, com **Número no ícone** ligado: no do Erevos as mensagens, no do SMS os SMS não lidos, no do Telefone as chamadas perdidas, no dos Contatos um aniversário de hoje. A maioria dos outros launchers, como os dos Pixel e do GrapheneOS, o da Samsung e o Kvaesitso, dá o ponto ou o número de uma notificação a todos os ícones de um app por igual, e ali o Erevos não pode mudar isso. Veja [Aparência](#appearance).",
  "**Choose the parts of Erevos you use**: Erevos's own chats, the Phone, the SMS, and the chats with Nostr, Matrix and XMPP apps are modules now, any of them on, Erevos's own too, at least one. One that is off does not start and shows nowhere, and the Phone's and the SMS's icons leave the phone's apps: Erevos is lighter, opens faster and uses less battery. Nothing of it is deleted: it is all there again when it is back on. Erevos's very first start sets it up as an installer does, its language, the modules and what Android should allow for them; a module turned on later asks for its permissions again. After this update every module stays on until you change them in **Settings** → **General** → **Modules**. See [Modules](#modules).":
    "**Escolha as partes do Erevos que você usa**: as conversas do próprio Erevos, o Telefone, os SMS e as conversas com apps Nostr, Matrix e XMPP agora são módulos, qualquer um deles pode ficar ativado, o do próprio Erevos também, pelo menos um. Um desativado não inicia e não aparece em lugar nenhum, e os ícones do Telefone e dos SMS saem dos apps do celular: o Erevos fica mais leve, abre mais rápido e gasta menos bateria. Nada dele é apagado: tudo volta quando ele é ativado de novo. O primeiríssimo início do Erevos o configura como um instalador faz, o idioma, os módulos e o que o Android deve permitir para eles; um módulo ativado depois pede suas permissões de novo. Depois desta atualização, todos os módulos continuam ativados até você mudá-los em **Configurações** → **Geral** → **Módulos**. Veja [Módulos](#modules).",
  "**Public posts in the Nostr tab**: on the home screen, the Nostr tab shows first **Posts**, the public posts of the people your Nostr key follows and what they shared again, newest first, as in Amethyst or a Telegram channel, with **Chats** one tap away. Older ones come as you scroll to the end, the newest when you pull the list down; tap who wrote a post for their posts or to write to them. Read only, looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Publicações públicas na aba Nostr**: na tela inicial, a aba Nostr mostra primeiro **Publicações**, as publicações públicas das pessoas que a sua chave Nostr segue e o que elas compartilharam de novo, das mais recentes às mais antigas, como no Amethyst ou num canal do Telegram, com **Conversas** a um toque. As mais antigas chegam quando você rola até o fim, as mais recentes quando você puxa a lista para baixo; toque em quem escreveu uma publicação para ver as publicações dessa pessoa ou para escrever para ela. Somente leitura, buscadas pelo Tor como diz o espaço e não guardadas, e nenhuma imagem ou link é aberto. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Hidden chats on your linked devices**: each place of hidden chats now links on its own, from inside it, to the same place on a computer or in a browser, with **Linked devices** under its list. Its chats, messages, groups, calls, Chat with myself and its own Matrix, XMPP and Nostr accounts go there, and its contacts write to it there directly. Nothing of it shows in the space or on the space's linked devices. The link runs while the place is open, and while it is closed too with **Receive while closed** on. See [Linked devices](#devices).":
    "**Conversas ocultas nos seus dispositivos conectados**: cada posição de conversas ocultas agora se conecta por conta própria, de dentro, à mesma posição num computador ou num navegador, com **Dispositivos conectados** abaixo da lista dela. As conversas, mensagens, grupos, chamadas, a Conversa comigo e as contas próprias de Matrix, XMPP e Nostr dela vão para lá, e os contatos dela escrevem para ela lá diretamente. Nada disso aparece no espaço nem nos dispositivos conectados do espaço. A conexão funciona enquanto a posição está aberta, e fechada também com **Receber quando fechadas** ligado. Veja [Dispositivos conectados](#devices).",
  "**Move a chat to another space**: in a chat's **Details**, **Move to another space** takes it, with its messages, name, picture, look and imported chats, into the space whose password you type, as a move into hidden chats does: the safety number stays the same, and their phone is told at once to write there. That space stays closed, and the row shows in every space. A chat never takes the place of one that space, or hidden chats, already have with the same person. See [Second password](#second).":
    "**Mover uma conversa para outro espaço**: nos **Detalhes** de uma conversa, **Mover para outro espaço** a leva, com as mensagens, o nome, a imagem, a aparência e as conversas importadas, para o espaço cuja senha você digita, como ao mover para conversas ocultas: o número de segurança continua o mesmo, e o celular da pessoa é avisado na hora para escrever para lá. Esse espaço continua fechado, e a opção aparece em todo espaço. Uma conversa nunca toma o lugar de outra que esse espaço, ou conversas ocultas, já tenham com a mesma pessoa. Veja [Segunda senha](#second).",
  // 4.0.0-rc.10
  "**Erevos no longer stops when only the SMS or the Contacts are open**: from them, a contact's chat, an SMS, another icon or a screen that asks for the password again could make Erevos say it could not open (Maximum call stack size exceeded). Now the password opens all of Erevos, then that screen. And when Erevos cannot open, **Try again** starts it again. See [Password lock](#lock).":
    "**O Erevos não para mais quando só os SMS ou os contatos estão abertos**: a partir deles, a conversa de um contato, um SMS, outro ícone ou uma tela que pede a senha de novo podiam fazer o Erevos dizer que não conseguiu abrir (Maximum call stack size exceeded). Agora a senha abre todo o Erevos e depois essa tela. E quando o Erevos não consegue abrir, **Tentar de novo** o inicia outra vez. Veja [Bloqueio com senha](#lock).",
  "**Each icon opens what it names**: after Erevos was opened by the SMS icon, or from the recent apps, another icon, the widget or a notice could sometimes show the SMS instead. Now each opens what it names. With only the SMS or the Contacts open, another icon asks for the password as when Erevos is locked, then opens its own part: the Contacts icon only the contacts, Erevos's own icon all of it. And Back on Erevos's first screen now puts it behind, as Home does, whatever opened it. See [Password lock](#lock).":
    "**Cada ícone abre o que indica**: depois que o Erevos foi aberto pelo ícone de SMS ou a partir dos apps recentes, outro ícone, o widget ou um aviso podiam às vezes mostrar os SMS no lugar. Agora cada um abre o que indica. Quando só os SMS ou os contatos estão abertos, outro ícone pede a senha como quando o Erevos está bloqueado e depois abre a sua própria parte: o ícone de Contatos só os contatos, o ícone do próprio Erevos todo o Erevos. E Voltar na primeira tela do Erevos agora o deixa em segundo plano, como o botão de início, seja o que for que o abriu. Veja [Bloqueio com senha](#lock).",
  // 4.0.0-rc.9
  "**Only the Contacts**: with Erevos locked, the Contacts icon, the widget's Contacts button and the notice of a birthday ask for the password, then open only the contacts. A chat, an SMS, Settings, and the orange padlock **Unlock everything**, ask for it again, then open all of Erevos. See [Password lock](#lock).":
    "**Só os Contatos**: com o Erevos bloqueado, o ícone de Contatos, o botão Contatos do widget e o aviso de um aniversário pedem a senha e depois abrem só os contatos. Uma conversa, um SMS, as Configurações e o cadeado laranja **Desbloquear tudo** pedem a senha de novo e depois abrem todo o Erevos. Veja [Bloqueio com senha](#lock).",
  "**Old private messages in Nostr chats**: Erevos also reads private messages sent the older way (NIP-04), which Damus, Primal and many apps still send and keep, past and new, in the same chats. The relays see who wrote such a message to whom; Erevos itself still sends only the NIP-17 way. See [Chats with other Nostr apps](#nostr-chats).":
    "**Mensagens privadas antigas nas conversas Nostr**: o Erevos também lê as mensagens privadas mandadas do jeito antigo (NIP-04), que o Damus, o Primal e muitos apps ainda mandam e guardam: passadas e novas, nas mesmas conversas. Os relays veem quem escreveu uma mensagem dessas para quem; o próprio Erevos continua mandando só do jeito do NIP-17. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Public posts in Nostr chats**: in a chat with one person, **Public posts** shows what they post for everyone, newest first, read only. It is looked up through Tor as the space says and not kept, and no pictures or links are opened. See [Chats with other Nostr apps](#nostr-chats).":
    "**Publicações públicas nas conversas Nostr**: numa conversa com uma pessoa, **Publicações públicas** mostra o que ela publica para todos, das mais recentes às mais antigas, somente leitura. Isso é buscado pelo Tor como o espaço diz e não é guardado, e nenhuma imagem ou link é aberto. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  // 4.0.0-rc.8
  // 4.0.0-rc.7
  "**Licence**: Settings → General → Licence says under which licence Erevos is free software, AGPL-3.0-or-later, its three additional terms, that it comes with no warranty, and who made it. See [Licence](#licence).":
    "**Licença**: Configurações → Geral → Licença diz sob qual licença o Erevos é software livre, AGPL-3.0-or-later, as suas três condições adicionais, que ele vem sem nenhuma garantia, e quem o fez. Veja [Licença](#licence).",
  "**Contact**: Settings → General → Contact adds the maker of Erevos as a contact, to write to in Erevos itself, end-to-end encrypted, with no phone number and no email. See [What Erevos is](#about).":
    "**Contato**: Configurações → Geral → Contato adiciona o criador do Erevos como contato, para você escrever para ele no próprio Erevos, com criptografia de ponta a ponta, sem número de telefone e sem e-mail. Veja [O que é o Erevos](#about).",
  "**A new sticker set, Angry Eyes**: 24 faces of big yellow eyes on a black disc, drawn by the maintainer, each with the moves he gave it.":
    "**Um novo conjunto de figurinhas, Angry Eyes**: 24 rostos de grandes olhos amarelos em um disco preto, desenhados pelo criador do Erevos, cada um com os movimentos que ele lhe deu.",
  "**The calculator opens again**: in 4.0.0-rc.6 it closed as soon as it was tapped.":
    "**A calculadora volta a abrir**: na 4.0.0-rc.6 ela fechava assim que você tocava nela.",
  "**People you follow on Nostr are looked for on more relays**: **Show the people you follow** also asks relays that gather follow lists and more of the relays your key writes on, and waits longer for them; when it finds no one, it says why and how each relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**As pessoas que você segue no Nostr são procuradas em mais relays**: **Mostrar as pessoas que você segue** consulta também relays que reúnem listas de seguidos e mais dos relays onde a sua chave escreve, e espera mais tempo por eles; quando não encontra ninguém, diz por quê e como cada relay respondeu. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  // 4.0.0-rc.6
  "**Panic password**: with the password lock on, **Set the panic password** under the Panic button sets a password of its own that, typed on the lock screen, wipes Erevos as **Wipe everything now** does, while the screen shows **Wrong password**. Nothing shows whether one is set. See [Panic button](#panic).":
    "**Senha de pânico**: com o bloqueio com senha ativado, **Definir a senha de pânico** em «Botão de pânico» define uma senha própria que, digitada na tela de bloqueio, apaga o Erevos como **Apagar tudo agora**, enquanto a tela mostra **Senha incorreta**. Nada mostra se há uma definida. Veja [Botão de pânico](#panic).",
  "**Calculator in place of Erevos**: on Android, under Launcher icons, a calculator that works can take the place of Erevos's icon; your code, then **=**, opens Erevos, which asks for its password as always. See [Appearance](#appearance).":
    "**Calculadora no lugar do Erevos**: no Android, em «Ícones do launcher», uma calculadora que funciona pode tomar o lugar do ícone do Erevos; o seu código, depois **=**, abre o Erevos, que pede a senha dele como sempre. Veja [Aparência](#appearance).",
  "**Chat with myself on your linked devices too**: notes, photos, files, voice messages and reminders written on one device go to the others, as do a reminder changed or seen and a note deleted. Those from before go once, both ways. See [Linked devices](#devices).":
    "**Conversa comigo também nos seus dispositivos conectados**: notas, fotos, arquivos, mensagens de voz e lembretes escritos em um dispositivo vão para os outros, assim como um lembrete mudado ou visto e uma nota apagada. Os de antes vão uma vez, nos dois sentidos. Veja [Dispositivos conectados](#devices).",
  "**Start when the phone turns on**: on Android, under In the background, Erevos can start by itself after the phone turns on, so the spaces set to say a message came while closed already say \"New message\", never which space or what. Off unless you choose it. See [Chat through a relay](#relay).":
    "**Iniciar quando o celular ligar**: no Android, em «Em segundo plano», o Erevos pode iniciar sozinho depois que o celular liga, de modo que os espaços configurados para avisar que chegou uma mensagem enquanto estão fechados já dizem “New message”, nunca qual espaço ou o quê. Desativado, a menos que você escolha. Veja [Conversar por um relay](#relay).",
  "**Moving the clock no longer ends the wait after wrong passwords**: it goes by the phone's own time since it started, which no one can set; after a restart it starts again from its beginning. See [Password lock](#lock).":
    "**Mexer no relógio não encerra mais a espera depois de senhas erradas**: ela segue o tempo próprio do celular desde que ele ligou, que ninguém pode ajustar; depois de um reinício ela recomeça do começo. Veja [Bloqueio com senha](#lock).",
  "**People you follow on Nostr, found where your other app keeps them**: with a key brought from another Nostr app, **Show the people you follow** also looks on the relays your key writes on, and says so when no relay answered. See [Chats with other Nostr apps](#nostr-chats).":
    "**As pessoas que você segue no Nostr, encontradas onde o seu outro app as guarda**: com uma chave trazida de outro app Nostr, **Mostrar as pessoas que você segue** procura também nos relays onde a sua chave escreve, e avisa quando nenhum relay respondeu. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Your Nostr name keeps the rest of your profile**: saving **Your name** changes only the name in your profile; a picture or words that another app of your key put there stay. Before, they could be wiped. See [Chats with other Nostr apps](#nostr-chats).":
    "**Seu nome no Nostr mantém o resto do seu perfil**: salvar **Seu nome** muda só o nome no seu perfil; uma foto ou palavras que outro app da sua chave pôs lá continuam. Antes, podiam ser apagadas. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Screens come down when no keyboard is open, in every case**: the home screen's list and buttons, or a chat, could still stay up as if a keyboard were open after it had gone. Now Erevos asks Android itself whether a keyboard is shown, and with none they come down within a second.":
    "**As telas descem quando não há teclado aberto, em todos os casos**: a lista e os botões da tela inicial, ou uma conversa, ainda podiam ficar no alto como se houvesse um teclado aberto, depois que ele sumia. Agora o Erevos pergunta ao próprio Android se há um teclado na tela, e sem teclado elas descem em menos de um segundo.",
  // 4.0.0-rc.5
  "**New chat opens hidden chats sooner**: hold **New chat** down for a moment, not a whole second, and the field for a PIN of hidden chats opens; on Android the phone buzzes once as it opens. See [Hidden chats](#hidden).":
    "**Nova conversa abre mais depressa as conversas ocultas**: segure **Nova conversa** por um instante, não um segundo inteiro, e abre-se o campo para um PIN de conversas ocultas; no Android o telefone vibra uma vez ao abrir. Veja [Conversas ocultas](#hidden).",
  "**People you follow on Nostr**: under New chat in Nostr chats, **Show the people you follow** lists the people your Nostr key follows, with their names; tap one to write to them. See [Chats with other Nostr apps](#nostr-chats).":
    "**Pessoas que você segue no Nostr**: nas Conversas Nostr, em Nova conversa, **Mostrar as pessoas que você segue** lista as pessoas que a sua chave Nostr segue, com os nomes; toque numa para escrever para ela. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Who makes Erevos, and its licence**: About Erevos now names its maker, and every file of Erevos's source code says whose it is and under which licence; the AGPL-3.0 licence has three added terms (keep the maker's name, mark a changed version, give it another name). See [What Erevos is](#about).":
    "**Quem faz o Erevos, e sua licença**: Sobre o Erevos agora diz quem o faz, e cada arquivo do código-fonte diz de quem é e sob qual licença; a licença AGPL-3.0 tem três condições adicionais (manter o nome do autor, marcar uma versão alterada como alterada e dar-lhe outro nome). Veja [O que é o Erevos](#about).",
  // 4.0.0-rc.4
  "**Numbers on the home chips**: each chip above the chats (All messages, SMS, Erevos, Matrix, XMPP, Nostr) shows how many messages are not read in it, as a small number after its name; muted chats and groups are not counted. See [Getting started](#start).":
    "**Números nos chips da tela inicial**: cada chip acima das conversas (Todos, SMS, Erevos, Matrix, XMPP, Nostr) mostra quantas mensagens não lidas há nele, com um número pequeno depois do nome; as conversas e os grupos em silêncio não contam. Veja [Primeiros passos](#start).",
  "**Open a photo full screen in Matrix, XMPP and Nostr chats**: tap a photo shown in a Matrix, XMPP or Nostr chat to see it on the whole screen, with zoom, turning with the phone and Save, as in a chat with a contact. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Foto em tela inteira nas conversas Matrix, XMPP e Nostr**: toque numa foto mostrada numa conversa Matrix, XMPP ou Nostr para vê-la na tela inteira, com zoom, rotação com o celular e Salvar, como na conversa com um contato. Veja [Matrix](#matrix), [XMPP](#xmpp) e [Conversas com outros apps Nostr](#nostr-chats).",
  "**Who got and who read your messages in groups**: in a group that is not public, your messages show ✓, then ✓✓ once they reached the phone of every member, and ✓✓✓ once every one read them. Hold one and choose **Who read it** to see who read it and when, whose phone it reached and when, and who has neither yet. A member whose Erevos is older says nothing. A linked computer shows the same marks. See [Chat through a relay](#relay) and [Group chats](#groups).":
    "**Quem recebeu e quem leu as suas mensagens nos grupos**: em um grupo que não é público, as suas mensagens mostram ✓, depois ✓✓ quando chegaram ao celular de cada membro, e ✓✓✓ quando todos as leram. Segure uma e escolha **Quem leu** para ver quem a leu e quando, em que celular ela chegou e quando, e quem ainda não fez nem uma coisa nem outra. Um membro com um Erevos mais antigo não avisa nada. Um computador conectado mostra as mesmas marcas. Veja [Conversar por um relay](#relay) e [Conversas em grupo](#groups).",
  "**Who read your messages in Matrix**: your messages in a Matrix chat show ✓ once the Matrix server took them and ✓✓✓ once every other member read them, as their Matrix apps tell their servers; **Who read it**, on a message held down, lists who read it and when, and who has not. Matrix has no mark for a message that reached a phone, so there is no ✓✓. See [Matrix](#matrix).":
    "**Quem leu as suas mensagens no Matrix**: as suas mensagens em uma conversa do Matrix mostram ✓ quando o servidor Matrix as recebeu e ✓✓✓ quando todos os outros membros as leram, como os apps Matrix deles avisam os servidores; **Quem leu**, numa mensagem segurada, lista quem a leu e quando, e quem não leu. O Matrix não tem marca para uma mensagem que chegou a um celular, então não existe ✓✓. Veja [Matrix](#matrix).",
  "**Quiet group messages for the marks**: the group message that says a message came or was read goes only to the senders concerned, and batched; after 300 such messages to some members only, the next goes to all, so no member falls behind in the phone's MLS keys (they accept a jump of 1000 at most). Groups let go of as their space closes send nothing more. See [Group chats](#groups).":
    "**Mensagens de grupo silenciosas para as marcas**: a mensagem de grupo que diz que uma mensagem chegou ou foi lida vai só aos remetentes envolvidos, e agrupada; depois de 300 dessas mensagens enviadas só a alguns membros, a seguinte vai a todos, para que nenhum membro fique para trás nas chaves MLS do celular (elas aceitam um salto de no máximo 1000). Os grupos soltos quando o espaço deles fecha não enviam mais nada. Veja [Conversas em grupo](#groups).",
  // 4.0.0-rc.3
  "**Bold, italic, code and hidden words**: in chats and groups, words typed between * become bold, between _ italic, between ~ struck through, between ` code, and between || hidden behind a grey bar until tapped. See [Chat through a relay](#relay).":
    "**Negrito, itálico, código e palavras escondidas**: em conversas e grupos, palavras entre * ficam em negrito, entre _ em itálico, entre ~ riscadas, entre ` como código, e entre || escondidas atrás de uma barra cinza até você tocar. Veja [Conversar por um relay](#relay).",
  "**Hidden photo**: under + in a chat or a group, a photo that shows blurred until it is tapped. See [Chat through a relay](#relay).":
    "**Foto escondida**: em + numa conversa ou num grupo, uma foto que aparece borrada até você tocar nela. Veja [Conversar por um relay](#relay).",
  "**Safety message**: under + in a chat, words to a contact that the relay sends by itself if you do not open Erevos for 6 hours to a week; each time you open it, they move on again. See [Chat through a relay](#relay).":
    "**Mensagem de segurança**: em + numa conversa, palavras para um contato que o relay envia sozinho se você não abrir o Erevos por um período de 6 horas a uma semana; cada vez que você o abre, elas são adiadas de novo. Veja [Conversar por um relay](#relay).",
  "**Name a member in a group with @**: type @ and pick a member; they are told of the message even if they muted the group. See [Group chats](#groups).":
    "**Cite um membro num grupo com @**: digite @ e escolha um membro; ele é avisado da mensagem mesmo que tenha silenciado o grupo. Veja [Conversas em grupo](#groups).",
  "**Reply, change, react and delete in XMPP chats**: hold a message in an XMPP chat or group to answer it, change your words, delete it for everyone or react with an emoji, as Conversations, Dino, Gajim, Monal and Kaidan do; and **typing…** shows while the other person writes. See [XMPP](#xmpp).":
    "**Responder, editar, reagir e apagar nas conversas XMPP**: segure uma mensagem em uma conversa ou grupo XMPP para respondê-la, mudar suas palavras, apagá-la para todos ou reagir com um emoji, como Conversations, Dino, Gajim, Monal e Kaidan fazem; e **digitando…** aparece enquanto a outra pessoa escreve. Veja [XMPP](#xmpp).",
  "**See who is writing in a Matrix chat**: **typing…** shows under a Matrix chat while someone writes in it, as the Matrix server says. It shows of you too only if you turn on **Say when I am writing** on the Matrix or XMPP screen: off at first, as it goes through the server not encrypted. See [Matrix](#matrix).":
    "**Veja quem está escrevendo num chat Matrix**: **digitando…** aparece embaixo de um chat Matrix enquanto alguém escreve nele, como o servidor Matrix diz. De você só aparece se você ativar **Avisar quando estou escrevendo** na tela do Matrix ou XMPP: desligado no início, pois passa pelo servidor sem criptografia. Veja [Matrix](#matrix).",
  "**Block someone on XMPP**: Block, at the bottom of an XMPP chat, keeps that person's messages, calls and requests from every app of your XMPP account; Unblock lets them through again. See [XMPP](#xmpp).":
    "**Bloqueie alguém no XMPP**: Bloquear, no fim de um chat XMPP, mantém as mensagens, chamadas e pedidos dessa pessoa longe de todos os apps da sua conta XMPP; Desbloquear a deixa passar de novo. Veja [XMPP](#xmpp).",
  "**Voice messages in XMPP chats**: hold the microphone under an XMPP chat's message box to record, and let go to send; it goes encrypted as the chat is, as Conversations sends one. See [XMPP](#xmpp).":
    "**Mensagens de voz nos chats XMPP**: segure o microfone abaixo da caixa de mensagem de um chat XMPP para gravar, e solte para enviar; vai criptografada como o chat, do jeito que o Conversations envia. Veja [XMPP](#xmpp).",
  "**Matrix groups from Erevos**: New group, on the Matrix screen, makes an encrypted group with a name and the people you invite; Join a group joins one by its address; Invite, in a group, asks someone else in; typing @ in a group names a member, who is told of it. See [Matrix](#matrix).":
    "**Grupos do Matrix pelo Erevos**: Novo grupo, na tela do Matrix, cria um grupo criptografado com um nome e as pessoas que você convidar; Entrar num grupo entra em um pelo endereço; Convidar, num grupo, chama outra pessoa; digitar @ num grupo cita um membro, que é avisado. Veja [Matrix](#matrix).",
  "**The panic button on a computer and on Sailfish OS**: Settings → Privacy and security → Panic button now wipes Erevos there too, with its automatic backups if you choose; on a computer it then starts again as new. See [Panic button](#panic).":
    "**O botão de pânico num computador e no Sailfish OS**: Configurações → Privacidade e segurança → Botão de pânico agora apaga o Erevos também lá, com os backups automáticos dele se você escolher; num computador ele depois começa como novo. Veja [Botão de pânico](#panic).",
  "**Every chat opens at its latest message**: chats with contacts, groups and SMS, and the Matrix, XMPP and Nostr chats, all open at the last message with the message bar under it, and have round arrows to the start, to where you left off (the first message that was new when you opened it) and to the end. See [Getting started](#start).":
    "**Cada conversa abre na sua última mensagem**: as conversas com contatos, os grupos e os SMS, e as conversas de Matrix, XMPP e Nostr abrem todas na última mensagem, com a barra de mensagem embaixo, e têm setas redondas para o início, para onde você parou (a primeira mensagem que era nova ao abrir) e para o fim. Veja [Primeiros passos](#start).",
  "**The panic button says when it refused**: when your panic app asked to wipe Erevos while the switch was off, or signed with another key, the panic screen now says so, with the time. An app that moves to a new key the way Android allows stays trusted; otherwise you can trust it again as it is now. See [Panic button](#panic).":
    "**O botão de pânico diz quando recusou**: quando seu app de pânico pediu para apagar o Erevos com o interruptor desligado, ou assinado com outra chave, a tela do botão de pânico agora avisa, com a hora. Um app que passa a uma chave nova do jeito que o Android permite continua de confiança; senão você pode confiar nele de novo como está agora. Veja [Botão de pânico](#panic).",
  "**The home screen's chips stay on one line**: with a Nostr, Matrix or XMPP chip as well, **Names** went to a line of its own and the chips moved. Now they stay on one line that slides to the side, and the chosen one is always in sight.":
    "**Os chips da tela inicial ficam em uma linha só**: com um chip de Nostr, Matrix ou XMPP a mais, **Nomes** ia para uma linha própria e os chips mudavam de lugar. Agora ficam em uma linha só que desliza para o lado, e o escolhido está sempre à vista.",
  "**Screens come down when the keyboard is gone**: back from another app that had its keyboard open, the home screen's buttons (or a chat's field) could stay up where the keyboard had been, until a keyboard opened again. Now they come down within a second.":
    "**As telas descem quando o teclado some**: ao voltar de outro app com o teclado aberto, os botões da tela inicial (ou o campo de uma conversa) podiam ficar no alto, onde estava o teclado, até um teclado abrir de novo. Agora descem em menos de um segundo.",
  // 4.0.0-rc.2
  "**See what you type in a password or a PIN**: every field for a password, a PIN or a token has an eye at its end: tap it to see what you type, and again to hide it. It is hidden again the next time. See [Password lock](#lock).":
    "**Veja o que você digita numa senha ou num PIN**: cada campo de senha, PIN ou token tem um olho no fim: toque nele para ver o que você digita, e de novo para esconder. Na próxima vez ele volta a ficar escondido. Veja [Bloqueio com senha](#lock).",
  "**A chat read as it opens stays read**: messages read while their chat was still opening, as Erevos ended a look at the relay, showed as unread on the home screen once you went back. Now they are marked read as soon as they show.":
    "**Uma conversa lida enquanto abre fica lida**: mensagens lidas enquanto a conversa ainda estava abrindo, enquanto o Erevos terminava de olhar no relay, apareciam como não lidas na tela inicial assim que você voltava. Agora elas ficam marcadas como lidas assim que aparecem.",
  "**Link for a website**: under New chat → Your contact link, a link to put on a web page, such as your contact page. It opens a page that offers Erevos to whoever has none yet, then adds you; what they send comes as a message request. See [Chat through a relay](#relay).":
    "**Link para um site**: em Nova conversa → Seu link de contato, um link para pôr numa página web, como sua página de contato. Abre uma página que oferece o Erevos a quem ainda não o tem e depois adiciona você; o que enviar chega como solicitação de mensagem. Veja [Conversar por um relay](#relay).",
  "**An update's download that stalls is tried again**: when the connection brings nothing for a while, Erevos starts the download again by itself, three times in all, and then says so in its own words. See [Updates](#updates).":
    "**Um download de atualização que trava é tentado de novo**: quando a conexão não traz nada durante algum tempo, o Erevos recomeça o download sozinho, três vezes ao todo, e depois avisa com palavras próprias. Veja [Atualizações](#updates).",
  // 4.0.0-rc.1
  "**Pieces of photos through Nostr stay with their chats**: while a photo that comes through Nostr waits for the rest of its pieces, they are now kept encrypted with the space or the hidden chats they came for, no longer apart where they could be counted, so nothing outside a hidden chats' password says that a photo is on its way to them. Pieces kept before go to the first chats whose photo they are, or after four days. See [Through Nostr](#nostr).":
    "**Os pedaços de fotos pelo Nostr ficam com as suas conversas**: enquanto uma foto que chega pelo Nostr espera o resto dos seus pedaços, eles agora são guardados criptografados com o espaço ou as conversas ocultas para os quais vieram, não mais à parte, onde podiam ser contados, então nada fora da senha de conversas ocultas diz que uma foto está a caminho delas. Os pedaços guardados antes vão para as primeiras conversas de cuja foto são, ou saem após quatro dias. Veja [Pelo Nostr](#nostr).",
  "**Encrypted SMS when nothing else works, if you choose**: on Android, when the relay, Nostr, the phones nearby and LoRa all fail, a text to an Erevos contact whose number is linked can go by SMS, end-to-end encrypted, hidden from their SMS app. Off until you turn it on, for all such contacts under Settings → Phone and SMS → SMS, or for one in a chat's Details. It costs SMS (3 for a short text, up to 10 for a longer one), and the phone company sees who wrote to whom, and when. Both phones need Erevos as the SMS app. See [SMS](#sms).":
    "**SMS criptografados quando nada mais funciona, se você quiser**: no Android, quando o relay, o Nostr, os celulares por perto e o LoRa falham todos, um texto para um contato do Erevos com número vinculado pode ir por SMS, criptografado de ponta a ponta e escondido do app de SMS dele. Desativado até você ativar, para todos esses contatos em Configurações → Telefone e SMS → SMS, ou para um nos Detalhes de uma conversa. Custa SMS (3 para um texto curto, até 10 para um mais longo), e a operadora vê quem escreveu para quem, e quando. Os dois celulares precisam do Erevos como app de SMS. Veja [SMS](#sms).",
  "**Answer a hidden call with Answer**: on the \"Incoming call\" screen with no name that a call to your hidden chats brings, **Answer** now asks for the PIN, as the small sign does, and the right PIN answers the call; before, it could not connect, and only the small sign could. See [Hidden chats](#hidden).":
    "**Atender uma chamada oculta com Atender**: na tela “Chamada recebida” sem nome que uma chamada para as suas conversas ocultas traz, **Atender** agora pede o PIN, como o pequeno sinal, e o PIN certo atende a chamada; antes, não conseguia conectar, e só o pequeno sinal conseguia. Veja [Conversas ocultas](#hidden).",
  "**Spam SMS come quietly**: on Android, an SMS that the spam filter's own words catch, a link with words that try to fool from a number that is no contact and that you never answered, still goes to Spam but no longer shows a notice or makes a sound. Spam by your own words and rules still shows one, as they stay encrypted in the space; with the Spam filter off, every SMS does. See [SMS](#sms).":
    "**SMS de spam chegam em silêncio**: no Android, um SMS que as palavras do próprio filtro de spam pegam, um link com palavras que tentam enganar de um número que não é contato e a que você nunca respondeu, ainda vai para o Spam, mas não mostra mais aviso nem faz som. O spam pelas suas próprias palavras e regras ainda mostra um, pois elas ficam criptografadas no espaço; com o Filtro de spam desligado, todo SMS mostra. Veja [SMS](#sms).",
  '**What\'s new in two parts**: each version says first what changes for you, then what changed under the hood: fixes, speed, battery and security inside. See [Updates](#updates).':
    '**Novidades em duas partes**: cada versão diz primeiro o que muda para você e depois o que mudou nos bastidores: correções, velocidade, bateria e segurança por dentro. Veja [Atualizações](#updates).',
  '**A contact\'s SMS no longer stay counted as new**: opening their chat reads all of them, the earlier ones too, not only those that show.':
    '**Os SMS de um contato não ficam mais contados como novos**: abrir a conversa lê todos, também os anteriores, não só os que aparecem.',
  '**A message no longer waits when Tor cannot reach the relay**: with Tor for messages, it goes straight at once, as the Tor settings say. See [Through Tor](#tor).':
    '**Uma mensagem não fica mais esperando quando o Tor não chega ao relay**: com o Tor para as mensagens, ela sai direto na hora, como dizem as configurações do Tor. Veja [Pelo Tor](#tor).',
  '**Background notices no longer stop after a network change**: when the connection of a wait at the relay died on the way (Wi-Fi to mobile data, the relay restarting), Erevos took the relay for one from before, which cannot wait, for the whole run: contacts\' messages then came up to ten minutes late, and hidden chats, closed spaces and hidden rings said nothing until Erevos was restarted. See [Chat through a relay](#relay).':
    '**Os avisos em segundo plano não param mais depois de uma troca de rede**: quando a conexão de uma espera no relay morria no caminho (de Wi-Fi para dados móveis, reinício do relay), o Erevos tomava o relay por um antigo, que não sabe esperar, durante toda a execução: as mensagens dos contatos chegavam até dez minutos atrasadas, e as conversas ocultas, os espaços fechados e os toques ocultos não diziam nada até reiniciar o Erevos. Veja [Conversar por um relay](#relay).',
  '**A call hung up at once no longer rings**: when the hang-up came in the same look as the call, the phone rang 45 seconds for a call nobody was on; the same for a group call its starter left at once. See [Chat through a relay](#relay).':
    '**Uma chamada desligada na hora não toca mais**: quando o desligamento chegava no mesmo olhar que a chamada, o telefone tocava 45 segundos por uma chamada em que não havia ninguém; o mesmo para uma chamada de grupo que quem a começou deixou na hora. Veja [Conversar por um relay](#relay).',
  '**A hidden call rings once**: a place with Receive while closed and a ring queue rang twice for one call, and a call taken while hidden chats were open rang again as they closed. See [Hidden chats](#hidden).':
    '**Uma chamada oculta toca uma vez**: um lugar com Receber quando fechadas e uma fila de toque tocava duas vezes por uma chamada, e uma chamada atendida com as conversas ocultas abertas voltava a tocar quando elas fechavam. Veja [Conversas ocultas](#hidden).',
  '**A member\'s contact link no longer says New message**: the answer to an ask from a group only adds the contact, with no notice. See [Group chats](#groups).':
    '**O link de contato de um membro não diz mais Nova mensagem**: a resposta a um pedido feito de um grupo só adiciona o contato, sem aviso. Veja [Conversas em grupo](#groups).',
  '**The birthday notice and the phone\'s incoming call no longer replace each other**: they had the same notice number. See [Contacts](#contacts).':
    '**O aviso de aniversário e a chamada recebida do telefone não se substituem mais**: tinham o mesmo número de aviso. Veja [Contatos](#contacts).',
  '**A closed space tells of its contacts\' messages too**: since each contact writes to a queue of their own, a space that says a message came while another is open told only of group messages and first messages from new contacts. It now asks about its contacts\' queues too, up to 64. See [Chat through a relay](#relay).':
    '**Um espaço fechado avisa também das mensagens dos contatos dele**: como cada contato escreve numa fila própria, um espaço que avisa que chegou mensagem enquanto outro está aberto só avisava de mensagens de grupos e de primeiras mensagens de contatos novos. Agora ele pergunta também pelas filas dos contatos dele, até 64. Veja [Conversar por um relay](#relay).',
  '**The user guide is in every language of the app**: it shows in the one you chose, and names the buttons as the app shows them. See [Language](#start).':
    '**O guia de uso está em todos os idiomas do app**: aparece no que você escolheu e chama os botões como o app os mostra. Veja [Idioma](#start).',
  '**Location finds where you are, indoors too**: the phone looks by satellite and by its network at once, a sheet says it is looking, and when nothing is found it says why, with Try again. See [Chat through a relay](#relay).':
    '**Localização encontra onde você está, também em lugares fechados**: o celular procura por satélite e pela rede dele ao mesmo tempo, uma folha diz que está procurando, e quando nada é encontrado diz por quê, com Tentar de novo. Veja [Conversar por um relay](#relay).',
  '**The web app\'s icon counts what is not read**: on an iPhone, with notifications on for the space, Erevos\'s icon on the home screen shows how many messages are not read, never a hidden chat\'s, unless turned off under Settings → Notifications → Number on the icon. See [On an iPhone](#iphone).':
    '**O ícone do app web conta o que não foi lido**: num iPhone, com as notificações ativas para o espaço, o ícone do Erevos na tela de início mostra quantas mensagens não foram lidas, nunca as de uma conversa oculta, a não ser que você o desligue em Configurações → Notificações → Número no ícone. Veja [Num iPhone](#iphone).',
  "**Notifications for each chat**: on Android, mute a chat or a group for 8 hours, a week or always, and give its messages and its calls a sound of their own, or none. See [Chat through a relay](#relay).":
    "**Notificações para cada conversa**: no Android, silencie uma conversa ou um grupo por 8 horas, uma semana ou sempre, e dê às mensagens e chamadas dela um som próprio, ou nenhum. Veja [Conversar por um relay](#relay).",
  "**A chat locked with its own PIN stays locked**: when its contact's Erevos started a new conversation, as it does about once a month, the chat lost its PIN, and a public group joined again lost its own. See [Hidden chats](#hidden).":
    "**Uma conversa bloqueada com um PIN próprio continua bloqueada**: quando o Erevos do contato começava uma conversa nova, como faz mais ou menos uma vez por mês, a conversa perdia o PIN, e um grupo público em que você entrou de novo perdia o seu. Veja [Conversas ocultas](#hidden).",
  "**Erevos's icon keeps the number of messages not read, on Android**: leaving Erevos with messages not read, a notice without sound keeps how many until you read them, and the launcher shows it on the icon, as a number or a dot. Settings → Notifications → Number on the icon turns it off. See [Chat through a relay](#relay).":
    "**O ícone do Erevos guarda o número de mensagens não lidas, no Android**: ao sair do Erevos com mensagens não lidas, uma notificação sem som guarda quantas são até você lê-las, e o launcher a mostra no ícone, como número ou ponto. Configurações → Notificações → Número no ícone o desliga. Veja [Conversar por um relay](#relay).",
  "**The web app's notifications, more dependable**: no New message over Erevos while it is open, and a push held back while the phone was offline no longer counts messages you already read (both with your relay updated), every notice sounds in Chrome, Firefox and Edge, they come back by themselves when the browser changes its push address, and Notifications while closed says when the browser blocks them or your relay was not told yet that they are off. See [On an iPhone](#iphone).":
    "**As notificações do app web, mais confiáveis**: nenhuma Nova mensagem por cima do Erevos enquanto ele está aberto, e um push retido enquanto o celular estava sem conexão não conta mais as mensagens que você já leu (as duas coisas com o seu relay atualizado), cada aviso faz som no Chrome, no Firefox e no Edge, elas voltam sozinhas quando o navegador muda o endereço de push dele, e Notificações com o app fechado diz quando o navegador as bloqueia ou quando o seu relay ainda não foi avisado de que elas estão desativadas. Veja [Num iPhone](#iphone).",
  "**Calls ring in the web app, on the computer and on Sailfish OS**: a call that comes while Erevos is open now rings, where only its screen showed, and vibrates where the phone can. On an iPhone it rings once you have touched Erevos, and not on silent. See [On an iPhone](#iphone).":
    "**As chamadas tocam no app web, no computador e no Sailfish OS**: uma chamada que chega enquanto o Erevos está aberto agora toca, onde antes só aparecia a tela dela, e vibra onde o telefone pode. Num iPhone ela toca depois que você tocou no Erevos, e não no silencioso. Veja [Num iPhone](#iphone).",
  '**Erevos on a computer keeps running with its window closed**: in the system tray (on a Mac, in the Dock) it goes on receiving, a call rings and brings the window back, and a notification says how many messages are not read, never who or what. Turn it off under Settings → Notifications → In the background. See [On a computer](#desktop).':
    '**O Erevos no computador continua rodando com a janela fechada**: na bandeja do sistema (num Mac, no Dock) ele continua recebendo, uma chamada toca e traz a janela de volta, e uma notificação diz quantas mensagens não foram lidas, nunca de quem nem o quê. Desligue em Configurações → Notificações → Em segundo plano. Veja [Num computador](#desktop).',
  "**Erevos on Sailfish OS tells of messages and calls while it is closed**: while it is out of sight or closed, a small helper waits at the relay for the open space, a notification says how many messages came, never who or what, and a call rings with the phone's ringtone. See [On Sailfish OS](#sailfish).":
    "**O Erevos no Sailfish OS avisa de mensagens e chamadas enquanto está fechado**: enquanto não está à vista ou está fechado, um pequeno ajudante espera no relay pelo espaço aberto, uma notificação diz quantas mensagens chegaram, nunca de quem nem o quê, e uma chamada toca com o toque do celular. Veja [No Sailfish OS](#sailfish).",
  "**The relay's pushes to the web app, sturdier**: a push the push service could not take just then is sent again, a call goes before the messages waiting their turn, and whoever runs the relay can allow another push service. Your relay needs an update for it.":
    "**Os pushes do relay para o app web, mais robustos**: um push que o serviço de push não pôde aceitar naquele momento é enviado de novo, uma chamada passa na frente das mensagens que esperam a vez delas, e quem cuida do relay pode permitir outro serviço de push. O seu relay precisa de uma atualização para isso.",
  "**Permissions checks every notice Erevos uses**: on Android, the message notice without sound or with a chat's own sound, and the reminders', turned off, now show there, with a button to each. See [Chat through a relay](#relay).":
    "**Permissões verifica cada aviso que o Erevos usa**: no Android, o aviso de mensagens sem som ou com o som próprio de uma conversa, e o dos lembretes, quando desativados, agora aparecem ali, com um botão para cada um. Veja [Conversar por um relay](#relay).",
  '**Hidden chats say what their switches need**: Say when a message comes and Ring calls when closed say so when Settings → Notifications → In the background lets them do nothing. See [Hidden chats](#hidden).':
    '**As conversas ocultas dizem do que os interruptores delas precisam**: Avisar quando chega uma mensagem e Tocar as chamadas quando fechadas avisam quando Configurações → Notificações → Em segundo plano não as deixa fazer nada. Veja [Conversas ocultas](#hidden).',
  "**Truer words about notices**: Settings and the guide give the notices' own words and say what each one needs. See [Chat through a relay](#relay).":
    "**Palavras mais fiéis sobre os avisos**: as Configurações e o guia dão as próprias palavras dos avisos e dizem do que cada um precisa. Veja [Conversar por um relay](#relay).",
  "**Calls ring as they should**: with Do Not Disturb only when their notice may break through, with a phone's clock off too once the relay is updated, and to the end on Android 7 and 8; a second call is told busy, and a ring stops only for its own call. See [Chat through a relay](#relay).":
    "**As chamadas tocam como devem**: com o Não perturbe só quando o aviso delas pode passar por ele, também com o relógio de um celular errado assim que o relay for atualizado, e até o fim no Android 7 e 8; uma segunda chamada recebe sinal de ocupado, e um toque só para por causa da própria chamada. Veja [Conversar por um relay](#relay).",
  '**Hidden calls**: one turned down no longer leaves Erevos over the lock screen, one that comes while the password screen shows comes over it, and none rings twice. See [Hidden chats](#hidden).':
    '**Chamadas ocultas**: uma recusada não deixa mais o Erevos sobre a tela de bloqueio, uma que chega enquanto a tela da senha aparece vem por cima dela, e nenhuma toca duas vezes. Veja [Conversas ocultas](#hidden).',
  '**Notices come again at once after a change of network**, and receiving starts again as Erevos shows when Android refused it. See [Chat through a relay](#relay).':
    '**Os avisos voltam a chegar na hora depois de uma mudança de rede**, e o recebimento começa de novo quando o Erevos aparece na tela, se o Android o tinha recusado. Veja [Conversar por um relay](#relay).',
  "**Hidden chats' notices tell each message once**: what came since a place last looked is told as it closes, a call that rang is not told again as a message, and a place whose queue the relay lost keeps its switch on. See [Hidden chats](#hidden).":
    "**Os avisos das conversas ocultas falam de cada mensagem uma vez**: o que chegou desde a última vez que uma posição olhou é avisado quando ela fecha, uma chamada que tocou não é avisada de novo como mensagem, e uma posição cuja fila o relay perdeu mantém o interruptor dela ativado. Veja [Conversas ocultas](#hidden).",
  '**Hidden chats close while Erevos is away**, after 30 seconds, so a call to them meanwhile rings with their PIN to answer. See [Hidden chats](#hidden).':
    '**As conversas ocultas fecham enquanto o Erevos está fora da tela**, depois de 30 segundos, então uma chamada para elas nesse meio-tempo toca com o PIN delas para atender. Veja [Conversas ocultas](#hidden).',
  '**A voice message counts once**, on its last part, also when it goes again whole.':
    '**Uma mensagem de voz conta uma vez**, na última parte dela, também quando ela vai de novo inteira.',
  '**The number on the icon counts only what is still there**: a message deleted for everyone, or read on a linked computer, no longer counts. See [Chat through a relay](#relay).':
    '**O número no ícone conta só o que ainda está lá**: uma mensagem apagada para todos, ou lida num computador conectado, deixa de contar. Veja [Conversar por um relay](#relay).',
  '**Messages sent for later** tell of themselves only while their space is open, without sound if sent so.':
    '**As mensagens agendadas** só avisam de si enquanto o espaço delas está aberto, sem som se foram enviadas assim.',
  '**SMS**: one to the chat on screen only sounds there, they are marked read only while their screen shows, and Android names their notices SMS. See [SMS](#sms).':
    '**SMS**: um para a conversa na tela só toca ali, eles só são marcados como lidos enquanto a tela deles aparece, e o Android chama os avisos deles de SMS. Veja [SMS](#sms).',
  "**Reminders**: one seen in Chat with myself goes from the notice, a hidden place's go with a new PIN, and birthdays come at 9:00. See [Getting started](#start).":
    "**Lembretes**: um visto na Conversa comigo sai do aviso, os de uma posição oculta saem com um PIN novo, e os aniversários chegam às 9:00. Veja [Primeiros passos](#start).",
  '**Nostr reads as soon as Tor is ready.** See [Through Nostr](#nostr).':
    '**O Nostr lê assim que o Tor está pronto.** Veja [Pelo Nostr](#nostr).',
  "**Erevos's notices show its mark** in the status bar.":
    "**Os avisos do Erevos mostram a marca dele** na barra de status.",
  '**Notices are asked for with receiving off too**, when Say a message came is on.':
    '**Os avisos são pedidos também com o recebimento desativado**, quando Avisar quando chega mensagem está ativado.',
  "**Photos open on the whole screen**: tap one to see it edge to edge, zoom in with two fingers or a double tap, and tap again to hide or show what is around it; big photos open as small ones do. Erevos also turns with the phone while the phone's Auto-rotate is on, and a photo shown on its own even when it is off. See [Chat through a relay](#relay).":
    '**As fotos abrem na tela inteira**: toque numa para vê-la de ponta a ponta, amplie com dois dedos ou um toque duplo, e toque de novo para esconder ou mostrar o que há em volta; fotos grandes abrem como as pequenas. O Erevos também gira com o telefone enquanto Girar automaticamente estiver ativado nele, e uma foto vista sozinha mesmo quando está desativado. Veja [Conversar por um relay](#relay).',
  "**Matrix accounts in Erevos**: sign a space in to Matrix and chat with people who use Element or another Matrix app, end-to-end encrypted, under Settings → Relay and networks → Matrix. These chats are not anonymous, and say so: the Matrix server sees who talks with whom. Text, photos and files. See [Matrix](#matrix).":
    "**Contas Matrix no Erevos**: entre no Matrix com um espaço e converse com pessoas que usam o Element ou outro app Matrix, com criptografia de ponta a ponta, em Configurações → Relay e redes → Matrix. Essas conversas não são anônimas, e avisam: o servidor Matrix vê quem fala com quem. Texto, fotos e arquivos. Veja [Matrix](#matrix).",
  "**Every network's chats on the home screen**: once you sign in to Matrix, its chats are in the list with the Erevos chats and the SMS, newest first, each marked Matrix, and the Matrix chip shows them alone, as SMS and Erevos do. See [Matrix](#matrix).":
    "**As conversas de todas as redes na tela inicial**: depois que você entra no Matrix, as conversas dele ficam na lista com as conversas do Erevos e os SMS, as mais recentes primeiro, cada uma marcada Matrix, e o chip Matrix mostra só elas, como SMS e Erevos. Veja [Matrix](#matrix).",
  '**Test versions before a release**: Erevos reads a version such as 4.0.0-rc.1, a test version that comes before 4.0.0, when it looks for updates, tells of a new version and shows what is new. See [Updates](#updates).':
    '**Versões de teste antes de uma versão**: o Erevos lê uma versão como 4.0.0-rc.1, uma versão de teste que vem antes da 4.0.0, ao procurar atualizações, ao avisar de uma nova versão e ao mostrar as novidades. Veja [Atualizações](#updates).',
  "**Check Matrix devices by emoji**: in a chat with one person on Matrix, Check by emoji shows you both seven pictures; if they match, nobody sits in between, and Element sees the check too. Check this device with another of yours makes your own Element trust Erevos. See [Matrix](#matrix).":
    "**Verificar dispositivos do Matrix por emoji**: numa conversa com uma pessoa no Matrix, Verificar por emoji mostra aos dois sete imagens; se forem iguais, ninguém está no meio, e o Element também vê a verificação. Verificar este dispositivo com outro seu faz o seu próprio Element confiar no Erevos. Veja [Matrix](#matrix).",
  "**Automatic backups to your own server too**: on Android, each automatic backup can also go to a folder on a server you choose, such as your Nextcloud, over WebDAV. Off until you add one. The server gets random bytes under a random name and cannot open them; it still sees your account, your address and when. See [Backups](#backup).":
    "**Backups automáticos também para o seu próprio servidor**: no Android, cada backup automático também pode ir para uma pasta num servidor que você escolher, como o seu Nextcloud, por WebDAV. Desligado até você adicionar um. O servidor recebe bytes aleatórios com um nome aleatório e não consegue abri-los; ainda assim vê sua conta, seu endereço e quando. Veja [Backups](#backup).",
  "**Matrix Security Key and key backup**: enter the Security Key Element made, under Settings → Relay and networks → Matrix, and earlier messages open, new keys are backed up, and your other devices trust Erevos. An account with none can set one up there. See [Matrix](#matrix).":
    "**Chave de segurança e backup de chaves do Matrix**: digite a chave de segurança que o Element criou, em Configurações → Relay e redes → Matrix, e as mensagens anteriores abrem, as chaves novas ganham backup, e seus outros dispositivos confiam no Erevos. Uma conta sem ela pode criar uma ali. Veja [Matrix](#matrix).",
  "**Matrix through Tor**: on Android, a space's Matrix account follows its choice under Settings → Relay and networks → Tor, so the Matrix server no longer sees where you are; the Matrix screen says when it goes through Tor. See [Matrix](#matrix).":
    "**Matrix pelo Tor**: no Android, a conta Matrix de um espaço segue a escolha dele em Configurações → Relay e redes → Tor, então o servidor Matrix não vê mais onde você está; a tela do Matrix diz quando vai pelo Tor. Veja [Matrix](#matrix).",
  "**XMPP accounts in Erevos**: sign a space in to XMPP, under Settings → Relay and networks → XMPP, and chat with people who use Conversations, Monal, Gajim, Dino or another XMPP app, encrypted with OMEMO. These chats are not anonymous, and say so: the XMPP server sees who talks with whom. Text with delivery and read marks, photos and files, in the home list under an XMPP chip of its own, and through Tor on Android as you chose. See [XMPP](#xmpp).":
    "**Contas XMPP no Erevos**: faça um espaço entrar no XMPP, em Configurações → Relay e redes → XMPP, e converse com pessoas que usam o Conversations, o Monal, o Gajim, o Dino ou outro app XMPP, criptografado com OMEMO. Essas conversas não são anônimas, e dizem isso: o servidor XMPP vê quem fala com quem. Texto com marcas de entrega e de leitura, fotos e arquivos, na lista da tela inicial sob um chip XMPP próprio, e pelo Tor no Android como você escolheu. Veja [XMPP](#xmpp).",
  "**Voice and video calls with people on XMPP**: the two tiles at the top of an XMPP chat call the person, and their calls ring on the same screen as Erevos's own, with apps that call as Conversations does. The call goes through your call relay or the XMPP server's, so they do not learn your address; the key that proves it passes through the XMPP servers, which could put themselves in between. See [XMPP](#xmpp).":
    "**Chamadas de voz e vídeo com pessoas no XMPP**: os dois blocos no topo de uma conversa XMPP ligam para a pessoa, e as chamadas dela tocam na mesma tela que as do Erevos, com apps que ligam como o Conversations. A chamada passa pelo seu relay de chamadas ou pelo do servidor XMPP, então ela não fica sabendo seu endereço; a chave que a comprova passa pelos servidores XMPP, que poderiam se colocar no meio. Veja [XMPP](#xmpp).",
  "**Voice and video calls with people on Matrix**: on Android, the two tiles at the top of a Matrix chat call with Element Call, the call app of Element and Element X, which opens inside Erevos in a window of its own, and their calls ring here as Erevos's own do. Sound and picture are end-to-end encrypted and go through the media server your Matrix server names, never through Tor. See [Matrix](#matrix).":
    "**Chamadas de voz e vídeo com pessoas no Matrix**: no Android, os dois blocos no topo de uma conversa Matrix ligam com o Element Call, o app de chamadas do Element e do Element X, que abre dentro do Erevos numa janela própria, e as chamadas delas tocam aqui como as do Erevos. Som e imagem são criptografados de ponta a ponta e passam pelo servidor de mídia que o seu servidor Matrix indica, nunca pelo Tor. Veja [Matrix](#matrix).",
  "**Voice and video calls with people on Matrix, in the web app and on a computer**: the two tiles at the top of a Matrix chat call with Element Call there too, as on Android, over the app; its back arrow makes it small in a corner, so you can keep using Erevos during the call. Element Call runs apart from Erevos and can read nothing of it. See [Matrix](#matrix).":
    "**Chamadas de voz e vídeo com pessoas no Matrix, no app web e no computador**: os dois blocos no topo de uma conversa Matrix ligam com o Element Call também lá, como no Android, por cima do app; a seta de voltar da janela a deixa pequena num canto, para você continuar usando o Erevos durante a chamada. O Element Call roda separado do Erevos e não consegue ler nada dele. Veja [Matrix](#matrix).",
  "**Chats with people on other Nostr apps**: give a space a Nostr key of its own, under Settings → Relay and networks → Nostr chats, and chat with people who use Damus, Amethyst, Primal, 0xchat or another Nostr app, one to one or in groups, encrypted as NIP-17 asks: the relays see whom a message is for, not who wrote it. These chats are not anonymous, and say so: your key is the same to everyone you write to. Text, photos, files and reactions, in the home list under a Nostr chip of its own, and through Tor on Android as you chose. See [Chats with other Nostr apps](#nostr-chats).":
    "**Conversas com pessoas em outros apps Nostr**: dê a um espaço uma chave Nostr própria, em Configurações → Relay e redes → Conversas Nostr, e converse com pessoas que usam Damus, Amethyst, Primal, 0xchat ou outro app Nostr, a dois ou em grupo, criptografado como o NIP-17 pede: os relays veem para quem é uma mensagem, não quem a escreveu. Estas conversas não são anônimas, e dizem isso: sua chave é a mesma para todos com quem você fala. Texto, fotos, arquivos e reações, na lista da tela inicial sob um botão Nostr próprio, e pelo Tor no Android como você escolheu. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Notices for Matrix, XMPP and Nostr messages**: a message in a chat on Matrix, XMPP or Nostr shows a notice and counts in the number on Erevos's icon, as in Erevos's own chats. On Android, Notifications at the bottom of such a chat mutes it or gives it a sound of its own, and an XMPP or Matrix call rings with its chat's ringtone. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**Avisos das mensagens de Matrix, XMPP e Nostr**: uma mensagem numa conversa de Matrix, XMPP ou Nostr mostra um aviso e conta no número do ícone do Erevos, como nas conversas do próprio Erevos. No Android, Notificações, no fim de uma conversa assim, silencia ela ou dá a ela um som próprio, e uma chamada XMPP ou Matrix toca com o toque da conversa dela. Veja [Matrix](#matrix), [XMPP](#xmpp) e [Conversas com outros apps Nostr](#nostr-chats).",
  "**A closed space tells of Matrix messages**: on Android, Say a message came under While this space is closed, on the Matrix screen, has a closed space say \"New message\" when something comes on Matrix while another space is open, never what, from whom or in which chat. Off until you choose it. The Matrix server then tells the space's relay of each message, with no words in it: it learns the relay's address, and the relay when messages come. See [Matrix](#matrix).":
    "**Um espaço fechado avisa das mensagens do Matrix**: no Android, «Avisar quando chega mensagem» em «Enquanto este espaço está fechado», no ecrã do Matrix, faz um espaço fechado dizer «Nova mensagem» quando chega algo no Matrix enquanto outro espaço está aberto, nunca o quê, de quem ou em que conversa. Desligado até o escolheres. O servidor Matrix avisa então o relay do espaço de cada mensagem, sem nenhuma palavra dela: fica a saber o endereço do relay, e o relay quando chegam mensagens. Ver [Matrix](#matrix).",
  "**Made with others' open source**: About Erevos, and the guide, now name the open-source projects Erevos is built on, with their makers and their licences. See [What Erevos is](#about).":
    "**Feito com o código aberto de outros**: Em Sobre o Erevos e no guia aparecem agora os projetos de código aberto em que o Erevos se apoia, com seus autores e suas licenças. Veja [O que é o Erevos](#about).",
  "**Groups on XMPP**: under Settings → Relay and networks → XMPP, make a private group with your contacts, encrypted with OMEMO for every member as Conversations' private groups are, or join a group by its address, and answer invitations to groups. A group that is not private, a channel, is not encrypted, and says so. Your groups follow your account's other XMPP apps, and a channel tells only of messages that name you. See [XMPP](#xmpp).":
    "**Grupos no XMPP**: em Configurações → Relay e redes → XMPP, crie um grupo privado com seus contatos, criptografado com OMEMO para cada membro como os grupos privados do Conversations, ou entre num grupo pelo endereço, e responda aos convites para grupos. Um grupo que não é privado, um canal, não é criptografado, e diz isso. Seus grupos acompanham os outros apps XMPP da sua conta, e um canal avisa só das mensagens que citam você. Veja [XMPP](#xmpp).",
  "**More in Matrix chats**: hold a message to react to it, reply to it, copy it and, if it is yours, edit it or delete it for everyone. Load earlier messages brings in older ones, and the microphone under the message box sends voice messages that Element plays too. Reactions are not encrypted, as Element sends them. See [Matrix](#matrix).":
    "**Mais nas conversas do Matrix**: segure uma mensagem para reagir a ela, respondê-la, copiá-la e, se for sua, editá-la ou apagá-la para todos. «Carregar mensagens anteriores» traz as mais antigas, e o microfone abaixo do campo de mensagem envia mensagens de voz que o Element também toca. As reações não são criptografadas, como o Element as envia. Veja [Matrix](#matrix).",
  "**Video added to an XMPP call**: in a voice call with someone on XMPP, either of you can turn on video with Add video; the other is asked first and can say Not now. It works with apps that add video to a call as Conversations does. See [XMPP](#xmpp).":
    "**Vídeo adicionado a uma chamada do XMPP**: numa chamada de voz com alguém no XMPP, qualquer um dos dois pode ligar o vídeo com «Adicionar vídeo»; a outra pessoa é perguntada primeiro e pode dizer «Agora não». Funciona com apps que adicionam vídeo a uma chamada como o Conversations. Veja [XMPP](#xmpp).",
  "**Voice messages and replies in Nostr chats**: hold the microphone under the message box to send a voice message, which plays with Play; hold a message to reply to it, and the answer shows the message it is to, here and in other Nostr apps. See [Chats with other Nostr apps](#nostr-chats).":
    "**Mensagens de voz e respostas nas conversas do Nostr**: segure o microfone abaixo do campo de mensagem para enviar uma mensagem de voz, que toca com «Reproduzir»; segure uma mensagem para respondê-la, e a resposta mostra a mensagem a que responde, aqui e em outros apps Nostr. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**OMEMO 2 in XMPP chats**: a message to someone whose app speaks OMEMO 2, as Kaidan does, now goes with OMEMO 2 to that app and with OMEMO 0.3 to their others, as before. The XMPP screen shows this device's key both ways, to compare with what each app shows. See [XMPP](#xmpp).":
    "**OMEMO 2 nas conversas do XMPP**: uma mensagem para alguém cujo app fala OMEMO 2, como o Kaidan, agora vai com OMEMO 2 para esse app e com OMEMO 0.3 para os outros apps dele, como antes. A tela do XMPP mostra a chave deste dispositivo das duas maneiras, para comparar com o que cada app mostra. Veja [XMPP](#xmpp).",
  "**Hidden chats can have their own Matrix, XMPP and Nostr accounts**: under the list of a place of hidden chats, Matrix, XMPP and Nostr open an account of that place alone, apart from the space's, kept encrypted with the hidden chats' key. Its chats show among the hidden chats only. It connects while they are open, and while they are closed too if Receive while closed is on, as the hidden chats do: then a message says only \"New message\", and a call rings with no name and is answered with the PIN. See [Hidden chats](#hidden).":
    "**As conversas ocultas podem ter as próprias contas Matrix, XMPP e Nostr**: abaixo da lista de uma posição de conversas ocultas, Matrix, XMPP e Nostr abrem uma conta só daquela posição, separada da do espaço e guardada criptografada com a chave das conversas ocultas. As conversas dela aparecem só entre as conversas ocultas. Ela se conecta enquanto estão abertas, e também enquanto estão fechadas se Receber quando fechadas estiver ligado, como as próprias conversas ocultas: então uma mensagem diz só “Nova mensagem”, e uma chamada toca sem nome e é atendida com o PIN. Veja [Conversas ocultas](#hidden).",
  "**Matrix, XMPP and Nostr in backups**: a backup now holds the Matrix, XMPP and Nostr accounts of every space and of its hidden chats. After a restore, a Nostr key comes back with its chats as they were; an XMPP account goes on as a new device of the account, with its contacts and chats; a Matrix account is let go of on this phone, and the space signs in again as a new device; its Security Key opens the messages from before. See [Backups](#backup).":
    "**Matrix, XMPP e Nostr nos backups**: um backup agora guarda as contas Matrix, XMPP e Nostr de cada espaço e de suas conversas ocultas. Depois de restaurar, uma chave Nostr volta com suas conversas como estavam; uma conta XMPP segue como um novo dispositivo da conta, com seus contatos e conversas; uma conta Matrix é solta neste celular, e o espaço entra de novo como um novo dispositivo; a chave de segurança dele abre as mensagens de antes. Veja [Backups](#backup).",
  "**Matrix voice messages show their waveform, and Nostr answers can be photos**: a voice message sent in a Matrix chat carries its waveform, which Element draws, and one that comes with a waveform shows it under Play; in a Nostr chat, a photo, file or voice message sent while a message shows over the message box answers it. See [Matrix](#matrix) and [Chats with other Nostr apps](#nostr-chats).":
    "**As mensagens de voz do Matrix mostram sua forma de onda, e as respostas no Nostr podem ser fotos**: uma mensagem de voz enviada numa conversa Matrix leva sua forma de onda, que o Element desenha, e uma que chega com forma de onda a mostra abaixo de Reproduzir; numa conversa Nostr, uma foto, um arquivo ou uma mensagem de voz enviada enquanto uma mensagem aparece acima do campo a responde. Veja [Matrix](#matrix) e [Conversas com outros apps Nostr](#nostr-chats).",
  "**Group calls in XMPP groups**: in a private XMPP group, start a voice or video call, answer one that rings, or join one going on, together with people who use Dino. See [XMPP](#xmpp).":
    "**Chamadas de grupo nos grupos XMPP**: num grupo privado XMPP, inicie uma chamada de voz ou de vídeo, atenda uma que toca, ou entre numa que está acontecendo, junto com pessoas que usam o Dino. Veja [XMPP](#xmpp).",
  '**A call to a slow phone rings in full**: the caller now waits up to a minute and a quarter for the other phone to say it rings, and then 45 seconds from then, so a call that reached it late no longer rings there only to stop at once; and the phone called reads a call before anything it has to send, and waits for calls again at once after its network changes. See [Chat through a relay](#relay).':
    '**Uma chamada para um telefone lento toca inteira**: quem chama agora espera até um minuto e um quarto que o outro telefone diga que está tocando, e depois 45 segundos a partir daí, para que uma chamada que chegou tarde não toque mais só para parar logo em seguida; e o telefone chamado lê uma chamada antes de tudo o que tem para enviar, e volta a esperar chamadas logo após uma troca de rede. Veja [Conversar por um relay](#relay).',
  "**The web app and the computer reach Matrix, XMPP and Nostr servers over HTTPS**: their page policy allowed only WebSocket connections, so Matrix sign-in, XMPP server discovery and file sharing, and Nostr files and name lookups failed there. They work now. See [Matrix](#matrix), [XMPP](#xmpp) and [Chats with other Nostr apps](#nostr-chats).":
    "**O app web e o computador alcançam servidores Matrix, XMPP e Nostr por HTTPS**: a política da página deles só permitia conexões WebSocket, então o login no Matrix, a descoberta do servidor XMPP e o envio de arquivos, e os arquivos e as buscas de nomes do Nostr falhavam lá. Agora funcionam. Veja [Matrix](#matrix), [XMPP](#xmpp) e [Conversas com outros apps Nostr](#nostr-chats).",
  // 3.4.2
  '**A message sent as a chat opens waits for it**, marked Sending…, and goes as soon as the chat is open, never saying that Erevos cannot encrypt.':
    '**Uma mensagem enviada enquanto uma conversa abre espera por ela**, marcada Enviando…, e vai assim que a conversa abre, sem dizer que o Erevos não pode criptografar.',
  '**What you read as a chat opens stays read**: the home screen no longer counts it as new.':
    '**O que você lê enquanto uma conversa abre fica lido**: a tela inicial não conta mais como novo.',
  '**No question from Samsung about its sharing**: on a Samsung phone, Wi-Fi Aware and the Wi-Fi with phones nearby stay off until you turn them on. See [Chat with a nearby phone](#nearby).':
    '**Nenhuma pergunta da Samsung sobre o compartilhamento dela**: em um celular Samsung, o Wi-Fi Aware e a rede Wi-Fi com celulares por perto ficam desligados até você ligá-los. Veja [Conversar com um celular por perto](#nearby).',
  '**The SMS field keeps its width on a small screen**: Photo and Send beside it are round buttons, as in a chat.':
    '**O campo do SMS mantém a largura numa tela pequena**: Foto e Enviar ao lado são botões redondos, como numa conversa.',
  // 3.4.1
  '**Send answers at once**: a short buzz as you press it, the field empties and the message shows, marked Sending…, so it never goes twice.':
    '**Enviar responde na hora**: uma vibração curta ao tocar, o campo se esvazia e a mensagem aparece, marcada Enviando…, então nunca sai duas vezes.',
  '**The screen no longer stays pushed up** after the keyboard closed behind a sheet, a dialog or another app.':
    '**A tela não fica mais empurrada para cima** depois que o teclado se fechou atrás de um painel, de um diálogo ou de outro app.',
  '**Importing a chat with its photos no longer freezes Erevos**: the screen moves while the files come in, says what share of them is in, and **Cancel** stops it. A chat moved into hidden chats takes the chats imported into it along. See [Imported chats](#import).':
    '**Importar uma conversa com suas fotos não trava mais o Erevos**: a tela responde enquanto os arquivos chegam, diz que parte já chegou e **Cancelar** interrompe. Uma conversa movida para as conversas ocultas leva junto as conversas importadas nela. Veja [Conversas importadas](#import).',
  // 3.4.0
  '**Your relay proves its own key**: every connection to it starts with a check only the relay holding that key can pass, so no one in between can pass for it. Once it has, Erevos never reaches it without the check. Your relay needs an update for it.':
    '**O seu relay prova a própria chave**: cada conexão com ele começa com uma verificação em que só passa o relay que tem essa chave, então ninguém no meio pode se passar por ele. Depois que ele prova uma vez, o Erevos nunca mais se conecta a ele sem a verificação. Para isso, o seu relay precisa de uma atualização.',
  '[Transparency](#transparency), a new part of the guide: what the server behind Erevos keeps and for how long, what it does not keep, and who else sees something.':
    '[Transparência](#transparency), uma nova parte do guia: o que o servidor por trás do Erevos guarda e por quanto tempo, o que ele não guarda e quem mais vê alguma coisa.',
  "**What's new**: this list, in Settings → General, by version.": '**Novidades**: esta lista, em Configurações → Geral, por versão.',
  "**Nothing shows behind a chat's PIN**: none of the messages of a chat locked with a PIN is drawn until its PIN is typed, and with glass, a wallpaper or a style's own scene, the PIN screen is a dense frost that lets nothing through.":
    "**Nada aparece atrás do PIN de uma conversa**: nenhuma mensagem de uma conversa bloqueada com um PIN é mostrada antes de o PIN ser digitado, e com vidro, um papel de parede ou um estilo com cena própria, a tela do PIN é um fosco denso que não deixa ver nada.",
  "**A group video call from the top of the group**: a blue camera beside the green handset, as in a contact's chat.":
    "**Videochamada de grupo no topo do grupo**: uma câmera azul ao lado do fone verde, como na conversa com um contato.",
  "**A relay queue for each contact**: each contact writes to a queue only they know, so the relay cannot tell that two contacts write to the same phone, and deleting or blocking someone deletes only theirs. Your relay needs an update for it.":
    "**Uma fila do relay para cada contato**: cada contato escreve numa fila que só ele conhece, então o relay não consegue saber que dois contatos escrevem para o mesmo telefone, e apagar ou bloquear alguém apaga só a dele. Seu relay precisa ser atualizado para isso.",
  "**Hidden chats, more like the others**: they close after 30 seconds in the background, not at once, and never during a call or while you pick a photo or a file; while open, a message plays its sound, and link previews have a switch of their own there. See [Hidden chats](#hidden).":
    "**As conversas ocultas, mais como as outras**: fecham após 30 segundos em segundo plano, não de imediato, e nunca durante uma chamada nem enquanto você escolhe uma foto ou um arquivo; abertas, uma mensagem toca o seu som, e as pré-visualizações de links têm ali um interruptor próprio. Veja [Conversas ocultas](#hidden).",
  "**Hidden chats that receive while closed**: a switch at the top of each place, on for new places, has them receive as your other chats do: their contacts see at once that a message came, a notice says only \"New message\", and a call rings with no name. See [Hidden chats](#hidden).":
    "**Conversas ocultas que recebem quando fechadas**: um interruptor no topo de cada lugar, ligado nos lugares novos, faz com que recebam como as suas outras conversas: os contatos delas veem na hora que uma mensagem chegou, um aviso diz só “Nova mensagem”, e uma chamada toca sem nome. Veja [Conversas ocultas](#hidden).",
  "**Hidden chats wait and import too**: what cannot go now waits, marked Waiting, and goes by itself through their relay; Send later works there as in your other chats; and a chat from Telegram, WhatsApp or Viber can be imported into a hidden chat, kept only there. See [Hidden chats](#hidden).":
    "**As conversas ocultas também aguardam e importam**: o que não pode sair agora aguarda, marcado “Aguardando”, e sai sozinho pelo relay delas; “Enviar mais tarde” funciona ali como nas suas outras conversas; e uma conversa do Telegram, WhatsApp ou Viber pode ser importada para uma conversa oculta, guardada só ali. Veja [Conversas ocultas](#hidden).",
  "**Hidden chats listed like your chats**: they open on a list as the home screen's, with what was said last and how many are not read, and each place has a Chat with myself of its own at its top. See [Hidden chats](#hidden).":
    "**As conversas ocultas em lista como as suas conversas**: abrem numa lista como a da tela inicial, com o que foi dito por último e quantas não foram lidas, e cada posição tem no topo a sua própria Conversa comigo. Veja [Conversas ocultas](#hidden).",
  "**More in hidden chats**: with Receive while closed on, what comes to them through Nostr is read while they are closed too; and there a contact can be added from a photo of their QR code, and a hidden contact given a photo. See [Hidden chats](#hidden).":
    "**Mais nas conversas ocultas**: com Receber quando fechadas, o que lhes chega pelo Nostr também é lido enquanto estão fechadas; e lá é possível adicionar um contato a partir de uma foto do código QR dele e dar uma foto a um contato oculto. Veja [Conversas ocultas](#hidden).",
  "**Hidden chats with no relay**: as your other chats, they can begin through Nostr only: their contact link and QR code say where they read there, and texts and reactions go there. See [Hidden chats](#hidden).":
    "**Conversas ocultas sem relay**: como as suas outras conversas, podem começar só pelo Nostr: o link de contato e o código QR delas dizem onde leem lá, e textos e reações vão para lá. Veja [Conversas ocultas](#hidden).",
  "**Groups in hidden chats**: under their list, New group makes a group with their contacts; it lists among their chats, goes through their relay only, and is read while they are closed if Receive while closed is on. See [Hidden chats](#hidden).":
    "**Grupos nas conversas ocultas**: abaixo da lista delas, Novo grupo cria um grupo com os contatos delas; ele aparece entre as conversas delas, passa só pelo relay delas e é lido enquanto estão fechadas se Receber quando fechadas estiver ativado. Veja [Conversas ocultas](#hidden).",
  "**No test version line**: the home screen no longer ends saying this is a test version. The guide still says exactly what is protected, and that nothing has been audited yet. See [What is protected today](#privacy).":
    "**Sem a linha de versão de teste**: a tela inicial não termina mais dizendo que esta é uma versão de teste. O guia continua dizendo exatamente o que está protegido, e que nada foi auditado ainda. Veja [O que está protegido hoje](#privacy).",
  "**The contacts menu in hidden chats**: their Contacts has a menu again, with what is theirs only: a .vcf file imported into them, their contacts saved as a .vcf file, and a contact's QR code read from a photo. An Erevos ID typed there adds them to the hidden chats. See [Contacts](#contacts).":
    "**O menu de contatos nas conversas ocultas**: os Contatos delas voltam a ter um menu, só com o que é delas: um arquivo .vcf importado nelas, seus contatos salvos como arquivo .vcf e o código QR de um contato lido de uma foto. Um ID do Erevos digitado ali adiciona a pessoa às conversas ocultas. Veja [Contatos](#contacts).",
  // 3.3.2
  '**The plain call button for more contacts**: the orange keypad at the top of a contact’s chat also takes the number of a contact you connected them to (**Connect to one of my contacts**), the mobile number first.':
    '**O botão de chamada comum para mais contatos**: o teclado laranja no topo da conversa de um contato também usa o número do contato a que você o vinculou (**Vincular a um dos meus contatos**), primeiro o celular.',
  // 3.3.1
  '**Viber chats can be imported**: from the HTML file of the Android app Backup Text for Viber, words only.':
    '**Conversas do Viber podem ser importadas**: do arquivo HTML do app Android Backup Text for Viber, só os textos.',
  // 3.3.0
  '**Start without a relay, through Nostr**: **Start without a relay** on New chat. Texts, stickers, reactions, edits and the delivered and read marks go through Nostr over Tor. Photos, voice messages, files and calls still need a relay or a phone nearby.':
    '**Começar sem relay, pelo Nostr**: **Começar sem relay** em Nova conversa. Textos, figurinhas, reações, edições e as marcas de entregue e lida vão pelo Nostr, via Tor. Fotos, mensagens de voz, arquivos e chamadas ainda precisam de um relay ou de um celular por perto.',
  '**The relay comes by itself**: whoever has a relay that invites sends a contact with no relay an invite once, inside the chat, and the other phone takes it by itself.':
    '**O relay chega sozinho**: quem tem um relay que faz convites envia uma vez um convite a um contato sem relay, dentro da conversa, e o outro celular o aceita sozinho.',
  '**Told when a new version is out** (Android): once a day Erevos asks LPHL’s server, then shows a pinned Erevos row and a notice, only for a version the release computer signed. It turns off in Settings → General → Updates.':
    '**Aviso quando sai uma versão nova** (Android): uma vez por dia o Erevos pergunta ao servidor do LPHL e então mostra uma linha fixada do Erevos e uma notificação, só para uma versão assinada pelo computador de versões. Dá para desativar em Configurações → Geral → Atualizações.',
  '**Lock a chat with a PIN**: Details → Lock with a PIN, for chats and groups. Nothing of it shows in search, starred messages or imports. In hidden chats it asks for no PIN.':
    '**Bloquear uma conversa com um PIN**: Detalhes → Bloquear com um PIN, para conversas e grupos. Nada dela aparece na busca, nas mensagens favoritas nem nas importações. Nas conversas ocultas, não pede PIN.',
  '**A new handset** on the green tiles: Phone, and the call in a chat.': '**Um novo ícone de fone** nos blocos verdes: Telefone, e a chamada em uma conversa.',
  '**A new New chat screen**: How you connect now at the top, three large cards for a phone without a relay (I have an invite, Sign in with LPHL, Start without a relay), and the technical part under For advanced users.':
    '**Uma nova tela de Nova conversa**: Como você se conecta agora no topo, três cartões grandes para um celular sem relay (Tenho um convite, Entrar com LPHL, Começar sem relay) e a parte técnica em Para usuários avançados.',
  '**Nostr steadier through Tor**: each Nostr relay has its own way through Tor, and after a failure it tries a new exit. A clearer error on the Nostr screen.':
    '**Nostr mais estável pelo Tor**: cada relay Nostr tem o próprio caminho pelo Tor e, depois de uma falha, tenta uma nova saída. Um erro mais claro na tela do Nostr.',
  '**When the connection to the relay drops** while Erevos waits on it, Erevos notices and connects again, where it stayed stuck before.':
    '**Quando a conexão com o relay cai** enquanto o Erevos espera por ele, o Erevos percebe e se conecta de novo, onde antes ficava travado.',
  '**Invite by SMS** (Android): on a phone contact’s card, for one person, for 2 days. The link opens a page that offers Erevos (the APK for Android, the web app for an iPhone or a computer), then opens the invite. The QR code and Share the invite stay as they were.':
    '**Convidar por SMS** (Android): no cartão de um contato do celular, para uma pessoa, por 2 dias. O link abre uma página que oferece o Erevos (o APK para Android, o app web para iPhone ou computador) e depois abre o convite. O código QR e Compartilhar o convite continuam como estavam.',
  '**Fixes to the SMS invite**: a link copied as /i/#… works too, an older web app opens the invite as well, and on iOS 26 it says Share is under •••.':
    '**Correções no convite por SMS**: um link copiado como /i/#… também funciona, um app web mais antigo também abre o convite e, no iOS 26, avisa que Compartilhar fica em •••.',
  '**A phone call button** in Erevos chats and SMS chats.': '**Um botão de chamada telefônica** nas conversas do Erevos e nas conversas por SMS.',
  // 3.2.1
  '**Edit a message** you sent, up to a day after: to contacts, groups and linked devices, with Edited beside the time.':
    '**Editar uma mensagem** que você enviou, até um dia depois: para contatos, grupos e dispositivos conectados, com Editada ao lado do horário.',
  '**Nostr says what it did**: Sent through Nostr, and on the Nostr screen what each relay did last.':
    '**O Nostr diz o que fez**: Enviada pelo Nostr, e na tela do Nostr o que cada relay fez por último.',
  '**Coloured call buttons** at the top of a chat: video blue, voice green.': '**Botões de chamada coloridos** no topo de uma conversa: vídeo azul, voz verde.',
  // 3.2.0
  'Arrows to the start and the end of a chat; earlier messages come by themselves as you scroll.':
    'Setas para o início e o fim de uma conversa; as mensagens mais antigas carregam sozinhas conforme você rola.',
  'Chats imported from Telegram and WhatsApp look like Erevos messages: bubbles, days, photos, voice messages, search.':
    'As conversas importadas do Telegram e do WhatsApp aparecem como mensagens do Erevos: balões, dias, fotos, mensagens de voz, busca.',
  'Dogs instead of cats in the stickers.': 'Cachorros em vez de gatos nas figurinhas.',
  'Screenshots: a switch in Settings → Privacy and security.': 'Capturas de tela: uma opção em Configurações → Privacidade e segurança.',
  'Hidden chats from New chat: hold it for a second.': 'Conversas ocultas a partir de Nova conversa: mantenha pressionado por um segundo.',
  'Coloured tiles on the home screen: Phone green, Contacts violet, the lock orange.': 'Blocos coloridos na tela inicial: Telefone verde, Contatos roxo, o cadeado laranja.',
  '**Chat with myself**, always first, and **Remind me**, the orange bell.': '**Conversa comigo**, sempre em primeiro, e **Lembrar-me**, o sino laranja.',
  '**Media, links and files** in a chat’s Details, with a calendar and Go to a day.':
    '**Mídia, links e arquivos** nos Detalhes de uma conversa, com um calendário e Ir para um dia.',
  'Import a chat from inside the chat: Details → Imported chats.': 'Importar uma conversa de dentro da própria conversa: Detalhes → Conversas importadas.',
  'A closed space can say that a message came while another space is open.': 'Um espaço fechado pode avisar que chegou uma mensagem enquanto outro espaço está aberto.',
  'The message menu says when a message went or came through Nostr.': 'O menu da mensagem diz quando uma mensagem foi ou veio pelo Nostr.',
  '**Support Erevos**: Liberapay, PayPal, Monero, Bitcoin.': '**Apoiar o Erevos**: Liberapay, PayPal, Monero, Bitcoin.',
  'Who makes Erevos and why, in About Erevos; the guide says why everywhere.': 'Quem faz o Erevos e por quê, em Sobre o Erevos; o guia explica o porquê em toda parte.',
  // 3.1.2
  '**Settings in 8 groups**, with a search: General, Appearance, Notifications, Privacy and security, Relay and networks, Phone and SMS, Data and devices, For testing. The home screen’s ⋯ keeps only the places, and Settings last.':
    '**Configurações em 8 grupos**, com busca: Geral, Aparência, Notificações, Privacidade e segurança, Relay e redes, Telefone e SMS, Dados e dispositivos, Para testes. O ⋯ da tela inicial fica só com os lugares, e Configurações por último.',
  // 3.1.1
  'Check for updates says what stopped an update.': 'Procurar atualizações diz o que impediu uma atualização.',
  'Invite someone is not made from a token for all; it asks you to sign in to the relay first.':
    'Convidar alguém não usa mais um token compartilhado; antes, pede que você entre no relay.',
  'The relay’s token for all becomes a token of the phone’s own, by itself (needs the relay updated).':
    'O token compartilhado do relay vira sozinho um token próprio do celular (precisa do relay atualizado).',
  'A relay that refuses through Tor says why.': 'Um relay que recusa pelo Tor diz por quê.',
  // 3.1.0
  'Less battery in the background: the relay, Tor and the nearby radios.': 'Menos bateria em segundo plano: o relay, o Tor e os rádios para celulares por perto.',
  'Erevos no longer closes when you make a sticker from a photo.': 'O Erevos não fecha mais quando você faz uma figurinha a partir de uma foto.',
  'Hidden chats’ notices are right.': 'As notificações das conversas ocultas estão corretas.',
  'Hidden chats by holding New chat.': 'Conversas ocultas mantendo Nova conversa pressionado.',
  'A search for contacts on the Phone.': 'Busca de contatos no Telefone.',
  'New chat shows first how to add a contact.': 'Nova conversa mostra primeiro como adicionar um contato.',
  'A call shows over the screen saver, and the screen wakes.': 'Uma chamada aparece sobre o protetor de tela, e a tela acende.',
  'Erevos in other apps’ Share.': 'O Erevos no Compartilhar dos outros apps.',
  'A sound for every new message, also while Erevos shows.': 'Um som para cada mensagem nova, também com o Erevos na tela.',
  'The SMS settings say right what holding does.': 'As configurações de SMS dizem corretamente o que acontece ao manter pressionado.',
  // 3.0.0
  'Each icon opens what it names: Erevos, SMS, Phone, Contacts, the widget.': 'Cada ícone abre o que o nome diz: Erevos, SMS, Telefone, Contatos, o widget.',
  '**Messages through Tor by default**: Messages, Everything or Nothing.': '**Mensagens pelo Tor por padrão**: Mensagens, Tudo ou Nada.',
  '**Texts through Nostr**: three public relays, through Tor, with your own relay as backup after 5 minutes.':
    '**Textos pelo Nostr**: três relays públicos, pelo Tor, com o seu próprio relay como reserva depois de 5 minutos.',
  // 2.0.3
  'One invite for everything: the relay and the contact together.': 'Um convite para tudo: o relay e o contato juntos.',
  'Spam rules for senders and numbers abroad, with the reason.': 'Regras de spam para remetentes e números do exterior, com o motivo.',
  '480 stickers in 20 sets.': '480 figurinhas em 20 pacotes.',
  'Lighter chats on older phones; QR codes at once.': 'Conversas mais leves em celulares antigos; códigos QR na hora.',
  'Copy code for one-time codes in SMS.': 'Copiar código para os códigos de uso único nos SMS.',
  'Locked, Erevos keeps receiving.': 'Bloqueado, o Erevos continua recebendo.',
  'Faster contacts; the hidden chats’ notice counts only messages.': 'Contatos mais rápidos; a notificação das conversas ocultas conta só mensagens.',
  'The relay tries every address: push, other relays, the LPHL sign-in.': 'O relay tenta todos os endereços: push, outros relays, o login do LPHL.',
  // 2.0.2
  'Swiping on the tabs only changes the tab.': 'Deslizar nas abas só troca de aba.',
  'The icons fill the launcher’s shape.': 'Os ícones preenchem o formato do launcher.',
  // 2.0.1
  'Coloured icons (Erevos red, Phone green, SMS blue, Contacts violet) and a new SMS icon.':
    'Ícones coloridos (Erevos vermelho, Telefone verde, SMS azul, Contatos roxo) e um novo ícone de SMS.',
  'A colour for each icon, and the order of the widget’s buttons.': 'Uma cor para cada ícone, e a ordem dos botões do widget.',
  'Swipe to go back, and between tabs.': 'Deslizar para voltar, e entre as abas.',
  // 2.0.0
  'An update of the WebView no longer closes Erevos.': 'Uma atualização do WebView não fecha mais o Erevos.',
  'Deleting or blocking a contact gives you a new queue on the relay.': 'Apagar ou bloquear um contato dá a você uma nova fila no relay.',
  'A new contact can take the name of a contact on the phone.': 'Um novo contato pode usar o nome de um contato do celular.',
  '**Sign in to the relay with LPHL**, and **invites to the relay**.': '**Entrar no relay com LPHL**, e **convites para o relay**.',
  'Permissions in the web app, and more on Android; the web app’s notice says how many came.':
    'Permissões no app web, e mais no Android; a notificação do app web diz quantas mensagens chegaram.',
  'Hidden chats can ring calls while they are closed.': 'As conversas ocultas podem tocar as chamadas enquanto estão fechadas.',
  'New keys every month in chats, every week in groups.': 'Chaves novas todo mês nas conversas, toda semana nos grupos.',
  'Linked devices work with the phone off.': 'Os dispositivos conectados funcionam com o celular desligado.',
  'A new chat screen; QR codes from a photo; the Phone for small screens.': 'Uma nova tela de conversa; códigos QR a partir de uma foto; o Telefone para telas pequenas.',
  'Add as contact inside a group.': 'Adicionar como contato dentro de um grupo.',
  'Stickers in sets, moving, and your own.': 'Figurinhas em pacotes, animadas, e as suas próprias.',
  'SMS inside the Erevos chat.': 'SMS dentro da conversa do Erevos.',
  'Android updates need the release computer’s signature.': 'As atualizações para Android precisam da assinatura do computador de versões.',
  'An F-Droid build; Serbo-Croatian; new version numbers.': 'Uma versão para o F-Droid; servo-croata; novos números de versão.',
  'Much for security: Argon2id, messages encrypted for the relay too, a token for each phone, no link starts a call.':
    'Muito para a segurança: Argon2id, mensagens criptografadas também para o relay, um token para cada celular, nenhum link inicia uma chamada.',
  // 0.1.16
  'Imports from Telegram and WhatsApp bring photos, videos, voice messages and files.': 'As importações do Telegram e do WhatsApp trazem fotos, vídeos, mensagens de voz e arquivos.',
  'A phone without a relay talks through a place on a contact’s relay.': 'Um celular sem relay se comunica por um lugar no relay de um contato.',
  // 0.1.14
  'Back to my chats, for hidden chats.': 'Voltar para minhas conversas, para as conversas ocultas.',
  'Erevos receives and rings even after you swipe it away from the recent apps.': 'O Erevos recebe e toca mesmo depois que você o fecha nos apps recentes.',
  // 0.1.12
  'Hidden chats can say a message came.': 'As conversas ocultas podem avisar que chegou uma mensagem.',
  'Fixes: menus, QR codes from a photo, Bluetooth on Android 17, long lists.': 'Correções: menus, códigos QR a partir de uma foto, Bluetooth no Android 17, listas longas.',
  // 0.1.11
  'The Phone without the password, if you allow it; a home screen widget; an SMS and Erevos filter.':
    'O Telefone sem a senha, se você permitir; um widget para a tela inicial; um filtro de SMS e Erevos.',
  // 0.1.10
  'Links wait for the password; Phone and Contacts icons; the Erevos ID on a contact.': 'Os links esperam a senha; ícones de Telefone e Contatos; o ID do Erevos em um contato.',
  // 0.1.8
  '61 new features: 5 new languages, linked devices, public groups, replies, reactions, polls, send later, Erevos as the phone and contacts app, Tor bridges, the fingerprint, Windows and more.':
    '61 recursos novos: 5 idiomas novos, dispositivos conectados, grupos públicos, respostas, reações, enquetes, enviar mais tarde, o Erevos como app de telefone e de contatos, pontes do Tor, a impressão digital, Windows e mais.',
  // 0.1.7 to 0.1.2
  'SMS notices in the background.': 'Notificações de SMS em segundo plano.',
  'The web app comes out with every release.': 'O app web sai junto com cada versão.',
  'Greek in the whole app.': 'Grego no app inteiro.',
  'Web Push in the web app.': 'Web Push no app web.',
  'The first signed Android release: encrypted chats, calls, groups, hidden chats, backups, imports, and phones nearby without the internet.':
    'A primeira versão assinada para Android: conversas criptografadas, chamadas, grupos, conversas ocultas, backups, importações e celulares por perto sem internet.',
  "**Two new sticker sets of 24 moods**: **Tux**, the Linux penguin as he is drawn, and **Aikido**, an aikidoka in keikogi and a wide hakama, who also bows, sits in seiza and rolls.":
    "**Dois novos conjuntos de figurinhas com 24 humores**: **Tux**, o pinguim do Linux tal como é desenhado, e **Aikido**, um aikidoka de keikogi e hakama largo, que também se curva, senta-se em seiza e rola.",
  "**A new sticker set, Takis**: a caricature in a dark suit and a purple tie with dots, in 24 moods that move.":
    "**Um novo conjunto de figurinhas, Takis**: uma caricatura de terno escuro e gravata roxa de bolinhas, em 24 humores que se mexem.",
  "**Photos, files and voice messages with no relay**: when there is no relay between you and your contact and they read on Nostr, a voice message goes through Nostr like a text, a photo up to 3 MB in pieces, and a larger photo, a video or another file, up to 20 MB, to an encrypted file server (Blossom), all through Tor. See [Through Nostr](#nostr).":
    "**Fotos, arquivos e mensagens de voz sem relay**: quando não há relay entre você e o seu contato e ele lê no Nostr, uma mensagem de voz vai pelo Nostr como um texto, uma foto de até 3 MB em pedaços, e uma foto maior, um vídeo ou outro arquivo, de até 20 MB, para um servidor de arquivos cifrado (Blossom), tudo pelo Tor. Veja [Pelo Nostr](#nostr).",
  "**More battery saved in the background, if you choose**: under Settings → Notifications → In the background, Only the waste stays the default; And nearby phones also turns off the radios for phones nearby while Erevos is in the background; And sleep also lets the phone sleep, so Erevos looks at your relay about once a minute and a message or a call can be a minute or two late. Android only. See [Chat through a relay](#relay).":
    "**Mais bateria poupada em segundo plano, se você escolher**: em Configurações → Notificações → Em segundo plano, Só o desperdício continua sendo o padrão; E os celulares por perto desliga também os rádios para celulares por perto enquanto o Erevos está em segundo plano; E o sono deixa também o celular dormir, de modo que o Erevos olha o seu relay cerca de uma vez por minuto e uma mensagem ou uma chamada pode chegar um ou dois minutos atrasada. Só no Android. Veja [Conversar por um relay](#relay).",
  "**A contact you delete no longer comes back from an old ask**: in a group, a member you asked for their contact link, or who asked for yours, and whom you then deleted as a contact before Erevos looked at the relay again, could be added again by that old ask. Deleting them now lets go of it at once. See [Group chats](#groups).":
    "**Um contato apagado não volta mais por um pedido antigo**: num grupo, um membro cujo link de contato você pediu, ou que pediu o seu, e que depois você apagou como contato antes de o Erevos olhar o relay de novo, podia ser adicionado outra vez por esse pedido antigo. Agora apagá-lo larga o pedido na hora. Veja [Conversas em grupo](#groups).",
  "**Every message says which way it went**: hold a message and its menu says whether it went or came through the relay, through Nostr, to a phone nearby or over LoRa. Messages from before say nothing. See [Through Nostr](#nostr).":
    "**Cada mensagem diz por onde foi**: segure uma mensagem e o menu dela diz se foi ou veio pelo relay, pelo Nostr, por um telefone por perto ou por LoRa. As mensagens de antes não dizem nada. Veja [Pelo Nostr](#nostr).",
  "**The spam filter reads words as they look**: a scam text that swaps a letter for a look-alike of another alphabet, or hides a mark that shows nothing inside a word, no longer gets past it. See [SMS](#sms).":
    "**O filtro de spam lê as palavras como elas aparecem**: um SMS de golpe que troca uma letra por uma parecida de outro alfabeto, ou esconde numa palavra uma marca que não se vê, já não o engana. Veja [SMS](#sms).",
  "**Media, links and files in groups too**: in a group's details, a list of its photos, videos, voice messages, music, files and links, each kind apart under its months, with a calendar, as in a contact's chat. A tap opens or plays; held, each goes to its message. See [Group chats](#groups).":
    "**Mídia, links e arquivos também nos grupos**: nos detalhes de um grupo, uma lista das suas fotos, vídeos, mensagens de voz, músicas, arquivos e links, cada tipo à parte sob os seus meses, com um calendário, como na conversa de um contato. Um toque abre ou toca; segurado, cada um vai até a sua mensagem. Veja [Conversas em grupo](#groups).",
  "**A relay restart no longer brings a false notice**: after your relay restarted, a hidden chat or a closed space said New message once more for messages it had told of already. Your relay needs an update for it. See [Hidden chats](#hidden).":
    "**Um reinício do relay não traz mais um aviso falso**: depois que o seu relay reiniciava, uma conversa oculta ou um espaço fechado dizia de novo Nova mensagem por mensagens de que já tinha avisado. O seu relay precisa de uma atualização para isso. Veja [Conversas ocultas](#hidden).",
  "**Backups to your server through Tor**: on Android, automatic backups sent to your own server now follow the space's choice under Settings → Relay and networks → Tor, as Matrix does, so with Tor the server no longer sees where you are. To a server too says when they go through Tor. See [Backups](#backup).":
    "**Backups para o seu servidor pelo Tor**: no Android, os backups automáticos enviados ao seu próprio servidor agora seguem a escolha do espaço em Configurações → Relay e redes → Tor, como o Matrix, então com Tor o servidor não vê mais onde você está. Também para um servidor diz quando vão pelo Tor. Veja [Backups](#backup).",
  "**Restore a backup straight from your server**: Restore from a server, under Backups, lists the backups on your server, newest first, and opens the one you choose with its password, with no download by hand, on a new phone too. See [Backups](#backup).":
    "**Restaure um backup direto do seu servidor**: Restaurar de um servidor, em Backups, mostra os backups no seu servidor, os mais recentes primeiro, e abre o que você escolher com a senha dele, sem baixar à mão, num celular novo também. Veja [Backups](#backup).",
  "**Backups to your server from a computer and the web app too**: in the desktop app, automatic backups go to your WebDAV server as on Android; in the web app, Send a backup now sends one there, with a server that lets the web app in. Both can restore from it. Not through Tor. See [Backups](#backup).":
    "**Backups para o seu servidor também do computador e do web app**: no app para computador, os backups automáticos vão para o seu servidor WebDAV como no Android; no web app, Enviar um backup agora envia um para lá, com um servidor que deixe o web app entrar. Os dois podem restaurar a partir dele. Não pelo Tor. Veja [Backups](#backup).",
  "**Check a contact in person with QR codes**: under Safety number in a chat's details, each phone shows a code; take a photo of the code on the other phone, and they of yours. When it matches, the contact is marked Checked in person. Nothing is sent. See [Chat through a relay](#relay).": "**Confira um contato pessoalmente com códigos QR**: em Número de segurança, nos detalhes de uma conversa, cada celular mostra um código; tire uma foto do código no outro celular, e a pessoa do seu. Quando bate, o contato fica marcado como Conferido pessoalmente. Nada é enviado. Veja [Conversar por um relay](#relay).",
  "**Up to three home relays**: under Settings → Relay and networks → Home relay, Add another home relay gives a space up to two more, each with a queue of its own. Your contact link and your messages name them in order, and contacts try each while the ones before cannot be reached. See [Home relay](#home-relay).": "**Até três relays de casa**: em Configurações → Relay e redes → Relay de casa, Adicionar outro relay de casa dá a um espaço até mais dois, cada um com sua própria fila. Seu link de contato e suas mensagens citam todos em ordem, e os contatos tentam cada um enquanto os anteriores não respondem. Veja [Relay de casa](#home-relay).",
  "**Introduce two of your contacts**: in a contact's chat details, Introduce to a contact asks them and another contact of yours, each in your chat with them. Only if both say yes do they become contacts, and neither learns whether the other said no. See [Chat through a relay](#relay).": "**Apresente dois dos seus contatos**: nos detalhes da conversa de um contato, Apresentar a um contato pergunta a ele e a outro contato seu, cada um na sua conversa com ele. Só se os dois disserem sim eles viram contatos, e nenhum fica sabendo se o outro disse não. Veja [Conversar por um relay](#relay).",
  "**Bluetooth that cannot be followed**: the random number your phone sends out over Bluetooth for phones nearby to find it changed only when Erevos started again; it now changes every nine to twelve minutes, so someone listening cannot follow your phone from place to place by it. Older Erevos phones still find yours. See [Chat with a nearby phone](#nearby).": "**Bluetooth que não dá para seguir**: o número aleatório que seu celular emite por Bluetooth para os celulares por perto o acharem só mudava quando o Erevos reiniciava; agora muda a cada nove a doze minutos, então quem escuta não consegue seguir seu celular de um lugar a outro por ele. Celulares com um Erevos mais antigo ainda acham o seu. Veja [Conversar com um celular por perto](#nearby).",
  "**Hidden chats show at once**: as the PIN opens them, their chats and contacts show at once, to read, while what they were receiving in the background ends; before, that could hold them back a long while, as it may go through Tor. See [Hidden chats](#hidden).": "**As conversas ocultas aparecem na hora**: assim que o PIN as abre, suas conversas e contatos aparecem na hora, para ler, enquanto termina o que elas recebiam em segundo plano; antes, isso podia atrasá-las por muito tempo, pois pode passar pelo Tor. Veja [Conversas ocultas](#hidden).",
  "**Your backup password in pieces with friends**: under Settings → Data and devices → Backup pieces, give pieces of it to 3 to 5 contacts; any 2 or 3 of them give it back, one alone shows nothing. Each goes inside the encryption of your chat with them and only their Erevos keeps it; your phone keeps none. See [Backup pieces with friends](#backup-pieces).": "**A senha dos seus backups em partes com amigos**: em Configurações → Dados e dispositivos → Partes do backup, dê partes dela a 3 a 5 contatos; quaisquer 2 ou 3 a devolvem, uma sozinha não mostra nada. Cada uma vai dentro da criptografia da sua conversa com eles e só o Erevos deles a guarda; seu celular não guarda nenhuma. Veja [Partes do backup com amigos](#backup-pieces).",
  "**Panic button**: under Settings → Privacy and security → Panic button, wipe everything Erevos keeps here with one tap, on Android and in the web app. On Android, a panic app such as Ripple can do it too, but only the one you say yes to, checked by its signature. See [Panic button](#panic).": "**Botão de pânico**: em Configurações → Privacidade e segurança → Botão de pânico, apague com um toque tudo o que o Erevos guarda aqui, no Android e no app web. No Android, um app de pânico como o Ripple também pode fazer isso, mas só aquele a que você disser sim, conferido pela assinatura dele. Veja [Botão de pânico](#panic).",
  "**Erevos to a phone nearby, with no internet**: under Settings → General → Give Erevos to a phone nearby, this phone serves its Erevos over the same Wi-Fi or its hotspot for ten minutes, with a QR code. A phone without Erevos downloads it in the browser; one with an older Erevos takes it under Updates → From a phone nearby, which installs it only when it is Erevos, signed as that one is. See [Erevos to a phone nearby](#give-app).": "**O Erevos para um telefone próximo, sem internet**: em Configurações → Geral → Dar o Erevos a um telefone próximo, este telefone serve o Erevos dele pela mesma Wi-Fi ou pelo hotspot dele por dez minutos, com um código QR. Um telefone sem o Erevos o baixa no navegador; um com um Erevos mais antigo o recebe em Atualizações → De um telefone próximo, que só o instala se for o Erevos, assinado como aquele. Veja [O Erevos para um telefone próximo](#give-app).",
  "**Hidden chats with phones nearby**: while hidden chats are open, or receive while closed, they reach a contact's phone nearby over Bluetooth, Wi-Fi Aware, Wi-Fi Direct or the same Wi-Fi, with no internet, as your other chats do. The space never learns that a hidden contact is near, and nothing on the air tells their messages from the space's; other phones never carry them, and they never go over LoRa or by SMS. See [Hidden chats](#hidden).":
    "**Conversas ocultas com celulares por perto**: enquanto as conversas ocultas estão abertas, ou recebem fechadas, elas chegam ao celular de um contato por perto por Bluetooth, Wi-Fi Aware, Wi-Fi Direct ou na mesma rede Wi-Fi, sem internet, como suas outras conversas. O espaço nunca fica sabendo que um contato oculto está por perto, e nada no ar distingue as mensagens delas das do espaço; outros celulares nunca as levam, e elas nunca vão por LoRa nem por SMS. Veja [Conversas ocultas](#hidden).",
  "**The same Wi-Fi on Sailfish OS**: Erevos on Sailfish OS finds Erevos phones and computers on the same Wi-Fi or a phone's hotspot and talks with them with no internet, as on a computer. See [On Sailfish OS](#sailfish).":
    "**A mesma rede Wi-Fi no Sailfish OS**: o Erevos no Sailfish OS encontra celulares e computadores com Erevos na mesma rede Wi-Fi ou no roteador de um celular e conversa com eles sem internet, como num computador. Veja [No Sailfish OS](#sailfish).",
  "**Downloads stop at 100 MB**: a file, a backup from a server or any other download is read as it comes and stopped as soon as it passes 100 MB, or less where the network's files are smaller, such as 20 MB for Nostr files, so a file server a contact names can no longer fill the phone's memory with an answer without end. A backup on a server comes back up to 100 MB; download a larger one and open it with Restore a backup. See [Backups](#backup).":
    "**Os downloads param em 100 MB**: um arquivo, um backup de um servidor ou qualquer outro download é lido conforme chega e interrompido assim que passa de 100 MB, ou de menos onde os arquivos da rede são menores, como 20 MB para os arquivos do Nostr, então um servidor de arquivos que um contato indica não consegue mais encher a memória do celular com uma resposta sem fim. Um backup num servidor volta até 100 MB; baixe um maior e abra-o com Restaurar um backup. Veja [Backups](#backup).",
  "**Profile pictures on Matrix and XMPP**: contacts and Matrix rooms show their picture in the chat list, and you can set your own on the Matrix and XMPP screens (Choose a photo). Pictures are not encrypted on either network: the server sees them. See [Matrix](#matrix) and [XMPP](#xmpp).":
    "**Fotos de perfil no Matrix e no XMPP**: contatos e salas do Matrix mostram a foto na lista de conversas, e você pode pôr a sua nas telas do Matrix e do XMPP (Escolher uma foto). As fotos não são criptografadas em nenhuma das duas redes: o servidor as vê. Veja [Matrix](#matrix) e [XMPP](#xmpp).",
  "**Run an XMPP group**: a group's admins can set its subject and take people out or bar them, its owner can rename it and make admins, and in a channel the admin sees who is in it and can put them out. See [XMPP](#xmpp).":
    "**Gerenciar um grupo XMPP**: os admins de um grupo definem o assunto e removem ou banem pessoas, o dono o renomeia e faz admins, e num canal o admin vê quem está dentro e pode tirá-lo. Veja [XMPP](#xmpp).",
  "**Check a Matrix device by QR code**: once both sides accept a check, Erevos shows a code for Element (or another Erevos) to photograph, or photographs theirs, as Element does; comparing emoji stays one tap away. See [Matrix](#matrix).":
    "**Verificar um dispositivo Matrix por código QR**: quando os dois lados aceitam uma verificação, o Erevos mostra um código para o Element (ou outro Erevos) fotografar, ou fotografa o deles, como o Element faz; comparar emoji continua a um toque. Veja [Matrix](#matrix).",
  "**Sign in to Matrix with single sign-on** (Android): when your Matrix server signs people in on its own page, as matrix.org does, Sign in with single sign-on opens it in the browser and comes back to Erevos. See [Matrix](#matrix).":
    "**Entrar no Matrix com início de sessão único** (Android): quando o teu servidor Matrix faz entrar as pessoas na própria página, como o matrix.org, «Entrar com login único (SSO)» abre-a no navegador e volta ao Erevos. Ver [Matrix](#matrix).",
  "**A closed space tells of XMPP messages**: on Android, Say a message came under While this space is closed, on the XMPP screen, has a closed space say \"New message\" when something comes on XMPP while another space is open, never what, from whom or in which chat. Off until you choose it. It needs a relay updated for it and an XMPP server that sends notices to apps that are away; the XMPP server then learns the relay's name, and the relay when messages come. See [XMPP](#xmpp).":
    "**Um espaço fechado avisa de mensagens do XMPP**: no Android, “Avisar quando chega mensagem” em “Enquanto este espaço está fechado”, na tela do XMPP, faz um espaço fechado dizer “Nova mensagem” quando chega algo no XMPP enquanto outro espaço está aberto, nunca o quê, de quem ou em qual conversa. Desligado até você escolher. Precisa de um relay atualizado para isso e de um servidor XMPP que envie avisos a apps inativos; o servidor XMPP fica então sabendo o nome do relay, e o relay quando chegam mensagens. Ver [XMPP](#xmpp).",
  "**Linking a computer is clearer**: on a computer, Settings → Data and devices → Linked devices now starts with Link to my phone, with LPHL's relay filled in and Sign in with LPHL under the token, so no token has to be copied from the phone; and it says that the QR code shows once Link to my phone is tapped. See [Linked devices](#devices).":
    "**Conectar um computador ficou mais claro**: no computador, Configurações → Dados e dispositivos → Dispositivos conectados agora começa com “Conectar ao meu celular”, com o relay do LPHL já preenchido e “Entrar com LPHL” embaixo do token, então não é preciso copiar nenhum token do celular; e avisa que o código QR aparece quando você toca em “Conectar ao meu celular”. Veja [Dispositivos conectados](#devices).",
  "**Delete me from everywhere**: Settings → Privacy and security → Delete me from everywhere deletes what the servers keep for the open space (its queues on the relays with the messages in them, what a relay holds for you to send later, files waiting there, invites nobody used), asks the Nostr relays through Tor to forget the keys your chats read on, and stops the space until you tap Start again. Your phone keeps everything. You can also sign out of Matrix and XMPP and delete the Nostr account made here. See [Delete me from everywhere](#forget).": "**Apagar-me de todos os lugares**: Configurações → Privacidade e segurança → Apagar-me de todos os lugares apaga o que os servidores guardam do espaço aberto (as filas dele nos relays com as mensagens dentro, o que um relay guarda para enviar depois, arquivos que esperam lá, convites que ninguém usou), pede pelo Tor aos relays do Nostr que esqueçam as chaves em que suas conversas leem, e para o espaço até você tocar em Iniciar de novo. Seu celular mantém tudo. Você também pode sair do Matrix e do XMPP e apagar a conta Nostr criada aqui. Veja [Apagar-me de todos os lugares](#forget).",
  "**Every relay queue on one list**: the queues a space keeps on the relays are gathered in one place, and the checks fail if a new kind of queue is made without being added there, so Delete me from everywhere cannot leave one behind.": "**Cada fila de relay em uma lista**: as filas que um espaço guarda nos relays ficam reunidas em um só lugar, e as verificações falham se um novo tipo de fila for criado sem entrar lá, para que Apagar-me de todos os lugares não deixe nenhuma para trás.",
  "**Matrix, XMPP and Nostr on a linked computer**: linking a computer can bring this space's Matrix and XMPP accounts and the key of its Nostr chats over too, each signed in there as a new device of its own; for a computer linked already, tap Send the accounts under it on the phone. A Matrix server seldom lets the phone sign the computer in: the computer then asks for the Matrix password once, and the account's keys come from the phone, so no Security Key or check by emoji is needed. See [Linked devices](#devices).":
    "**Matrix, XMPP e Nostr num computador conectado**: ao conectar um computador, dá para levar também as contas Matrix e XMPP deste espaço e a chave das conversas Nostr dele, cada uma entrando lá como um novo dispositivo próprio; para um computador já conectado, toque em “Enviar as contas” embaixo dele no celular. Um servidor Matrix raramente deixa o celular fazer o computador entrar: o computador então pede a senha do Matrix uma vez, e as chaves da conta vêm do celular, então não é preciso chave de segurança nem verificar por emoji. Veja [Dispositivos conectados](#devices).",
  "**Only the SMS**: with Erevos locked, the SMS icon, the widget's SMS button and the notice of a new SMS ask for the password, then open only the SMS. Anything else, and the orange padlock **Unlock everything**, asks for it again, then opens all of Erevos. See [Password lock](#lock).":
    "**Só os SMS**: com o Erevos bloqueado, o ícone de SMS, o botão SMS do widget e o aviso de um SMS novo pedem a senha e depois abrem só os SMS. Todo o resto, inclusive o cadeado laranja **Desbloquear tudo**, pede a senha de novo e depois abre todo o Erevos. Veja [Bloqueio com senha](#lock).",
  "**Nostr chats with a key brought from another app get their messages again**: Erevos reads where that app said your messages arrive, as that app does, instead of its own three relays, fetches the messages kept there and in older lists of the key, and reads a relay again when it stops sending. Before, such a key could show its chats with no past messages and get no new ones. See [Chats with other Nostr apps](#nostr-chats).":
    "**As conversas Nostr com uma chave trazida de outro app voltam a receber suas mensagens**: o Erevos lê onde esse app disse que chegam as suas mensagens, como esse app faz, em vez dos seus três relays próprios, busca as mensagens guardadas ali e nas listas anteriores da chave, e volta a ler um relay quando ele para de enviar. Antes, uma chave assim podia mostrar suas conversas sem mensagens antigas e não receber novas. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Backups keep what closed chats need**: a backup now also holds what lets hidden chats ring a call and say a message came while they are closed, and a closed space say one came. So after a restore, on another phone too, **Ring calls when closed**, **Say when a message comes** and **Also while another space is open** go on as they were. See [Backups](#backup).":
    "**Os backups guardam o que as conversas fechadas precisam**: um backup agora guarda também o que deixa as conversas ocultas tocarem uma chamada e avisarem que chegou uma mensagem enquanto estão fechadas, e um espaço fechado avisar que chegou uma. Assim, depois de uma restauração, também em outro celular, **Tocar as chamadas quando fechadas**, **Avisar quando chega uma mensagem** e **Também enquanto outro espaço está aberto** continuam como estavam. Veja [Backups](#backup).",
  "**Open another space from the search**: type another space's password in **Search chats** on the home screen and press Enter: the open space closes, nothing of it stays, and the other opens, as with **Lock now** and its password. It takes as long whatever is typed, and a wrong password, or the open space's own, is just a search. See [Second password](#second).":
    "**Abrir outro espaço pela busca**: digite a senha de outro espaço em **Buscar conversas** na tela inicial e toque em Enter: o espaço aberto se fecha, sem que nada dele fique, e o outro se abre, como com **Bloquear agora** e a senha dele. Leva o mesmo tempo seja o que for digitado, e uma senha errada, ou a do espaço aberto, é só uma busca. Veja [Segunda senha](#second).",
  "**A dot for unread messages elsewhere, if you want it**: hidden chats with **Receive while closed** can show a small dot on the magnifier of **Search chats** while they have a message unread (their switch **Dot for unread messages**), and a space set to say a message came while another is open can show one on the padlock at the top of the other spaces' chats (**Dot in the other spaces**). Never how many, nor where; off unless you turn it on. See [Hidden chats](#hidden).":
    "**Um ponto para não lidas em outro lugar, se você quiser**: as conversas ocultas com **Receber quando fechadas** podem mostrar um pequeno ponto na lupa de **Buscar conversas** enquanto tiverem uma mensagem não lida (o interruptor delas **Ponto para não lidas**), e um espaço que avisa que chegou uma mensagem enquanto outro está aberto pode mostrar um no cadeado acima das conversas dos outros espaços (**Ponto nos outros espaços**). Nunca quantas, nem onde; desligado, a menos que você ligue. Veja [Conversas ocultas](#hidden).",
  "**Joining takes only the invite**: on a phone with no relay yet, **New chat** shows one way in, **I have an invite**. Signing in with LPHL, **Start without a relay** and the relay's settings are under **For advanced users**, for whoever looks for them. And an invite to your relay gives the relay only a name of random letters and digits for the phone it lets in: the name you type stays on your phone, where your list of invites shows it. See [Chat through a relay](#relay).":
    "**Para entrar, basta o convite**: num celular ainda sem relay, **Nova conversa** mostra uma forma de entrar, **Tenho um convite**. O login com LPHL, **Começar sem relay** e as configurações do relay ficam em **Para usuários avançados**, para quem procurar. E um convite para o seu relay dá ao relay só um nome de letras e números ao acaso para o celular que ele deixa entrar: o nome que você digita fica no seu celular, onde a sua lista de convites o mostra. Veja [Conversar por um relay](#relay).",
  "**Invited phones stay**: on a relay of this version, a phone you invited keeps its access even once yours goes, and so do the phones it invited; taking back an invite cuts off that one phone alone. See [Chat through a relay](#relay).":
    "**Os celulares convidados ficam**: num relay desta versão, um celular que você convidou fica com o acesso dele mesmo quando o seu termina, e o mesmo vale para os celulares que ele convidou; revogar um convite corta só aquele celular. Veja [Conversar por um relay](#relay).",
  "**Backups bring the phone back as it was**: a backup now holds the photos, files and voice messages too, in files of their own beside it, each sealed and bound to its backup; and the panic password, the settings that go with you, the Phone's quick replies and the calls it turns away, the SMS for later and automatic backups with their server, but not their folder. An SMS for later whose time passed before the restore waits for you to send it or delete it. What stays with each phone, as the fingerprint, the folders and what Android allows, never comes back: after a restore, Android's permissions open for the modules that are on. See [Backups](#backup).":
    "**Os backups trazem o celular de volta como estava**: um backup agora guarda também as fotos, os arquivos e as mensagens de voz, em arquivos próprios ao lado dele, cada um selado e preso ao seu backup; e a senha de pânico, as configurações que vão com você, as respostas rápidas do Telefone e as chamadas que ele recusa, os SMS para mais tarde e os backups automáticos com o servidor deles, mas não a pasta. Um SMS para mais tarde cuja hora passou antes da restauração espera você enviá-lo ou apagá-lo. O que fica com cada celular, como a digital, as pastas e o que o Android permite, nunca volta: depois de uma restauração, abrem as permissões do Android para os módulos ativados. Veja [Backups](#backup).",
  "**A newer backup asks for a newer Erevos**: a backup made by a newer Erevos than yours is refused, with nothing changed, and Erevos asks you to update to the latest version first. An Erevos from before 6.0.0 does not open backups from 6.0.0 on: update it, then restore. See [Backups](#backup).":
    "**Um backup mais novo pede um Erevos mais novo**: um backup feito por um Erevos mais novo que o seu é recusado, sem mudar nada, e o Erevos pede que você o atualize primeiro para a versão mais recente. Um Erevos anterior à 6.0.0 não abre backups da 6.0.0 em diante: atualize-o e depois restaure. Veja [Backups](#backup).",
  "**Shared into the Collection with no plain copy**: a photo or file another app shares with Erevos is encrypted as it comes in, before **Send to** opens, so on its way into the Collection it never lies unencrypted on the phone. It can be up to 4 GB there, and a large one shows how far it is encrypted, with **Cancel**; a chat still takes 100 MB at most. See [Collection](#collection).": "**Compartilhar na Coleção sem cópia sem criptografia**: uma foto ou um arquivo que outro app compartilha com o Erevos é criptografado assim que chega, antes de **Enviar para** abrir, por isso a caminho da Coleção nunca fica sem criptografia no telefone. Lá pode ter até 4 GB; uma conversa ainda aceita no máximo 100 MB. Num grande, aparece quanto já foi criptografado, com **Cancelar**. Veja [Coleção](#collection).",
  "**See a file come from the WebDAV server**: a file of the Collection that is not on this device, as after a backup restored on a new phone, shows how much of it has come from the server, and **Cancel** stops it; what came stays, and the next time only the rest comes. Music, videos, PDFs and **Open with another app** fetch it first too, instead of failing. See [Collection](#collection).": "**Veja um arquivo chegar do servidor WebDAV**: um arquivo da Coleção que não está neste dispositivo, como depois de um backup restaurado num telefone novo, mostra quanto já chegou do servidor, e **Cancelar** o interrompe; o que chegou fica, e da próxima vez só chega o resto. Música, vídeos, PDF e **Abrir com outro app** também o trazem primeiro, em vez de falhar. Veja [Coleção](#collection).",
  "**Backups skip what is on the WebDAV server after a restart too**: that a Collection's copies on its server are complete is kept with it, so a backup made after Erevos starts again still leaves its pieces out, as long as no file was added or deleted since. **The connection works.** now shows in the colour of success, not of a warning. See [Collection](#collection).": "**Os backups deixam de fora o que está no servidor WebDAV também depois de reiniciar**: o fato de as cópias de uma Coleção no seu servidor estarem completas é guardado com ela, por isso um backup feito depois de o Erevos voltar a iniciar continua a deixar de fora as suas partes, desde que nenhum arquivo tenha sido adicionado ou apagado desde então. **A ligação funciona.** aparece agora na cor do sucesso, não de um aviso. Veja [Coleção](#collection).",
  "**Notes from another app**: an app on the phone, as Fasouli for a payment that is coming, can ask to keep a note with its reminder in Chat with myself. Erevos asks you first, in the space you open. See [Getting started](#start).":
    "**Notas de outro app**: um app do telefone, como o Fasouli para um pagamento que está chegando, pode pedir para guardar uma nota com o seu lembrete na Conversa comigo. O Erevos pergunta antes, no espaço que você abre. Veja [Primeiros passos](#start).",
  "**Payment requests**: another app, as Fasouli, can ask Erevos to send one to a contact: an amount and what it is for, as a card. They tap **Paid** once they paid, and **Mark in Fasouli** then marks it collected there. Erevos moves no money. See [Chat through a relay](#relay).":
    "**Pedidos de pagamento**: outro app, como o Fasouli, pode pedir ao Erevos que envie um a um contato: um valor e para quê, como cartão. O contato toca **Pago** quando pagar, e **Marcar no Fasouli** marca como recebido lá. O Erevos não move dinheiro. Veja [Conversar por um relay](#relay).",
  "**Panic tells Fasouli too**: on Android, under Settings → Privacy and security → Panic button → **Tell other apps**, choose the apps Erevos tells as it wipes, as a panic app does: Fasouli then locks itself. Each asks you first. See [Panic button](#panic).":
    "**O pânico avisa também o Fasouli**: no Android, em Configurações → Privacidade e segurança → Botão de pânico → **Avisar outros apps**, você escolhe os apps que o Erevos avisa ao apagar, como um app de pânico: o Fasouli então se bloqueia. Cada um pergunta antes. Veja [Botão de pânico](#panic).",
  "**The Collection in the browser and on Sailfish OS**: the web app, on an iPhone's home screen too, and Erevos on Sailfish OS have the Collection now. A file is encrypted a piece at a time as it is read, and if the browser runs out of room nothing of it is kept. Photos, text, music and videos up to 256 MB open in memory only; a PDF is saved to be read elsewhere. See [Collection](#collection).":
    "**A Coleção no navegador e no Sailfish OS**: o app web, também na tela inicial de um iPhone, e o Erevos no Sailfish OS têm agora a Coleção. Um arquivo é criptografado um pedaço por vez enquanto é lido, e se o navegador ficar sem espaço nada dele é guardado. Fotos, textos, músicas e vídeos de até 256 MB abrem só na memória; um PDF é salvo para ser lido em outro lugar. Veja [Coleção](#collection).",
  "**Large files saved from the Collection on Sailfish OS**: **Save to phone** writes a file of any size to Downloads a piece at a time, as the desktop app now does too, and when the disk has no room left Erevos says so and leaves nothing half-written. See [Collection](#collection).":
    "**Arquivos grandes salvos da Coleção no Sailfish OS**: **Salvar no telefone** grava em Downloads um arquivo de qualquer tamanho um pedaço por vez, como agora também faz o app para computador, e quando o disco fica sem espaço o Erevos avisa e não deixa nada gravado pela metade. Veja [Coleção](#collection).",
  "**Sign in with Nextcloud**: a Collection's server and the backups' server can now be your Nextcloud, as LPHL's, the one Fasouli syncs with, without typing a password: tap **Sign in with Nextcloud**, sign in in the browser and grant access. Erevos gets an app password of its own and its own folder there, Erevos/Collection or Erevos/Backups. See [Collection](#collection).":
    "**Entrar com Nextcloud**: o servidor de uma Coleção e o dos backups agora podem ser o seu Nextcloud, como o do LPHL, aquele com que o Fasouli sincroniza, sem digitar uma senha: toque em **Entrar com Nextcloud**, entre no navegador e conceda acesso. O Erevos recebe uma senha de app própria e uma pasta dele lá, Erevos/Collection ou Erevos/Backups. Veja [Coleção](#collection).",
  "**Web app and Sailfish OS fixes from the review**: in the web app, each space that turns notifications on gets a push address of its own, from a service worker of its own, so a relay is never given another space's address and it never ties two spaces together; the browser's settings then list one service worker for each such space. A check for a new release that was slow to answer no longer brings back the release just replaced. On Sailfish OS, another app on the phone can no longer make Erevos hold on to memory, nor give orders to the helper that waits at the relay while Erevos is out of sight. See [On an iPhone](#iphone).":
    "**Correções da revisão no app web e no Sailfish OS**: no app web, cada espaço que ativa as notificações recebe o seu próprio endereço de push, de um service worker próprio, então um relay nunca recebe o endereço de outro espaço e ele nunca liga dois espaços; as configurações do navegador mostram então um service worker para cada um desses espaços. Uma busca por versão nova que demorou a responder não traz mais de volta a versão que acabou de ser substituída. No Sailfish OS, outro app do telefone não consegue mais fazer o Erevos segurar memória, nem dar ordens ao ajudante que espera no relay enquanto o Erevos não está na tela. Veja [Num iPhone](#iphone).",
  "**Photos of the Collection one after the other**: in a photo, the arrows (on a phone too, while the bars show) or a swipe go to the next or the one before, and **Slideshow** shows them by themselves, one every 4 seconds, till a tap. On a computer, in a browser and on Sailfish OS a photo opens again instead of staying at **Opening the photo…**. See [Collection](#collection).": "**As fotos da Coleção uma após a outra**: numa foto, as setas (também no telefone, enquanto as barras aparecem) ou deslizar levam à seguinte ou à anterior, e **Apresentação** as mostra sozinha, uma a cada 4 segundos, até um toque. No computador, num navegador e no Sailfish OS uma foto volta a abrir em vez de ficar em **Abrindo a foto…**. Veja [Coleção](#collection).",
  "**Reminders that come again**: a note Fasouli keeps for a scheduled payment now reminds you each time it is due, every month or as the payment repeats, and shows how often. Once you see it, it moves to its next time. See [Getting started](#start).":
    "**Lembretes que voltam**: uma nota que o Fasouli guarda para um pagamento agendado agora avisa você a cada vencimento, todo mês ou como o pagamento se repete, e mostra com que frequência. Assim que você a vê, ela passa para a próxima vez. Veja [Getting started](#start).",
  "**Who is online on Matrix and XMPP**: under a contact's name it says, as their server does, **Online**, **Away** or **Do not disturb**, with the words they set, or when they were last online, and their picture in the chat list has a green dot. On Matrix, Erevos no longer says you are online unless you turn on **Say when I am online** on the Matrix screen. See [Matrix](#matrix).":
    "**Quem está online no Matrix e no XMPP**: embaixo do nome de um contato aparece, como o servidor dele diz, **Online**, **Ausente** ou **Não incomodar**, com as palavras que ele pôs, ou quando esteve online pela última vez, e a foto dele na lista de conversas tem um ponto verde. No Matrix, o Erevos não diz mais que você está online, a não ser que você ative **Avisar quando estou online** na tela do Matrix. Veja [Matrix](#matrix).",
  "**Link a computer with one tap**: on the computer, **Linked devices** now shows a small code at once. Scan it with the phone and tap **Link**: the phone gives the computer what it needs through Nostr, end-to-end encrypted, and nothing has to be typed or compared. If Nostr cannot be reached, **Link another way** keeps the old way. See [Linked devices](#devices).":
    "**Conecte um computador com um toque**: no computador, **Dispositivos conectados** agora mostra na hora um pequeno código. Escaneie-o com o celular e toque em **Conectar**: o celular dá ao computador o que ele precisa pelo Nostr, criptografado de ponta a ponta, e não é preciso digitar nem comparar nada. Se o Nostr não puder ser alcançado, **Conectar de outro jeito** mantém o modo de antes. Veja [Dispositivos conectados](#devices).",
  '**Choose the name others see**: under Settings → Privacy and security → **My name**, give this space a name that your contacts and your private groups see instead of a code, always encrypted. Hidden chats have a name of their own, in their settings, empty at first. See [Chat through a relay](#relay).':
    '**Escolhe o nome que os outros veem**: em Configurações → Privacidade e segurança → **O meu nome**, dá a este espaço um nome que os teus contactos e os teus grupos privados veem em vez de um código, sempre cifrado. As conversas ocultas têm um nome próprio, nas suas configurações, vazio ao início. Veja [Conversar por um relay](#relay).',
  "**Folders in Chat with myself**: notes, photos, files and voice messages can now go in folders. The folder button at the top makes one; its tab above the notes then shows only what is in it, and what you write while it is chosen goes into it. Holding a note offers **Move to a folder**; holding a folder's tab renames or deletes it, its notes staying. The folders go to your linked devices with the notes. See [Getting started](#start).":
    "**Pastas em Conversa comigo**: notas, fotos, arquivos e mensagens de voz agora podem ir para pastas. O botão de pasta no topo cria uma; a aba dela acima das notas mostra então só o que há nela, e o que você escreve enquanto ela está escolhida vai para dentro dela. Segurar uma nota oferece **Mover para uma pasta**; segurar a aba de uma pasta a renomeia ou apaga, e as notas dela ficam. As pastas vão para os seus dispositivos conectados com as notas. Veja [Primeiros passos](#start).",
  "**The battery mode And sleep spares more**: each time it wakes the phone to look, about once a minute, the phone now sleeps again within a second or two when nothing came, not after 25 seconds.":
    "**O modo de bateria «E o sono» poupa mais**: cada vez que acorda o celular para olhar, cerca de uma vez por minuto, o celular agora volta a dormir em um ou dois segundos quando nada chegou, e não depois de 25 segundos.",
  "**Messages come at once while Erevos shows**: Erevos now waits at your relay with the connection open also while it is on the screen, so a message or a call comes the moment it is sent, not at the next look every 3 seconds, and the phone's radio rests in between.":
    "**As mensagens chegam de imediato enquanto o Erevos está à vista**: o Erevos agora espera no teu relay com a ligação aberta também enquanto está no ecrã, de modo que uma mensagem ou uma chamada chega no momento em que é enviada, e não no próximo olhar a cada 3 segundos, e o rádio do celular descansa entretanto.",
  "**A new battery mode, And light sleep**: under Settings → Notifications → In the background. The phone may sleep, and what comes to your relay wakes it, so messages and calls still come at once where the network and Android allow it. It is new: if messages come late with it, choose another.":
    "**Um novo modo de bateria, «E o sono leve»**: em Configurações → Notificações → Em segundo plano. O celular pode dormir, e o que chega ao teu relay acorda-o, de modo que mensagens e chamadas continuam a chegar de imediato onde a rede e o Android o permitem. É novo: se com ele as mensagens chegarem tarde, escolhe outro.",
  "**Chats are saved faster**: a message that comes, is read or is deleted is saved by looking only at its own chat, which shows most with many chats or after a large import. The chat screen is no longer drawn again every 5 seconds.":
    "**As conversas são guardadas mais depressa**: uma mensagem que chega, é lida ou é apagada é guardada olhando apenas para a sua própria conversa, o que se nota mais com muitas conversas ou depois de uma grande importação. O ecrã da conversa já não é redesenhado a cada 5 segundos.",
  "**Large imports write less**: the note of the files an import is still writing is kept in small parts, not written whole for every file.":
    "**As grandes importações escrevem menos**: a nota dos ficheiros que uma importação ainda está a escrever é guardada em pequenas partes, e não escrita inteira para cada ficheiro.",
  "**A text no longer waits for slow Nostr relays**: with Nostr on, a text waited for a Nostr relay to say it took it, up to 20 seconds when none answered, before it went through the relay. Now, when none says so within 4 seconds, it goes through the relay as well at once.":
    "**Uma mensagem já não espera por relays Nostr lentos**: com o Nostr ligado, uma mensagem esperava que um relay Nostr dissesse que a recebeu, até 20 segundos quando nenhum respondia, antes de ir pelo relay. Agora, se nenhum o disser em 4 segundos, vai logo também pelo relay.",
  "**Voice messages in Opus**: on Android 10 and later, in the web app and on a computer, voice messages are recorded as Ogg/Opus, as Telegram and Element send them: as clear as before at half the size, about 240 KB a minute. Every Erevos plays them, Safari on an older iPhone too. See [Chat through a relay](#relay).":
    "**Mensagens de voz em Opus**: no Android 10 e posteriores, no app web e num computador, as mensagens de voz são gravadas em Ogg/Opus, como Telegram e Element as enviam: tão claras quanto antes com metade do tamanho, cerca de 240 KB por minuto. Todo Erevos as reproduz, e o Safari num iPhone mais antigo também. Veja [Conversar por um relay](#relay).",
  "**Mark all as read**: the ⋮ menu of the chats has it for the part of the list you are on, all messages, SMS, Erevos, Matrix, XMPP or Nostr, and the Matrix, XMPP and Nostr screens have it for their chats. It asks first, then reads each chat as opening it would: those who wrote are told as then. See [Getting started](#start).":
    "**Marcar tudo como lido**: o menu ⋮ das conversas o tem para a parte da lista em que você está, todas as mensagens, SMS, Erevos, Matrix, XMPP ou Nostr, e as telas do Matrix, do XMPP e do Nostr o têm para as suas conversas. Ele pergunta primeiro, depois lê cada conversa como abri-la faria: quem escreveu é avisado como naquele momento. Veja [Primeiros passos](#start).",
  "**Answer with video, or voice only**: an incoming call, Erevos, group, XMPP or Matrix, now offers both. You can add video to an Erevos voice call while it goes on, and Flip on a computer moves to your next camera. See [Chat through a relay](#relay).":
    "**Atender com vídeo ou só com voz**: uma chamada recebida, do Erevos, de grupo, do XMPP ou do Matrix, agora oferece as duas coisas. Você pode adicionar vídeo a uma chamada de voz do Erevos enquanto ela dura, e Virar num computador passa para a sua câmera seguinte. Veja [Conversar por um relay](#relay).",
  "**Voice messages, places, contact cards and pins in SMS**: in an SMS conversation, hold the microphone to send a voice message by MMS. **+** also sends where you are, as an SMS with a map link any phone opens, and a contact from your phone as a contact card. Voice messages, contact cards and map links you receive show as such, to play, save or open. Hold a message down to **Pin for me**, kept only on this phone, or **Select** several to copy, forward or delete them together. See [SMS](#sms).":
    "**Mensagens de voz, lugares, cartões de contato e fixadas nos SMS**: numa conversa de SMS, segure o microfone para enviar uma mensagem de voz por MMS. O **+** também envia onde você está, como um SMS com um link de mapa que qualquer celular abre, e um contato do seu celular como cartão de contato. As mensagens de voz, cartões de contato e links de mapa que você recebe aparecem como tais, para reproduzir, salvar ou abrir. Toque e segure uma mensagem para **Fixar só para mim**, guardada só neste celular, ou **Selecionar** várias para copiá-las, encaminhá-las ou apagá-las juntas. Veja [SMS](#sms).",
  "**More in XMPP chats**: voice messages from other XMPP apps now play in the chat and show how long they are; **Sticker** sends your own photo stickers as photos, encrypted as the chat is; groups show who is **owner** or **admin**, and the owner can set the group's **Description**; **Forward** sends one or several messages to another XMPP chat; tapping a quoted reply goes to the message; **Pin for me** keeps a message at the top on this phone only; and **Select** chooses several messages to copy, forward or delete. See [XMPP](#xmpp).":
    "**Mais nas conversas XMPP**: as mensagens de voz de outros apps XMPP agora tocam na conversa e mostram a duração; **Figurinha** envia as suas próprias figurinhas feitas de fotos como fotos, criptografadas como a conversa; os grupos mostram quem é **dono** ou **admin**, e o dono pode definir a **Descrição** do grupo; **Encaminhar** envia uma ou várias mensagens para outra conversa XMPP; tocar numa resposta citada vai à mensagem; **Fixar só para mim** mantém uma mensagem no topo só neste celular; e **Selecionar** escolhe várias mensagens para copiar, encaminhar ou apagar. Veja [XMPP](#xmpp).",
  "**More in Nostr chats**: tap a reaction to add it or take yours back, pin messages for yourself, select several to copy, forward or delete, send your own photo stickers, and see, vote on and make polls in the Public feed. See [Chats with other Nostr apps](#nostr-chats).":
    "**Mais nas conversas do Nostr**: toque numa reação para acrescentá-la ou retirar a sua, fixe mensagens para você, escolha várias para copiar, encaminhar ou apagar, envie as suas próprias figurinhas feitas de fotos, e veja, vote e crie enquetes no feed público. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Matrix groups and stickers**: in a Matrix group, **Members** shows who is in it and who is an admin or moderator, and lets admins rename it, set its subject, make admins, and take people out or bar them. Stickers sent from Element and other Matrix apps now show, and your own stickers made from photos can be sent. **New chat** can find people by name, and **Select** in a message's menu chooses several messages to copy, forward or delete. See [Matrix](#matrix).":
    "**Grupos e figurinhas no Matrix**: num grupo do Matrix, **Membros** mostra quem está nele e quem é admin ou moderador, e deixa os admins renomeá-lo, definir o assunto, tornar outros admins, e remover ou banir pessoas. As figurinhas enviadas do Element e de outros apps do Matrix agora aparecem, e as suas próprias figurinhas feitas de fotos podem ser enviadas. **Nova conversa** pode achar pessoas pelo nome, e **Selecionar** no menu de uma mensagem escolhe várias mensagens para copiar, encaminhar ou apagar. Veja [Matrix](#matrix).",
  "**More in your chats and groups**: choose several messages to copy, forward or delete at once; end your polls; reply in threads in groups; give a group a description; and send a contact from your phone as a card. See [Chat through a relay](#relay) and [Group chats](#groups).":
    "**Mais nas suas conversas e grupos**: escolha várias mensagens para copiar, encaminhar ou apagar de uma vez; encerre as suas enquetes; responda em tópicos nos grupos; dê uma descrição a um grupo; e envie um contato do seu celular como cartão. Veja [Conversar por um relay](#relay) e [Conversas em grupo](#groups).",
  "**Ticks**: a text the other phone had, and read, before it showed as sent here (through a slow Nostr relay) now shows as read, not with one tick. Ticks from a contact on another relay no longer stop, and a text that reaches a phone while Erevos is in the background there gets its second tick at that phone's next check.":
    "**Vistos**: um texto que o outro celular já tinha e já tinha lido antes de aparecer aqui como enviado (por um relay do Nostr lento) agora aparece como lido, não com um visto só. Os vistos de um contato em outro relay não param mais, e um texto que chega a um celular enquanto o Erevos está em segundo plano nele recebe o segundo visto na próxima verificação desse celular.",
  "**Stickers on other networks**: a built-in sticker sent on Matrix, XMPP, Nostr or by MMS arrives as its picture, made on your device, its words in your language. See [Chat through a relay](#relay).":
    "**Figurinhas em outras redes**: uma figurinha embutida enviada pelo Matrix, XMPP, Nostr ou por MMS chega como a imagem dela, feita no seu aparelho, com as palavras no seu idioma. Veja [Conversar por um relay](#relay).",
  "**One button for all your services**: under the search on the home screen, one button says which service shows, with the messages not read and any service not connected now. Tap it for a window with every service as a card, each with its own number and a dot for its connection; **Add** turns more on, and holding a card moves it or hides it. With no search, the chats with messages not read come first, under **Unread**, then the rest under **Recent**. See [Getting started](#start).":
    "**Um botão para todos os seus serviços**: abaixo da busca na tela inicial, um botão diz qual serviço aparece, com as mensagens não lidas e qualquer serviço que não está conectado agora. Toque nele para uma janela com cada serviço como cartão, cada um com seu número e um ponto para sua conexão; **Adicionar** liga mais, e tocar e segurar um cartão o move ou oculta. Sem busca, vêm primeiro as conversas com mensagens não lidas, em **Não lidas**, e depois as outras em **Recentes**. Veja [Primeiros passos](#start).",
  "**Share an imported chat with the other person**: a Telegram, WhatsApp or Viber chat that goes on with an Erevos contact can now go to them too, from the chat's **Details** or **Settings** → **Data and devices** → **Imported chats**: every message, photo, video, voice message and file, end-to-end encrypted, to them alone, whatever its size. Their Erevos keeps the messages at once and shows them ahead of the new messages, the sides swapped; the files follow in rounds through your relay while both phones run Erevos, each up to 4 GB, as large as an import now keeps. See [Imported chats](#import).":
    "**Partilhe uma conversa importada com a outra pessoa**: uma conversa do Telegram, WhatsApp ou Viber que continua com um contacto Erevos pode agora ir também para ele, a partir dos **Detalhes** da conversa ou de **Configurações** → **Dados e dispositivos** → **Conversas importadas**: cada mensagem, foto, vídeo, mensagem de voz e ficheiro, cifrado de ponta a ponta, só para ele, seja qual for o tamanho. O Erevos dele guarda logo as mensagens e mostra-as antes das mensagens novas, com os lados trocados; os ficheiros seguem por rondas através do teu relay enquanto o Erevos estiver a correr nos dois telemóveis, cada um até 4 GB, tão grande como uma importação agora guarda. Ver [Conversas importadas](#import).",
  "**Tor for your XMPP account, and per chat**: on Android, the XMPP screen, and the one before signing in, chooses **Off** (the default), **As the space** or **Always through Tor** for the account: its connection, the look for its server and its files, never straight when it must not. **Through Tor** under any XMPP chat or group, off by default, sends the whole account only through Tor while on, as one connection carries all its chats. Calls do not go through Tor. Before you send while the account does not go through Tor, before a call and before a file from another server, Erevos says once that your internet address can be seen, and how not to. See [XMPP](#xmpp).":
    "**Tor para sua conta XMPP, e por conversa**: no Android, a tela do XMPP, e a de antes de entrar, escolhe para a conta **Desativado** (o padrão), **Como o espaço** ou **Sempre pelo Tor**: a conexão, a busca do servidor e os arquivos, nunca direto quando não deve. **Pelo Tor** sob qualquer conversa ou grupo XMPP, desativado por padrão, faz a conta inteira passar só pelo Tor enquanto estiver ativado, já que uma conexão leva todas as conversas. As chamadas não passam pelo Tor. Antes de você enviar enquanto a conta não passa pelo Tor, antes de uma chamada e antes de um arquivo de outro servidor, o Erevos diz uma vez que seu endereço de internet pode ser visto, e como evitar. Veja [XMPP](#xmpp).",
  "**Tor for Messenger and Signal, and per chat**: in Erevos+, the Messenger and Signal screens, and the ones before signing in, choose **Off** (the default), **As the space** or **Always through Tor** for the account. With it, everything of the account goes through Tor, its pictures and files too, and Messenger's sign-in page and Signal's registering, captcha and linking as well: never straight when it must not. **Through Tor** under any of their chats, off by default, sends the whole account only through Tor while on, as each has one connection. Calls do not go through Tor.":
    "**Tor para Messenger e Signal, e por conversa**: no Erevos+, as telas do Messenger e do Signal, também antes de entrar, escolhem para a conta **Desativado** (o padrão), **Como o espaço** ou **Sempre pelo Tor**. Com isso, tudo da conta passa pelo Tor, suas fotos e arquivos também, e ainda a página de entrada do Messenger e o registro, o captcha e a vinculação do Signal: nunca direto quando não deve. **Pelo Tor** em qualquer uma das conversas, desativado por padrão, envia a conta inteira só pelo Tor enquanto estiver ativo, pois cada uma tem uma conexão. As chamadas não passam pelo Tor.",
  "**Telegram: Tor as every account, and per chat**: on Android, **Tor for this Telegram account**, in Telegram's settings and before signing in, has **Off** (the default), **As the space** and **Always through Tor**, as every account of another network. With Always, or while the space sends Everything through Tor, Telegram is reached only through Tor, signing in too, and never straight, not even when Tor cannot connect. **Through Tor** in a Telegram chat's info sends that chat only through Tor, and with it the whole account, which has one connection. Calls do not go through Tor. See [Telegram (ErevosGram)](#telegram).":
    "**Telegram: Tor como em toda conta, e por conversa**: no Android, **Tor para esta conta do Telegram**, nas configurações do Telegram e antes de entrar, tem **Desativado** (o inicial), **Como o espaço** e **Sempre pelo Tor**, como toda conta de outra rede. Com Sempre, ou enquanto o espaço manda Tudo pelo Tor, o Telegram é alcançado só pelo Tor, também ao entrar, e nunca direto, nem quando o Tor não consegue conectar. **Pelo Tor** nas informações de uma conversa do Telegram leva essa conversa só pelo Tor, e com ela a conta inteira, que tem uma só conexão. As chamadas não passam pelo Tor. Veja [Telegram (ErevosGram)](#telegram).",
  "**Nostr: Tor as every account, and per chat**: on Android, the **Nostr chats** screen, before a key is made or brought too, has **Off** (the default, also for keys from before), **As the space** and **Always through Tor** for the account: its relays, look-ups and file servers, never straight when it must not (Always, or the space's Everything). **Through Tor** at the foot of a Nostr chat, off by default, sends that chat alone only through Tor, on circuits of its own, whatever the account says; what comes to you follows the account. See [Chats with other Nostr apps](#nostr-chats).":
    "**Nostr: Tor como em toda conta, e por conversa**: no Android, a tela **Conversas Nostr**, também antes de criar ou trazer uma chave, tem **Desativado** (o padrão, também para as chaves de antes), **Como o espaço** e **Sempre pelo Tor** para a conta: seus relays, buscas e servidores de arquivos, nunca direto quando não deve (Sempre, ou o Tudo do espaço). **Pelo Tor** no pé de uma conversa Nostr, desligado por padrão, envia só essa conversa apenas pelo Tor, em circuitos próprios, seja o que for que a conta diga; o que chega para você segue a conta. Veja [Conversas com outros apps Nostr](#nostr-chats).",
  "**Telegram warns before your internet address can be seen**: once in each Telegram chat, before the first message, file, sticker, voice message, poll or forward while the account does not go through Tor, with **Through Tor** for that chat to fix it, **Guide** or **Go on**; before every Telegram call, made or answered, as calls never go through Tor; and before joining a group or channel by its link. See [Who sees your internet address](#ip).":
    "**O Telegram avisa antes que seu endereço de internet possa ser visto**: uma vez em cada conversa do Telegram, antes da primeira mensagem, arquivo, figurinha, mensagem de voz, enquete ou encaminhamento enquanto a conta não vai pelo Tor, com **Pelo Tor** para essa conversa como solução, **Guia** ou **Prosseguir**; antes de cada chamada do Telegram, feita ou atendida, pois as chamadas nunca passam pelo Tor; e antes de entrar num grupo ou canal pelo link. Veja [Quem vê o seu endereço de internet](#ip).",
  "**Erevos or Erevos+, and betas, in Updates**: on Android, **Updates** now chooses the next update: **Erevos** or **Erevos+**, moving from one to the other with everything kept, and **Beta versions**, to join the betas, which come out first for trying, or leave them. See [Erevos or Erevos+, and betas](#updates).": "**Erevos ou Erevos+, e betas, em Atualizações**: no Android, **Atualizações** agora escolhe a próxima atualização: **Erevos** ou **Erevos+**, passando de um para o outro sem perder nada, e **Versões beta**, para participar das betas, que saem antes para teste, ou sair delas. Veja [Erevos ou Erevos+, e betas](#updates).",
  "**Matrix, XMPP and Nostr chats are in Erevos+**: Erevos now has its own chats, the Phone, SMS and the Collection, and Erevos+ has Matrix, XMPP and the chats with other Nostr apps besides. An account you had on them stays on the phone, encrypted, and Erevos says so once; choose **Erevos+** in **Updates** to have it again. Erevos's own messages still go through Nostr relays when no relay of yours takes them. See [Erevos or Erevos+, and betas](#updates).": "**As conversas de Matrix, XMPP e Nostr estão no Erevos+**: o Erevos agora tem as conversas dele, o Telefone, os SMS e a Coleção, e o Erevos+ tem também Matrix, XMPP e as conversas com outros apps do Nostr. Uma conta que você tinha neles fica no celular, criptografada, e o Erevos avisa uma vez; escolha **Erevos+** em **Atualizações** para tê-la de novo. As mensagens do próprio Erevos ainda passam por relays do Nostr quando nenhum relay seu as aceita. Veja [Erevos ou Erevos+, e betas](#updates).",
  "**Radio and TV through Tor**: the Collection's settings on Android have **Play through Tor**, off unless you turn it on. On, stations and channels play only through Tor, so they do not see your IP address; TV may stall for a moment. Off, Erevos says before the first one plays that its server sees your IP address, with a button that turns it on. Before, they always played straight. See [Collection](#collection).": "**Rádio e TV pelo Tor**: as configurações da Coleção no Android têm o **Tocar pelo Tor**, desligado a menos que você o ligue. Ligado, as estações e os canais tocam só pelo Tor, então não veem o seu endereço IP; a TV pode travar por um momento. Desligado, o Erevos avisa antes de tocar o primeiro que o servidor dele vê o seu endereço IP, com um botão que o liga. Antes, tocavam sempre direto. Veja [Coleção](#collection).",
  "**A chat no longer freezes before a message sent for later shows**: a message your contact sends with **Send later** can come before its time, and shows only then. Until then its chat was marked read again and again without end, so it could stop answering: **⋮** opened nothing and **Back** did not leave it until Erevos was closed. Now such a message is read once it shows. See [Chat through a relay](#relay).": "**Uma conversa já não congela antes de aparecer uma mensagem enviada para mais tarde**: uma mensagem que o teu contacto envia com **Enviar mais tarde** pode chegar antes da hora, e só aparece então. Até lá, a conversa era marcada como lida uma e outra vez, sem fim, e podia deixar de responder: **⋮** não abria nada e **Voltar** não saía dela até fechar o Erevos. Agora uma mensagem assim é lida assim que aparece. Veja [Conversar por um relay](#relay).",
  "**Choose the part Erevos opens on**: under **All services**, hold any card, **All messages** too, and choose **Opens first**. Erevos's icon in the launcher, and Erevos started with nothing else to open, then open on it; with none chosen, or the chosen one hidden, on **All messages**. Before, the icon always opened the Erevos chats. The widget's buttons still open their own. See [Getting started](#start).": "**Escolha onde o Erevos abre**: em **Todos os serviços**, mantenha pressionado qualquer cartão, **Todos** também, e escolha **Abre primeiro**. O ícone do Erevos no launcher, e o Erevos iniciado sem mais nada para abrir, abrem então ali; sem nenhum escolhido, ou com o escolhido oculto, em **Todos**. Antes, o ícone abria sempre as conversas do Erevos. Os botões do widget continuam abrindo os seus. Veja [Primeiros passos](#start).",
  "**Asked before strangers reach this phone**: an Erevos invite that comes by SMS is answered by itself only from a number in your contacts or one you have written to; from any other, Erevos asks first, as the sender of an SMS can be made up. A contact's invite to a place on their relay now says first that their relay sees your IP address, and is taken only if you go on. See [Who sees your internet address](#ip).": "**Pergunta-se antes que estranhos cheguem a este celular**: um convite do Erevos que chega por SMS só é respondido sozinho se vier de um número dos seus contatos ou de um para o qual você escreveu; de qualquer outro, o Erevos pergunta antes, porque o remetente de um SMS pode ser falsificado. O convite de um contato para um lugar no relay dele agora diz primeiro que o relay dele vê o seu endereço IP, e só é aceito se você continuar. Veja [Quem vê o seu endereço de internet](#ip).",
  "**Notices in your language**: Android's own notices and screens, new versions, reminders, birthdays, calls, SMS codes and the contact picker, now speak German, Spanish, French, Italian, Portuguese and Serbo-Croatian too, not only Greek and English. Older Greek subtitles, not saved as UTF-8, now show as Greek on the computer. See [Collection](#collection).": "**Avisos no seu idioma**: os avisos e as telas do próprio Android, as versões novas, os lembretes, os aniversários, as chamadas, os códigos de SMS e o seletor de contatos agora falam também alemão, espanhol, francês, italiano, português e servo-croata, não só grego e inglês. As legendas gregas antigas, não salvas em UTF-8, agora aparecem como grego no computador. Veja [Coleção](#collection).",
  "**Video calls on the computer, and the calculator after a wipe**: a video call started or answered on the computer now opens its camera. With the calculator in place of Erevos's icon, once Erevos is wiped by the panic password or **Clear storage**, the calculator opens Erevos as new and gives Erevos's icon back, where before no code opened it any more. See [Appearance](#appearance).": "**Chamadas de vídeo no computador, e a calculadora depois de um apagamento**: uma chamada de vídeo iniciada ou atendida no computador agora abre a câmera dela. Com a calculadora no lugar do ícone do Erevos, depois que o Erevos é apagado pela senha de pânico ou pelo **Limpar armazenamento**, a calculadora abre o Erevos como novo e devolve o ícone do Erevos, onde antes nenhum código o abria mais. Veja [Aparência](#appearance).",
  "**Last seen starts off**: in a new space, **Last seen** is now off until you turn it on, so no contact sees when you last had Erevos open, and you see no one's either. A space you already have keeps it as it was. See [Chat through a relay](#relay).": "**Visto por último começa desativado**: em um espaço novo, **Visto por último** agora fica desativado até você ativar, então nenhum contato vê quando você abriu o Erevos pela última vez, e você também não vê o de ninguém. Um espaço que você já tem o mantém como estava. Veja [Conversar por um relay](#relay).",
  "**A chat with a big file no longer closes Erevos**: on Android, opening a chat that held a large file, or one shared in many pieces, could close Erevos at once. Now it opens. See [Chat through a relay](#relay).": "**Uma conversa com um ficheiro grande já não fecha o Erevos**: no Android, abrir uma conversa com um ficheiro grande, ou partilhado em muitas partes, podia fechar o Erevos de imediato. Agora abre. Vê [Conversar por um relay](#relay).",
  "**A hidden service stays quiet**: a service you hide in the **Services** window, Messenger, Matrix, SMS or any other, no longer sends notifications or counts on Erevos's icon, as a muted chat. It stays connected and tells again once you show it. Telegram, whose folders can stand on home of their own, keeps telling. See [Getting started](#start).": "**Um serviço oculto fica em silêncio**: um serviço que ocultas na janela **Serviços**, Messenger, Matrix, SMS ou outro, já não envia notificações nem conta no número do ícone do Erevos, como uma conversa silenciada. Continua ligado e volta a avisar assim que o mostrares. O Telegram, cujas pastas podem estar no início como serviços próprios, continua a avisar. Vê [Getting started](#start).",
  "**Screenshots in hidden chats too, if you want**: hidden chats now follow **Screenshots** in **Privacy and security**: on, as it starts, they stay out of screenshots and the recent apps; turned off, screenshots work in them as in the other chats. Before, hidden chats always kept them out. See [Hidden chats](#hidden).": "**Capturas também nas conversas ocultas, se quiseres**: as conversas ocultas seguem agora **Capturas de tela** em **Privacidade e segurança**: ativo, como começa, ficam fora das capturas e das apps recentes; desativado, as capturas funcionam nelas como nas outras conversas. Antes, as conversas ocultas bloqueavam-nas sempre. Vê [Conversas ocultas](#hidden).",
  "**Messenger signs in on facebook.com, and opens Facebook**: in Erevos+, Messenger now signs in on Facebook's own page. **Open Facebook** on the Messenger screen shows Facebook itself with the same sign-in: its Messenger links come back to Erevos's chats, and other links open in your browser without Facebook's tracking marks and never through Tor, so the site sees your internet address. An account signed in on messenger.com before signs out and in again once to open Facebook.":
    "**O Messenger inicia sessão em facebook.com e abre o Facebook**: no Erevos+, o Messenger agora inicia sessão na própria página do Facebook. **Abrir Facebook** no ecrã do Messenger mostra o próprio Facebook com a mesma sessão: as suas ligações do Messenger voltam às conversas do Erevos, e as outras ligações abrem no teu navegador sem as marcas de rastreio do Facebook e nunca através do Tor, por isso o site vê o teu endereço de internet. Uma conta com sessão iniciada antes em messenger.com termina a sessão e volta a iniciá-la uma vez para abrir o Facebook.",
  "**Messenger, Signal and Session chats send more, and stay read**: in Erevos+, **+** in their chats sends a photo from your photos or the camera, a file or a sticker, and the microphone records a voice message. Your own messages show their words, where before some came empty; tapping a person with no Messenger chat yet opens a new one; and chats you mark read no longer come back unread.":
    "**As conversas do Messenger, Signal e Session enviam mais e ficam lidas**: no Erevos+, **+** nas suas conversas envia uma foto das tuas fotos ou da câmara, um ficheiro ou um autocolante, e o microfone grava uma mensagem de voz. As tuas próprias mensagens mostram as suas palavras, onde antes algumas chegavam vazias; tocar numa pessoa sem conversa do Messenger abre uma nova; e as conversas que marcas como lidas já não voltam a ficar por ler.",
  "**Every copy carries its licences**: the Android app, the computer and Sailfish apps and the web app now carry the file NOTICES.txt, with Erevos's licence, AUTHORS.md and every package Erevos is built from, each with its licence text. See [Licence](#licence).": "**Cada cópia traz as suas licenças**: a app Android, as apps de computador e Sailfish e a app web trazem agora o ficheiro NOTICES.txt, com a licença do Erevos, o AUTHORS.md e cada pacote de que o Erevos é feito, cada um com o texto da sua licença. Veja [Licença](#licence).",
  "**A ready list of radio stations**: **Add a station** in the Collection's Radio now adds a country's most listened stations from Radio Browser at once, up to 100, with **Add the stations of this country**; the country is the phone's, and **Change** picks another. See [Collection](#collection).": "**Uma lista pronta de estações de rádio**: **Adicionar uma estação** no Rádio da Coleção agora adiciona de uma vez as estações mais ouvidas de um país do Radio Browser, até 100, com **Adicionar as estações deste país**; o país é o do telefone, e **Mudar** escolhe outro. Veja [Coleção](#collection).",
  "**A new look to start with**: Erevos, newly installed, starts in Glass (Panes), Modernist, System, My color in sky blue, the phone's letters and square messages. A look you chose before stays as it was. See [Appearance](#appearance).": "**Uma aparência nova para começar**: o Erevos recém-instalado começa com Glass (Painéis), Modernist, Sistema, Minha cor em azul-céu, a letra do telefone e mensagens quadradas. Uma aparência escolhida antes fica como estava. Veja [Aparência](#appearance).",
  "**Modules names only what Erevos has**: under **Settings** → **General**, **Modules** no longer lists Nostr, Matrix and XMPP, which are in Erevos+.": "**Módulos nomeia só o que o Erevos tem**: em **Configurações** → **Geral**, **Módulos** não nomeia mais Nostr, Matrix e XMPP, que estão no Erevos+.",
  "**The guide tells only of what Erevos has**: in Erevos, the user guide no longer speaks of Matrix, XMPP and the chats with other Nostr apps, which are in Erevos+. See [Erevos or Erevos+, and betas](#updates).": "**O guia fala só do que o Erevos tem**: no Erevos, o guia não fala mais de Matrix, XMPP e das conversas com outros apps Nostr, que estão no Erevos+. Veja [Erevos ou Erevos+, e betas](#updates).",
  "**Meeting someone in one tap**: **New chat** now starts with two big buttons, **Scan their QR code** and **Show your QR code**; one of you scanning the other is enough, and the rest is under them. See [Chat through a relay](#relay).": "**Conhecer alguém com um toque**: **Nova conversa** agora começa com dois botões grandes, **Ler o código QR da outra pessoa** e **Mostrar seu código QR**; basta um de vocês ler o código do outro, e o resto fica embaixo. Veja [Conversar por um relay](#relay).",
  "**The panic button, found at once**: it is first, in red, in the **⋯** menu of the home screen, and holding down the lock at the top of the home screen opens it. See [Panic button](#panic).": "**O botão de pânico, na hora**: ele vem primeiro, em vermelho, no menu **⋯** da tela inicial, e segurar o cadeado no alto da tela inicial o abre. Veja [Botão de pânico](#panic).",
  "**New chat looks the same every time**: the two big buttons are always at the top; **How you connect now** shows only while something is missing, and says it in plain words; **Your contact link** and **Invite someone** are rows, with no second QR code button. See [Chat through a relay](#relay).": "**A nova conversa tem sempre o mesmo aspecto**: os dois botões grandes ficam sempre no alto; **Como você se conecta agora** só aparece enquanto falta algo, e diz isso em palavras simples; **Seu link de contato** e **Convidar alguém** são linhas, sem um segundo botão de código QR. Veja [Conversar por um relay](#relay).",
  "**One scan is all**: where your relay lets your phone invite, **Show your QR code** shows an invite for one person, so a phone new to Erevos joins your relay by itself as it scans it, typing nothing, and you are contacts at once; for someone else, tap **New QR code**. And with a relay, its queue is made by itself: **Create my relay queue** is there only to try again, should that fail. See [Chat through a relay](#relay).": "**Uma leitura basta**: onde o seu relay deixa o seu celular convidar, **Mostrar seu código QR** mostra um convite para uma pessoa, e assim um celular novo no Erevos entra sozinho no seu relay ao ler o código, sem digitar nada, e vocês já são contatos; para outra pessoa, toque em **Novo código QR**. E com um relay, a fila dele é criada sozinha: **Criar minha fila no relay** fica só para tentar de novo, se isso falhar. Veja [Conversar por um relay](#relay).",
  "**Video calls take about half the data**: a video call over the internet goes through the call relay, so that neither side sees the other's address; its picture is now held to 1 Mbps, which on a phone looks much the same. A call on the same network is not held back.": "**Chamadas de vídeo usam cerca de metade dos dados**: uma chamada de vídeo pela internet passa pelo relay de chamadas, para que nenhum dos lados veja o endereço do outro; a imagem agora é limitada a 1 Mbps, o que no celular parece quase igual. Uma chamada na mesma rede não é limitada.",
  "**A stranger's message shows only its words**: a message request, from someone who has only your contact link, shows only what it says until you accept it. Its photos and files wait, not taken, and its links show no preview. See [Chat through a relay](#relay).": "**A mensagem de um desconhecido mostra só as palavras**: uma solicitação de mensagem, de alguém que só tem o seu link de contato, mostra só o que diz até você aceitá-la. Fotos e arquivos esperam sem ser baixados, e os links não mostram prévia. Veja [Conversar por um relay](#relay).",
  "**Photos sent as files say nothing of where they were taken**: a photo sent with **File** (JPEG, PNG, GIF or WebP) goes without where and when it was taken and the phone, as a photo does; a GIF sent as a photo keeps moving, now without its hidden notes.": "**Fotos enviadas como arquivos não dizem onde foram tiradas**: uma foto enviada com **Arquivo** (JPEG, PNG, GIF ou WebP) vai sem onde e quando foi tirada e sem o celular, como uma foto; um GIF enviado como foto continua se mexendo, agora sem suas notas ocultas.",
  "**A word of care over a stranger's first messages**: if a message request asks for a code, a PIN, a password or money, promises easy money, or its name looks like one of your contacts', **Be careful** says so above it. Erevos looks for this on your phone only, and blocks nothing. See [Chat through a relay](#relay).": "**Um aviso sobre as primeiras mensagens de um desconhecido**: se uma solicitação de mensagem pede um código, um PIN, uma senha ou dinheiro, promete dinheiro fácil, ou o nome parece o de um dos seus contatos, **Cuidado** avisa acima. O Erevos procura isso só no seu celular, e não bloqueia nada. Veja [Conversar por um relay](#relay).",
  "**Tor finds its own way through**: under **Bridges**, **Automatic** tries Tor straight, then the obfs4 bridges, then Snowflake, then your own, until one connects, and remembers for 30 days the one that worked on Wi-Fi and on mobile data. **My network is watched** makes it never try straight, and **Check my connection** says whether Tor connects, and how, never your address. See [Through Tor](#tor).": "**O Tor acha o caminho sozinho**: em **Pontes**, **Automático** tenta o Tor direto, depois as pontes obfs4, depois o Snowflake, depois as suas, até uma conectar, e lembra por 30 dias a que funcionou no Wi-Fi e nos dados móveis. **Minha rede é vigiada** faz ele nunca tentar direto, e **Verificar minha conexão** diz se o Tor conecta, e como, nunca o seu endereço. Veja [Pelo Tor](#tor).",
  "**The bar at the top stays**: on the home screen, the bar with Erevos and its buttons no longer scrolls away with the list, and in SMS chats, as in those of the other networks, the name of the chat, its calls and who is online stay at the top while the messages scroll, as in Erevos's own chats.": "**A barra de cima fica no lugar**: na tela inicial, a barra com o Erevos e os botões dele não rola mais junto com a lista, e nos chats de SMS, como nos das outras redes, o nome do chat, as chamadas dele e quem está online ficam no alto enquanto as mensagens rolam, como nos chats próprios do Erevos.",
  "**A simpler field in Matrix and XMPP chats**: under it there is only **+**, for photos, files and the rest, and the microphone; the chat's settings are under **⋯** at the top.": "**Um campo mais simples nos chats Matrix e XMPP**: embaixo há só **+**, para fotos, arquivos e o resto, e o microfone; as configurações do chat ficam no alto, em **⋯**.",
  "**Adding a contact with 8 digits**: **Pair with a code** on **New chat** lets one phone show a code of 8 digits and the other type it, said aloud or read off the screen, and you are each other's contacts, with no QR code or link to pass. The code never leaves the phones, and whoever guesses gets 3 tries. See [Chat through a relay](#relay).": "**Adicionar um contato com 8 dígitos**: **Emparelhar com um código** em **Nova conversa** deixa um telefone mostrar um código de 8 dígitos e o outro digitá-lo, dito em voz alta ou lido na tela, e vocês ficam contatos um do outro, sem código QR nem link para passar. O código nunca sai dos telefones, e quem tenta adivinhar tem 3 tentativas. Veja [Conversar por um relay](#relay).",
  "**A voice not your own**: in a contact's chat details, **Change my voice** sends your voice messages in that chat **Deeper** or **Higher**, as long as you spoke. The change is made on your phone before the message goes, so your own voice never leaves it. On Android 10 and later, and in browsers that make Opus themselves. See [Chat through a relay](#relay).": "**Uma voz que não é a sua**: nos detalhes da conversa com um contato, **Mudar minha voz** envia suas mensagens de voz nessa conversa **Mais grave** ou **Mais aguda**, com a mesma duração. A mudança é feita no seu telefone antes de a mensagem sair, então sua própria voz nunca sai dele. No Android 10 e posteriores, e em navegadores que fazem Opus sozinhos. Veja [Conversar por um relay](#relay).",
  "**A word of care under a short password**: setting the password of a space or the PIN of hidden chats, Erevos now says when it is short: someone who breaks into the phone's own security could guess it on computers of their own. A phrase of 4 or 5 words is far safer. It still takes a short one. See [Password lock](#lock).": "**Um aviso abaixo de uma senha curta**: ao definir a senha de um espaço ou o PIN das conversas ocultas, o Erevos agora avisa quando ela é curta: quem quebrar a segurança do próprio telefone poderia adivinhá-la em computadores próprios. Uma frase de 4 ou 5 palavras é muito mais segura. Ainda assim aceita uma curta. Veja [Bloqueio com senha](#lock).",
  "**Groups that end**: a public group can now be a burner group, for one event. Under **It ends**, choose after a day, 3 days or 7 days, and when its time is up every member's Erevos deletes it, with its messages, photos and files, and its link stops working. See [public groups](#public-groups).": "**Grupos que terminam**: um grupo público pode agora ser descartável, para uma ocasião. Em **Termina**, escolha depois de um dia, 3 dias ou 7 dias, e quando o tempo acaba o Erevos de cada membro apaga-o, com as mensagens, fotos e ficheiros, e o link deixa de funcionar. Veja [Grupos públicos](#public-groups).",
  "**A photo to see once**: under **+** in a chat or a group, **Photo to see once** sends a photo that never shows in the chat, and **Camera, to see once** one you take then. They see it once, on its own, kept out of screenshots where the phone allows, and as it closes it is deleted from their phone. It cannot be forwarded or saved. See [Chat through a relay](#relay).": "**Uma foto de visualização única**: em **+** em uma conversa ou em um grupo, **Foto de visualização única** envia uma foto que nunca aparece na conversa, e **Câmera, visualização única** uma que você tira na hora. Eles a veem uma vez, sozinha, sem capturas de tela onde o telefone o permite, e ao fechar é apagada do telefone deles. Não pode ser encaminhada nem salva. Veja [Conversar por um relay](#relay).",
  "**Threads in a contact's chat too**: hold a message and choose **Reply in thread**, as in a group. The thread shows alone and what you send there answers it; **n answers in the thread** under a message opens it. See [Chat through a relay](#relay).": "**Tópicos também na conversa com um contacto**: mantenha premida uma mensagem e escolha **Responder no tópico**, como num grupo. O tópico aparece sozinho e o que enviar ali responde-lhe; **n respostas no tópico** sob uma mensagem abre-o. Veja [Conversar por um relay](#relay).",
  "**A voice message in words**: hold a voice message and choose **In words**, and your phone writes out what was said, in about a hundred languages, Greek among them. The first time it downloads a speech model of 268 MB, once you say so; then everything is done on your phone, and neither the sound nor its words leave it. On Android. See [Chat through a relay](#relay).": "**Uma mensagem de voz em palavras**: segure uma mensagem de voz e escolha **Em palavras**, e o telefone escreve o que foi dito, em cerca de cem idiomas, entre eles o grego. Na primeira vez ele baixa um modelo de voz de 268 MB, quando você disser; depois tudo é feito no seu telefone, e nem o som nem as palavras dele saem do aparelho. No Android. Veja [Conversar por um relay](#relay).",
  "**Translate a message**: hold a message and choose **Translate**, and your phone translates it into your language, between Greek, English, German, Spanish, French and Italian. The first time for a language it downloads its translation models, of 60 to 95 MB each, once you say so; then everything is done on your phone, and neither the message nor its translation leave it. On Android. See [Chat through a relay](#relay).": "**Traduzir uma mensagem**: segure uma mensagem e escolha **Traduzir**, e o seu celular traduz para o seu idioma, ou para o inglês, entre grego, inglês, alemão, espanhol, francês e italiano. Na primeira vez para um idioma ele baixa os modelos de tradução dele, de 60 a 95 MB cada, quando você mandar; depois tudo acontece no seu celular, e nem a mensagem nem a tradução saem dele. No Android. Veja [Conversar por um relay](#relay).",
  "**Phones nearby carry for each other from the start**: **Carry messages for others**, under **Nearby, with no internet** on **New chat**, is now on until you turn it off, so a message that cannot reach its relay finds more phones to take it there. What this phone carries is sealed: it cannot read it, nor tell who it is from or for. See [Chat with a nearby phone](#nearby).": "**Celulares por perto levam mensagens uns dos outros desde o início**: **Levar mensagens de outras pessoas**, em **Perto, sem internet** na tela **Nova conversa**, agora fica ativado até você desativar, então uma mensagem que não chega ao relay dela encontra mais celulares para levá-la. O que este celular leva vai criptografado: ele não consegue ler, nem saber de quem é ou para quem. Veja [Conversar com um celular por perto](#nearby).",
  "**Last seen is when they closed Erevos**: with **Say when I open and close Erevos** on, closing Erevos, or its hidden chats, now tells those you told while it was open when it closed, so their **last seen** is that time, not when they last heard from you. And you show online only while the chats they talk to you in are open: not while your hidden chats are open instead. See [Chat through a relay](#relay).": "**Visto por último é quando fecharam o Erevos**: com **Avisar quando eu abrir e fechar o Erevos** ligado, fechar o Erevos, ou as conversas ocultas dele, agora avisa quem foi avisado enquanto estava aberto quando ele fechou, então o **Visto por último** deles é esse horário, não a última vez que souberam de você. E você só aparece online enquanto as conversas em que falam com você estão abertas: não enquanto as suas conversas ocultas estão abertas no lugar delas. Veja [Conversar por um relay](#relay).",
  "**Sign in at another relay**: under **Sign in with LPHL** on New chat, **Sign in at another relay…** takes another relay's address, and the card signs in there with the accounts that relay takes; one that takes none says so, and its operator can give you an invite. See [Chat through a relay](#relay).": "**Entrar em outro relay**: embaixo de **Entrar com LPHL** em Nova conversa, **Entrar em outro relay…** recebe o endereço de outro relay, e o cartão faz o login lá com as contas que esse relay aceita; um que não aceita nenhuma avisa, e quem cuida dele pode te dar um convite. Veja [Conversar por um relay](#relay).",
  "**Post-quantum, all the way**: between two phones on this Erevos, every message of a chat is now also locked with a fresh ML-KEM key, a new one every few dozen messages, not only at the start. So someone who records your messages today and has a quantum computer one day still cannot read them. By itself, with nothing to turn on; not in groups.": "**Pós-quântico do começo ao fim**: entre dois celulares com este Erevos, cada mensagem de uma conversa agora também é criptografada com uma chave ML-KEM nova, trocada a cada poucas dezenas de mensagens, não só no começo. Assim, quem grava suas mensagens hoje e um dia tiver um computador quântico continua sem conseguir lê-las. Sozinho, sem nada para ligar; não nos grupos.",
  "**The Collection asks for your password**: where the space has a password, the Collection asks for it each time it opens, and again after Erevos was away more than 30 seconds; a fingerprint or face works too. See [Collection](#collection).": "**A Coleção pede sua senha**: onde o espaço tem senha, a Coleção pede a senha toda vez que abre, e de novo quando o Erevos ficou fora por mais de 30 segundos; impressão digital ou rosto também servem. Veja [Coleção](#collection).",
  "**Messenger in its case**: in Erevos+, Messenger can now be used in its case instead of by Erevos: Meta's own Messenger page, as on a computer, closed in by Erevos with the same sign-in. Only Meta's sites load in it, links out open in your browser without Facebook's tracking marks, nothing of the sign-in stays in it once closed, and calls work in it. Choose it on the Messenger screen under **How Messenger is used here**; its chats are then not in Erevos's lists and Erevos does not notify of them. Through Tor, if Messenger goes through Tor, and then without calls.":
    "**O Messenger na sua capa**: no Erevos+, o Messenger pode agora ser usado na sua capa em vez de pelo Erevos: a própria página do Messenger da Meta, como num computador, fechada pelo Erevos com a mesma sessão. Só carregam os sites da Meta, as ligações para fora abrem no teu navegador sem as marcas de rastreio do Facebook, nada da sessão fica nela depois de fechada, e as chamadas funcionam nela. Escolhe-o no ecrã do Messenger em **Como o Messenger é usado aqui**; as suas conversas não estão então nas listas do Erevos e o Erevos não avisa delas. Através do Tor, se o Messenger passa pelo Tor, e então sem chamadas.",
  "**Messenger chats you read stay read**: a Messenger chat you marked read right after Erevos+ started, while Messenger was still connecting, no longer comes back as unread; a chat whose last message is yours, sent from Messenger's own app or the web, is read; and encrypted chats you read in Messenger's app or on the web are read here too.":
    "**As conversas do Messenger que leste ficam lidas**: uma conversa do Messenger marcada como lida logo após o Erevos+ arrancar, enquanto o Messenger ainda se ligava, já não volta a ficar por ler; uma conversa cuja última mensagem é tua, enviada da app do Messenger ou da web, está lida; e as conversas cifradas que leste na app do Messenger ou na web ficam lidas aqui também.",
  "**Messenger in its case fits the phone, and Facebook's feed is a tap away**: in Erevos+, Messenger in its case is now laid out at the phone's width, so it reads without zooming in, and shows under Erevos's own bar, in its colours, with **←** back to Erevos and **Facebook** to see Facebook's feed in the same page. Facebook also has a card of its own in the **Services** window, beside Messenger. See [Messenger](#messenger).":
    "**O Messenger na sua capa cabe no telemóvel, e o feed do Facebook está a um toque**: no Erevos+, o Messenger na sua capa fica agora à largura do telemóvel, para se ler sem ampliar, e aparece sob a barra do próprio Erevos, com as suas cores, com **←** para voltar ao Erevos e **Facebook** para ver o feed do Facebook na mesma página. O Facebook tem também um cartão próprio na janela **Serviços**, ao lado do Messenger. Vê [Messenger](#messenger).",
  "**Messenger in its case asks for the PIN once**: in Erevos+, what Meta's page keeps now stays in the case between openings, apart from every other page, so Meta knows your phone again and no longer asks for the PIN of your encrypted chats each time you open it. It goes when you sign out of Messenger, or when another account opens the case. See [Messenger](#messenger).":
    "**O Messenger na sua capa pede o PIN só uma vez**: no Erevos+, o que a página da Meta guarda fica agora na capa de uma abertura para a outra, à parte de qualquer outra página, para que a Meta reconheça o teu telemóvel e deixe de pedir o PIN das tuas conversas encriptadas sempre que a abres. Apaga-se quando terminas a sessão do Messenger ou quando outra conta abre a capa. Vê [Messenger](#messenger).",
  "**Messenger in its case wears your whole look**: in Erevos+, Meta's own Messenger page in its case now takes your look: its colours, dark or light as Erevos is, the shape of your bubbles (round, square or a line), your text size, your style's letters, and what lies behind your screens (a wallpaper, Neon's grid, Paper's lines and the others), and it changes with your look even while it is open. A photo of your own stays in Erevos: there the page shows a soft gradient instead. Where Meta changes its page, parts of it may keep Meta's look. See [Messenger](#messenger).":
    "**O Messenger na sua capa veste toda a tua aparência**: no Erevos+, a própria página do Messenger da Meta na sua capa assume agora a tua aparência: as suas cores, escura ou clara como o Erevos, a forma dos teus balões (redondos, quadrados ou uma linha), o tamanho do texto, as letras do teu estilo e o que está por trás dos teus ecrãs (um fundo, a grelha do Neon, as linhas do Paper e os outros), e muda com a tua aparência mesmo enquanto está aberta. Uma foto tua fica no Erevos: aí a página mostra em vez dela um degradê suave. Onde a Meta mudar a sua página, algumas partes podem manter a aparência da Meta. Vê [Messenger](#messenger).",
  "**Messenger in its case tells you of new messages**: in Erevos+, when you use Messenger in its case, Erevos now tells you of its new messages as it does of other chats, even if you never opened the case. A chat with messages not read shows on home until it is read, and tapping it opens it in the case; while the case is open, Erevos tells of nothing, as the page shows it. See [Messenger](#messenger).":
    "**O Messenger na sua capa avisa-te de mensagens novas**: no Erevos+, quando usas o Messenger na sua capa, o Erevos agora avisa-te das suas mensagens novas como das outras conversas, mesmo que nunca tenhas aberto a capa. Uma conversa com mensagens por ler aparece no início até ser lida, e um toque abre-a na capa; enquanto a capa está aberta, o Erevos não avisa, porque a página já o mostra. Vê [Messenger](#messenger).",
};
